WordHunterWoW_QuestEN[38499] = { title = "Strange New Ores", description = "You smell that, smith? Ahhhh... that there's the smell of opportunity.\n\nDalaran's taken us to some strange new shores, filled with mysterious metals. I'm tethered to my shop here, but you... you've got the freedom to explore and mine at will.\n\nBring me something interesting, and we'll see what we can make with it.", objectives = "Obtain 10 Leystone Ore.", progress = "Come up with anything interesting?", completion = "Fascinating..." }
WordHunterWoW_QuestEN[38500] = { title = "Leysmithing Mastery", description = "Well, now that we have the flux we can put it to work and see how it goes. Why don't you take a crack at it this time and make some gauntlets for me. I'll observe your work... from a distance.", objectives = "Follow Alard Schmied's recipes in your Blacksmithing recipe list to build some Handcrafted Leystone Gauntlets.", progress = "Did it work? I haven't heard an explosion yet.", completion = "Excellent work! This new flux may do wonders for other craftable materials as well." }
WordHunterWoW_QuestEN[38501] = { title = "Hatecoil Hammerwork", description = "There may be a way to jump-start our research into leystone.\n\nI've heard reports of naga camps down in Azsuna. If they've been in Azsuna for long enough, their smiths have certainly started experimenting with leystone themselves.\n\nBe on the lookout for some leystone armor on the naga... ideally something more elaborate than a bracer.", objectives = "Obtain a Masterwork Hatecoil Breastplate and a pair of Masterwork Hatecoil Pauldrons.", progress = "I still marvel at how quickly those things can swim in plate armor.", completion = "Of course! They've found their way around the welding problem by simply crafting their armor out of one solid piece of metal.\n\nThe shoulderpads I should have figured out on my own, but their work on the breastplate really is remarkable.\n\nHere, let me jot down a few patterns so you can make these yourself." }
WordHunterWoW_QuestEN[38502] = { title = "The Methods of the Nightfallen", description = "I have a theory, {name}.\n\nHave you encountered the nightfallen elves of Azsuna? They descend from the Highborne, and the accomplishments of Highborne smiths are legendary.\n\nThese fallen elves do a bit of arcane tinkering, crafting sentries to patrol their camps.\n\nBring me a memory core from one of their constructs. Who knows what manner of smithlore might lie within!", objectives = "Obtain an Ancient Sentry Construct Memory Core.", progress = "Hopefully we can extract something useful.", completion = "If my guess is correct, the answer to our welding problem lies within this core." }
WordHunterWoW_QuestEN[38503] = { title = "7.0 Stormheim - Treasure 020 - Helheim - ZTO", description = "", objectives = "" }
WordHunterWoW_QuestEN[38504] = { title = "Shrine of the Bear Twins", description = "", objectives = "" }
WordHunterWoW_QuestEN[38505] = { title = "Engineers: Not COMPLETELY Useless", description = "Unfortunately, I have no idea how to access any information within this core. But I know someone who does.\n\nHead over to \"Like Clockwork\", the engineering shop three doors down from here. Timofey Oshenko owes me a favor. He should be able to extract the memory out of the core.", objectives = "Bring the Ancient Sentry Construct Memory Core to Timofey Oshenko in Dalaran.", progress = "You're here from Alard's shop? What does that musclehead want now?", completion = "Oh, a memory core? One moment." }
WordHunterWoW_QuestEN[38506] = { title = "Chicken Scratch", description = "I think I have just the thing to extract the information from this core for you.\n\n<Timofey loads the core into the hopper of a clearly goblin-made machine, then covers his ears.>\n\nYou may wish to avert your eyes, blacksmith.", objectives = "Bring the Ancient Highborne Data Printout to Professor Pallin in Dalaran.", progress = "Highborne! Ancient Highborne! What an amazing find!", completion = "...is what I would say if we weren't floating directly above the ancestral home of the Highborne. You need this translated or something?" }
WordHunterWoW_QuestEN[38507] = { title = "Secrets of Leysmithing", description = "I could spend hours poring over the details of this fascinating manuscript!\n\n...is what I would say if this weren't the simplest of tasks for someone of my skill level. It's about something called \"Leysmithing\". Here.\n\n<The gnome scribbles down a translation on the back of the scroll.>\n\nThere it is, word-for-word. Bring me something interesting next time.", objectives = "Bring the Leysmithing Guide to Alard Schmied in Dalaran.", progress = "Did you find the engineering shop?", completion = "I hadn't even thought far enough ahead to realize you'd need this to be translated, too. Good thinking.\n\nSee, this is why I keep adventurers like you around the shop." }
WordHunterWoW_QuestEN[38508] = { title = "Shrine of the Bear Twins - Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[38509] = { title = "7.0 Stormheim - Treasure 021 - Helheim - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
