WordHunterWoW_QuestEN[38512] = { title = "Oakleaf", description = "", objectives = "" }
WordHunterWoW_QuestEN[38513] = { title = "The Highmountain Smiths", description = "I think we've gone as far as we can go with what I know, {name}.\n\nThe tauren of Highmountain must have some smiths among their ranks. See if you can find out how to further progress our leysmithing abilities from them.", objectives = "Speak with Barm Stonebreaker in Highmountain.", completion = "You, outsider, think yourself worthy of our wisdom?" }
WordHunterWoW_QuestEN[38514] = { title = "You Are Not Worthy", description = "You wish me to teach you how to strengthen your crafts? We do not simply share the secrets of our trade with outsiders who ask for them.\n\nWe do, however, respect craftsmanship and discipline.\n\nLet's see your hammerwork. Our greenhorn trainees use those small anvils over there. Craft your best pair of gauntlets so I may judge your work.", objectives = "Use your blacksmithing skill to craft a pair of Leystone Gauntlets for Barm.", progress = "I'm waiting, outsider.", completion = "The craftsmanship is good, but the quality is feeble at best.\n\n<Barm snaps the gauntlets in half and throws them to floor>\n\nYou have proven yourself worthy of my tutelage however." }
WordHunterWoW_QuestEN[38515] = { title = "Nature Provides", description = "This is interesting, it says that leystone reacts violently with anything it views as a contaminant. Our foreign-mined flux was enough to cause the small explosion.\n\nLocal ingredients, however, have learned to coexist with leystone. Up in Highmountain, an herb called foxflower grows that can be turned into a suitable flux.\n\nGo and gather some foxflower that we can turn into a usable flux.", objectives = "Obtain 10 Foxflower.\n\nIf you are not an herbalist, you can purchase Foxflower on the Auction House, or you can obtain it from another player.", progress = "How goes the search for foxflower?", completion = "Excellent work. Let's get these turned into flux right away." }
WordHunterWoW_QuestEN[38516] = { title = "7.0 Stormheim - Treasure 022 - Helheim - ZTO", description = "", objectives = "" }
WordHunterWoW_QuestEN[38517] = { title = "Tayla's Rescue", description = "", objectives = "" }
WordHunterWoW_QuestEN[38518] = { title = "From One Master to Another", description = "Now young one, go back to your master\nin Dalaran and continue to practice your swing. We'll always be here if you wish to come back and learn more.", objectives = "Go back to Alard in Dalaran and share what you've learned from the Tauren.", completion = "I see, the strength of their work comes from the technique of their hammer strikes. Very interesting..." }
WordHunterWoW_QuestEN[38519] = { title = "Grayheft", description = "Our tribe regularly crafts legplates out of leystone. I will share our pattern with you... if you do me a favor.\n\nMy father fell to the drogbar several years ago, and they took his hammer as a trophy. That hammer was in my family for countless generations. Now, it languishes in the hands of the vile drogbar, Kubrul.\n\nI would very much like to have it back.", objectives = "Obtain Grayheft, Ancient Hammer of the Highmountain Tauren from Kubrul within the Deep Roads cavern.", progress = "I have no patterns for helms or boots.\n\nA tauren who cannot survive a few blows to the hoof has no place in battle. Boots are of little use to us.\n\nA helm is a coward's armor. I am sorry if this offends you, but it is true.\n\nLegplates, however, do play a vital role. I will gladly share this pattern with you, once you bring me my father's hammer.", completion = "Thank you, <name>.\n\nThank you." }
WordHunterWoW_QuestEN[38521] = { title = "Tayla's Rescue - Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[38522] = { title = "Not Just Weapons and Armor", description = "You know, we aren't just limited to armorsmithing and weaponsmithing. I regularly make chisels for the scribes, crucibles for the alchemists, and even thimbles for the tailors.\n\nThey should sew in full plate gauntlets if they're really all that worried about their poor little thumbs.\n\nAnyhow, I have a recipe I think an adventurer like you might be interested in. Let's try it out.", objectives = "Craft 4 Hard Leystone Bars and 24 Hard Leystone Nails.", progress = "Let's get to work. I think you'll enjoy this.", completion = "Let me take those bars, make a few adjustments and...\n\nTa da! Hoofplates for your mount!" }
WordHunterWoW_QuestEN[38523] = { title = "Leystone Hoofplates", description = "Here, bring these hoofplates to Mei Francis, down at the mounts and pets store, to get your mount properly shod.\n\nI'll share the pattern when you return.", objectives = "Approach Mei Francis in Dalaran while mounted to have your Leystone Hoofplates fitted.", completion = "Now that Mei's fit the plates to your mount, you should be able to put them on easily yourself.\n\nOh, and before I forget, here's the pattern. Enjoy!" }
WordHunterWoW_QuestEN[38524] = { title = "Felsmith Nal'ryssa", description = "Word has been circulating in smithing circles about a pair of Illidari blacksmiths that have been doing exciting work out on the demon-infested front lines of Suramar. I'd follow up myself, but anything described as \"demon-infested\" is a little too exotic for my tastes.\n\nI just make the armor. I prefer not to wear it.\n\nYou, though... you could follow up on this tip. Be on the lookout for Nal'ryssa. From what I hear, she's a hell of a smith.", objectives = "Report to Felsmith Nal'ryssa in Suramar.", completion = "You here to lend us a hand?" }
WordHunterWoW_QuestEN[38525] = { title = "Part of the Team", description = "You're a blacksmith?\n\n<The elf looks down at your hammer.>\n\nStill working in leystone, are you? I might be able to help you out.\n\nAlliances out here are hard-won. You've got a pretty face, but that's no guarantee that you aren't working for the demons. I can't afford to trust you yet.\n\nDon't come back until you're caked in demon's blood. Then we'll talk smithing.", objectives = "Slay 40 demons within Felsoul Hold.", completion = "That'll do." }
WordHunterWoW_QuestEN[38526] = { title = "Smith Under Fire", description = "You lack recipes for boots?\n\nWhat, were you trained by a tauren or something?\n\nHurry up, then. We probably have a few minutes before the demons attack again. Here's a pattern - show me your work.", objectives = "Follow Felsmith Nal'ryssa's instructions to craft Leystone Boots.", progress = "Watch your step out here on the front lines. This isn't your peaceful floating city's blacksmithing shop.", completion = "Not bad, <class>. You know how to swing a hammer." }
WordHunterWoW_QuestEN[38527] = { title = "Nal'ryssa's Technique", description = "Listen, {class}. We need smiths like you to carry on the traditions of the Illidari, should we fail in our crusade against the Legion. You are ready to learn.\n\nBring me materials. Lots of them. When you return, we will have much to discuss.", objectives = "Obtain 60 Leystone Ore and 60 Felslate.", progress = "Are you ready to learn?", completion = "Good. Now let's get to work." }
WordHunterWoW_QuestEN[38528] = { title = "Leystone's Potential", description = "As I'm sure you've deduced, all of the leystone recipes you know can be improved.\n\nBy learning to harness leystone's true potential, you can reduce the amount of material you use and still yield an equivalent result. Here, I'll show you.\n\nWe'll start, as one does, with the humble bracer. This particular piece of armor benefits from the addition of brimstone runes. See for yourself.", objectives = "Use Felsmith Nal'ryssa's technique to craft a set of Masterwork Leystone Armguards.", progress = "Keep it up, <class>.", completion = "Solid work.\n\nLeystone is a fickle metal. Its armguards benefit from the addition of brimstone, but to improve the production of shoulderpads? Enchanting dust. Helms benefit from uncarved gemstones. And so on." }
WordHunterWoW_QuestEN[38529] = { title = "7.0 Stormheim - Treasure 023 - Weeping Bluffs - ZTO", description = "", objectives = "" }
WordHunterWoW_QuestEN[38530] = { title = "The Firmament Stone", description = "When working with felslate and demonsteel, one must use special equipment. Specifically, an anvil hard enough to withstand the energy given off when felslate is hammered.\n\nUrael and I no longer possess such an anvil. But your friends, the Highmountain tauren, do.\n\nGain access to the Firmament Stone, their sacred anvil, and we can start working with demonsteel again.", objectives = "Speak with Barm Stonebreaker in Highmountain.", completion = "You have returned, <name>. Have you come for more training?\n\nWhat? The Firmament Stone?\n\n\n\nThat's another matter entirely." }
WordHunterWoW_QuestEN[38531] = { title = "Leystone Mastery", description = "Smiths that seek access to the Firmament Stone must first prove complete mastery over leystone.\n\nCraft an entire set of Leystone Armor, then submit it to me for inspection. Thala can provide you with an armor stand.", objectives = "Speak with Thala Steeltotem to purchase a Leystone Armor Stand, then hang all eight pieces of Leystone Armor on it.", progress = "Remember, <name>: I do not tolerate sloppy work.", completion = "<The tauren carefully looks over your handiwork, brows furrowed.>\n\nYou've learned some things, I see.\n\nVery well. You have succeeded." }
WordHunterWoW_QuestEN[38532] = { title = "Maw of Souls: Hammered By The Storm", description = "Your hammer looks weak, and would probably break upon striking the Firmament Stone.\n\nThe vrykul master blacksmiths of old were known for the strength of their hammers. The only way to get our hands on such a hammer would be to go where vrykul go when they die. To the Maw of Souls.\n\nThe goddess that resides over that realm is named Helya. She hoards the trinkets they bring for her own desires.\n\nDefeat her and you may be able to acquire such a hammer.", objectives = "Go to the Maw of Souls and recover an Ancient Vrykul Hammer.", progress = "Were you able to get your hands on one?", completion = "<Barm examines the hammer, turning it slowly in his hands.>\n\nNow THIS is a hammer!" }
WordHunterWoW_QuestEN[38533] = { title = "Tribal Knowledge", description = "First, however, you'll need proper patterns for demonsteel armor. While access to the stone is earned through hard work and perseverance, access to our recipes is limited to the trusted members of our tribe.\n\nPerhaps you should seek another smith if you wish to discuss demonsteel patterns.", objectives = "Report back to Felsmith Nal'ryssa in Suramar.", completion = "I wouldn't expect the tauren to part with their recipes easily. We are not quite as... bull-headed as they are, but even our recipes will come at a price.\n\nStill, you have earned access to the Firmament Stone, and proven the path to another great anvil, should Urael and I need it.\n\nYou have earned this recipe, as a token of our thanks." }
WordHunterWoW_QuestEN[38534] = { title = "Demonsteel Armguards", description = "", objectives = "The armguards you've made are impressive, but you can provide the same level of protection without wasting so much raw material.\n\nHere, let me show you." }
WordHunterWoW_QuestEN[38535] = { title = "Brimbil's Journey", description = "", objectives = "" }
WordHunterWoW_QuestEN[38536] = { title = "Demonsteel Waistguard", description = "", objectives = "Excellent smithing.\n\nNow, allow me to show you a trick I use to conserve resources." }
WordHunterWoW_QuestEN[38537] = { title = "Demonsteel Pauldrons", description = "", objectives = "Your anvilwork is to be commended, but the recipe you're using is unnecessarily wasteful.\n\nTry this instead." }
WordHunterWoW_QuestEN[38538] = { title = "Demonsteel Boots", description = "", objectives = "We don't tend to smith many boots up here, but even I can tell that you're using too much metal for the sole.\n\nHere's a way to cut back on your resource costs." }
WordHunterWoW_QuestEN[38539] = { title = "Demonsteel Gauntlets", description = "", objectives = "The Illidari certainly do like to waste ore, don't they?\n\nYou should craft them this way instead. You'll thank me later." }
WordHunterWoW_QuestEN[38540] = { title = "Demonsteel Helm", description = "", objectives = "Don't tell Thala and Barm, but I do keep a few helm patterns around, mainly for amusement and decoration.\n\nTake a look at this one. You'll get similar results with much less need for raw material." }
WordHunterWoW_QuestEN[38541] = { title = "Demonsteel Greaves", description = "", objectives = "Now that you've done it the easy way, try this.\n\nIt's more difficult, but it will save you loads of materials." }
WordHunterWoW_QuestEN[38542] = { title = "Demonsteel Breastplate", description = "", objectives = "The amount of ore you're wasting on that pattern is simply unacceptable. We should conserve wherever possible: it's better for the land and easier on the pocket.\n\nPlease, use this plan instead." }
WordHunterWoW_QuestEN[38543] = { title = "FLAG: Demonsteel Armguards", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38544] = { title = "FLAG: Demonsteel Waistguard Crafted", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
