WordHunterWoW_QuestEN[38552] = { title = "Lord Hal'shara's Tomb", description = "The tomb, I've found it.", objectives = "Raid the tomb." }
WordHunterWoW_QuestEN[38557] = { title = "Vignette: Invasion Point: Devastation", description = "", objectives = "" }
WordHunterWoW_QuestEN[38558] = { title = "See Ya Later, Oscillator", description = "Those jawless mooks are actually trying to salvage parts from our ship! They can't possibly appreciate superior gnomish technology... Perhaps its shiny nature is appealing to their simple inclinations.\n\nIn any case, I need a crystal oscillator for our new transponder. It's the shiniest part of the whole system, they're bound to have it set aside somewhere!", objectives = "Collect the Crystal Oscillator.", progress = "Did you find the oscillator?", completion = "<Overspark examines the crystal carefully.>\n\nYep, still shiny." }
WordHunterWoW_QuestEN[38559] = { title = "Worthy of the Stone", description = "You have nothing more to prove to me, {name}. Your training is complete.\n\nOnly a very small herd of smiths have earned the right to the Firmament Stone. You should speak with Muirn Ironhorn, who maintains vigil over our sacred stone. He will tell you what to do next.", objectives = "Speak with Muirn Ironhorn.", completion = "A new face? It's been years...\n\nThis is the Firmament Stone. Memorize her curves. Learn her intricacies. If you truly wish to push your smithing skill to the next level, I predict that you will be spending a lot of time at her side." }
WordHunterWoW_QuestEN[38560] = { title = "Garrison Campaign: The Bane of the Bleeding Hollow", description = "Commander, now that we've had time to get scouts all over the jungle we have heard some news near Zeth'Gol.\n\nIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.\n\nYou know what they say about \"the enemy of my enemy...\" We should collect their tracking maps and try to find the killer first!", objectives = "Collect tracking maps to find the location of the killer." }
WordHunterWoW_QuestEN[38561] = { title = "Garrison Campaign: The Warlock", description = "Commander, you have a visitor. One of Gul'dan's warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.\n\nI suggest you speak with him immediately.", objectives = "Speak with the warlock at Lion's Watch in Tanaan Jungle.", completion = "I was too late to give you the message. I am truly sorry. These poor shamans... if only I had known sooner!\n\nGul'dan has prepared everything for his ritual. He will use the cipher and his own fel magic to corrupt an elemental lord and use it to sunder the elemental link to the land. This will cause a massive upheaval across Draenor!" }
WordHunterWoW_QuestEN[38562] = { title = "Secrets of the Sargerei", description = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun since Teron'gor's original assault. Now suddenly the Sargerei attacked and blew open a hole into one of the underhalls.\n\nCorruption leaks from that breach. We must investigate!", objectives = "Locate and stop the source of corruption underneath Auchindoun.", completion = "More of my ancestors' souls plundered by Gorefiend! This must end once and for all. Gorefiend must be put down!" }
WordHunterWoW_QuestEN[38563] = { title = "Flower-Pickers and Potion-Quaffers", description = "Now that we know the foxflower flux is safe to use, we can start stocking it. That being said, I don't particularly feel like picking flowers. Do you feel like picking flowers? Didn't think so.\n\nGo talk to the alchemists and herbalists across the way. I'm sure we can set up some sort of work order arrangement.", objectives = "Speak with Linzy Blackbolt and Kuhuine Tenderstride to secure a work order for Foxflower Flux.", progress = "Have you spoken with the alchemists and herbalists yet?", completion = "Now that that's all taken care of, we can move on to improving our recipes." }
WordHunterWoW_QuestEN[38564] = { title = "A Sweet Bargain", description = "Reading over this research, I found an interesting method that I'd like you to try.\n\nThe method would require us to chill the metal to sub-freezing temperatures during the pre-tempering phase. Simple water quenching won't do.\n\nGood thing you can't walk two steps in this city without bumping into a frost mage! See if you can recruit one for the shop, {name}.", objectives = "Find a frost mage in Dalaran to chill your quenching trough.", completion = "Well done, <name>. Now let's put her to the test!" }
WordHunterWoW_QuestEN[38565] = { title = "The Sargerei Menace", description = "This attack surprised our defenders. Forces are marshalling to push them out, but it will take some time for them to arrive.\n\nAny Sargerei you can slay will make retaking this area much easier commander.", objectives = "Slay 12 Sargerei." }
WordHunterWoW_QuestEN[38566] = { title = "A United Force", description = "The paladins of Azeroth must stand united behind a single leader. With Tirion's passing, you are the one most worthy to wear the mantle of Highlord.\n\nIf you agree to accept this duty, inscribe your name into the Libram of Ancient Kings and I will address the masses on your behalf.\n\nThe Order of the Silver Hand is reborn, with you as its champion!", objectives = "Establish the Order of the Silver Hand using the Libram of Ancient Kings.", progress = "Yes, Highlord?", completion = "We've done it, Highlord <name>.\n\nThe Order of the Silver Hand is reborn!" }
WordHunterWoW_QuestEN[38567] = { title = "Garrison Campaign: War Council", description = "Your garrison is in an uproar. Warchief Vol'jin himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle.\n\nThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting...", objectives = "Speak with Warchief Vol'jin inside the Town Hall of your garrison.", completion = "<The Warchief studies a map of Tanaan Jungle and its surroundings, his brow creased with worry.>\n\nAh, Commander <name>! Voice of da Horde in Draenor. Ya done well here, bringin' da fight ta our enemies. Thrall tells me ya exceed his every expectation.\n\nIt be time ta finish dis. Are ya ready?" }
WordHunterWoW_QuestEN[38568] = { title = "We Need a Shipwright", description = "Whatever be left of da Iron Horde be fallin' back ta Tanaan Jungle, where Gul'dan is turnin' them into sumthun' even worse. A frontal assault be suicide.\n\nBut da seas be open. If we attack by both land an' sea, Gul'dan got ta fall back somewhere. {name}, it be time ta build a shipyard!\n\nWe need local resources. Go to da Iron Docks. Gazlowe's boys are already there. Gather any equipment ya find, and see if ya can recruit us a proper Horde Shipwright!", objectives = "Travel to the Iron Docks and speak with Sammy Fivefingers. Your Garrison Flight Master can provide transport.", completion = "Commander! I was hoping some backup would arrive. This place is going crazy. The Iron Horde retreated from the Foundry and now, under Gul'dan's orders, they're using these docks to flee to Tanaan.\n\nBut my people found something that might interest you, if you act fast..." }
WordHunterWoW_QuestEN[38569] = { title = "Clearing the Docks", description = "We need to get control of this situation. We thought these docks would be all but abandoned. Instead, Gul'dan has ordered the Iron Horde to retreat to Tanaan, and many are using this harbor to make their getaway.\n\nWe need to clear a path for your salvage team. Lay waste to them! Every foe we slay here is one less convert for Gul'dan's wretched demon-worshipping army.You will receive:", objectives = "Kill 1 Iron Horde orcs and 50 ogron." }
WordHunterWoW_QuestEN[38570] = { title = "Derailment", description = "Some orcs have spoken out against Gul'dan, and they've been taken prisoner. One of them is what you'd call an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" This guy's good. Designed all these docks, as well as the big dreadnaughts you fought around Shattrath.\n\nIf my scouts are right, he's in a prison train as we speak... And I betcha he'd be willing to defect!\n\nGather up some explosives and meet Durotan next to the train to the south.", objectives = "Collect Explosive Charges and a Detonator.", progress = "Commander, it's you! Good, I need someone steady at my back.", completion = "We confirmed that Solog Roark is aboard this prison train, but it's locked up tight. Oh - you brought explosives? Hmph. Those goblin friends of yours are always prepared.\n\nLet's bust this box open and convince that shipwright to join our cause..." }
WordHunterWoW_QuestEN[38571] = { title = "The Train Gang", description = "My warriors will surround and cover the train car. Hit the detonator to blow open the doors.\n\nI will speak to Roark and convince him to defect to our cause. He built all of this - he's our best hope for building a shipyard of our own.\n\nIf this doesn't work, execute him on the spot. The last thing we need is someone rebuilding the Iron Fleet.", objectives = "Use the detonator to blow open the prison train, and convince Roark to join your cause.", completion = "Lower your weapon, stranger. Blackhand is dead and our new \"Warchief\" just signed my death sentence. It looks like I'm going mercenary.\n\nYou want to build a shipyard? Then you want me." }
WordHunterWoW_QuestEN[38572] = { title = "Hook, Line, and... Sink Him!", description = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place.\n\nBut I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar.\n\n<Roark spits.>\n\nGul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", objectives = "Use a Blackrock Grapple to reach Knar's bunker. Slay him to obtain Roark's Shipyard Blueprints.", progress = "I will rebuild.", completion = "<Solog Roark takes in the view of his harbor one final time.>\n\nWe built it all for nothing, <class>. Gul'dan will claim whatever your troops do not destroy.\n\nNext time, I will build something that will last." }
WordHunterWoW_QuestEN[38573] = { title = "Nothing Remains", description = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people.\n\nYou and your Frostwolf allies still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!\n\nLet your people know I am coming.", objectives = "Report back to Vol'jin at your garrison.", completion = "Ah, ya found us a shipwright? Good! Ya followers be eager ta take on da open seas." }
WordHunterWoW_QuestEN[38574] = { title = "All Hands on Deck", description = "Let's put dis \"Iron Shipwright\" ta work, commander. If we ta take Tanaan from both land an' sea, we gonna need a shipyard. Work wit' Roark an' make it happen!\n\nHe be surveyin' tha land along tha road west of Frostwall.", objectives = "Construct a Level 1 Shipyard for your garrison.", progress = "I'll need building supplies, commander. Can't build docks of ice and snow.", completion = "<Solog Roark scans the horizon.>\n\nThis will do. It's a good deepwater harbor. We can gut that old warship down there to make your first transport. Moving supplies up and down these cliffs will be a chore, but they'll give us additional security in case we're attacked.\n\nWe'll make it work. Are you ready to get building?" }
WordHunterWoW_QuestEN[38575] = { title = "Beachhead", description = "", objectives = "" }
WordHunterWoW_QuestEN[38576] = { title = "We Meet at Light's Hope", description = "With you on our side, I know the Legion will fall! But before we march on the Broken Isles, we must put Highlord Tirion to rest.\n\nThere is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel.\n\nPaladins the world over are on their way to the ceremony. I know Tirion would want you there most of all.", objectives = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", completion = "It is fitting that you are here.\n\nTime and again, you have fought to save our world. Now, I fear I must ask you to undertake an even greater act of service." }
WordHunterWoW_QuestEN[38577] = { title = "The Battle for the West", description = "Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.\n\nI have received word that Durotan has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.", objectives = "Go to the Iron Front and speak with Durotan.", completion = "Now you see what we face here. We will keep as much pressure here as we can so your base can remain free to attack all over the jungle." }
WordHunterWoW_QuestEN[38578] = { title = "A Message of Terrible Import", description = "Your scout... he got me out of that hellish place. Fel orcs surprised us out in the jungle and dragged us up the mountain. They tortured us... killed all but me. I fear one of us may have given up our secret before the end.\n\nI must ask you to go to the home of our order. Speak with Lagar, my leader, tell him... tell him Gul'dan knows.", objectives = "Go to the Vault of the Earth and speak with Lagar the Wise.", progress = "This is most unfortunate.", completion = "We will speak more of this later, but thank you." }
WordHunterWoW_QuestEN[38579] = { title = "Vignette: Xanzith the Everlasting", description = "", objectives = "" }
WordHunterWoW_QuestEN[38580] = { title = "Vignette: Overlord Ma'gruth", description = "", objectives = "" }
WordHunterWoW_QuestEN[38581] = { title = "The Battle for the West", description = "Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.\n\nI have received word that Exarch Maladaar has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.", objectives = "Go to the Iron Front and speak with Exarch Maladaar.", completion = "Now you see what we face here. We will keep as much pressure here as we can so your base can remain free to attack all over the jungle." }
WordHunterWoW_QuestEN[38582] = { title = "To Old Friends", description = "I sense a powerful dark presence here, {name}, but it is not of Xavius. This feels too familiar.\n\nI sense a druid's touch here, a druid twisted by the shadow of the Nightmare.\n\nWe must deal with this threat if we are to find Xavius. I will take to the skies and lend you my aid.\n\nFind this corrupted druid and cut down his tainted and twisted plants.", objectives = "Kill 50 Corrupted Creatures in Moonrest.", completion = "Know this, <name>. You did the only thing you could.\n\nWhen a mortal has become corrupted by the nightmare, there is no return. Only death will set them free." }
WordHunterWoW_QuestEN[38583] = { title = "Max-level Choice Tracker: Tanaan 6.2 - Group - Throne of Kil'jaeden", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38584] = { title = "Max-level Choice Tracker: Tanaan 6.2 - Group - Throne of Kil'jaeden", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38585] = { title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Make no mistake; This is the most dangerous region in Tanaan.\n\nGather together a war party and assault the Throne of Kil'jaeden before the Legion gains a foothold here!", objectives = "Defeat the Shadow Council at the Throne of Kil'jaeden in Tanaan Jungle.", completion = "Welcome back, commander. Our scouts just returned with word of your success.\n\nWell done!" }
WordHunterWoW_QuestEN[38586] = { title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Make no mistake; This is the most dangerous region in Tanaan.\n\nGather together a war party and assault the Throne of Kil'jaeden before the Legion gains a foothold here!", objectives = "Defeat the Shadow Council at the Throne of Kil'jaeden in Tanaan Jungle.", completion = "Word of your success has already been passed on by our scouts. \n\nLok'tar!" }
WordHunterWoW_QuestEN[38587] = { title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Remember the first war, we know the destruction the legion can cause if they are unchecked.\n\nHead to the Throne of Kil'jaeden and let's put an end to this invasion before it can begin.", objectives = "Assault the Shadow Council forces at the Throne of Kil'jaeden in Tanaan Jungle." }
WordHunterWoW_QuestEN[38588] = { title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. We know the destruction the legion can cause if they are left unchecked.\n\nHead to the Throne of Kil'jaeden and let's put an end to this invasion before it can begin.", objectives = "Assault the Shadow Council forces at the Throne of Kil'jaeden in Tanaan Jungle." }
