WordHunterWoW_QuestEN[38591] = { title = "Treasure: Ravager Sack", description = "", objectives = "" }
WordHunterWoW_QuestEN[38592] = { title = "6.2 Tanaan Max-level Choice Reward Summary: Group", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38593] = { title = "Treasure: Ravager Spear", description = "", objectives = "" }
WordHunterWoW_QuestEN[38594] = { title = "6.2 Tanaan Max-level Choice Reward Summary: Group", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38595] = { title = "Malfurion's Fury", description = "The loss of Cenarius to the nightmare is a devastating blow to us all.\n\nThough Malfurion's rage is justified, his hatred of Xavius has burned for centuries and I fear that his blind rage will be used as a weapon against him.\n\nMay Elune guide us in our search for him, lest we have yet another friend to mourn today.", objectives = "Speak with Ysera to search for Malfurion.", completion = "Oh, <name>...\n\nWhat is becoming of this precious land?" }
WordHunterWoW_QuestEN[38596] = { title = "TRACKING Nightmare 02", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", objectives = "Defeat Botanist Darkgrove(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet." }
WordHunterWoW_QuestEN[38597] = { title = "Vignette: Panther Saberon Boss", description = "", objectives = "" }
WordHunterWoW_QuestEN[38598] = { title = "TEST: Craft Some Legplates", description = "The Highmountain tauren craft their legplates piece-by-piece, then assemble them all at the end.\n\nSeems pretty slow and unnecessarily arduous if you ask me, but we should start here before making any efficiency improvements.\n\nHere's some leystone. I've added the recipe into your workbook, as well. Let's give this a shot!", objectives = "Use your Blacksmithing skill to craft a pair of Handcrafted Leystone Legplates." }
WordHunterWoW_QuestEN[38599] = { title = "Infrastructure Improvements", description = "Sir, we built a vehicle to take ya up to the Throne of Kil'jaeden but whenever we try a test flight the navigation system goes crazy!\n\nIn my expert opinion it's 'cause of that crazy demon magic the Iron Horde is playing around with up there.\n\nIf you could travel up there and place these telemetry beacons we can program the vehicle and give you a stable flight all the way up.\n\nJust be sure to have some friends with you, the demons up there look especially vicious!", objectives = "Place 5 G-X3 Telemetry Beacons.", completion = "Hey welcome back! The signal's coming in loud and clear and the ship's good to go!\n\nWhen you're ready to head back up just take the rocket for the fastest ride on Draenor! We set it up over near Gargash." }
WordHunterWoW_QuestEN[38600] = { title = "Vignette: Fel Saberon Shaman", description = "", objectives = "" }
WordHunterWoW_QuestEN[38601] = { title = "Treasure: Saberon Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[38602] = { title = "Treasure: Fel Spike", description = "", objectives = "" }
WordHunterWoW_QuestEN[38603] = { title = "Setting the Signal", description = "Sir, we built a vehicle to bypass the Horde camp and take you to the Throne of Kil'jaeden! There's one problem, the concentrated fel energy up there is causing the navigation system to go haywire!\n\nI'll need you to place some sensors along the edge of the summit. With them in place we can stabilize the flight controls.\n\nJust be sure to have some friends with you, the demons up there look especially vicious!", objectives = "Place 5 Pentangulate-o-tron 2000s.", completion = "Welcome back!\n\nWe're getting a strong feed from those sensors! The crew locked the navigation system on to the signal and everything should be good to go!\n\nWe set the machine up next to Skyguard Thann." }
WordHunterWoW_QuestEN[38604] = { title = "Vignette: Saberon Shaman", description = "", objectives = "" }
WordHunterWoW_QuestEN[38605] = { title = "Vignette: Saberon Blademaster", description = "", objectives = "" }
WordHunterWoW_QuestEN[38607] = { title = "Gates of Valhallas", description = "Escaping the grasp of Helya is no small feat. You may prove to be a worthy warrior after all.\n\nSkovald has entered Valhallas; you are running out of time. Legion has corrupted the minds of the Skovald's men. A battalion of unworthy vrykul is attempting to enter the portal to Valhallas.\n\nThe giants that protect the gates are fighting a losing battle. There is no end to Legion's onslaught.\n\nSpeak with the dragon, Vehdir, inside the gates near the portal. He will aid you on your next task.", objectives = "Speak with Vedhir.Escaping the grasp of Helya is no small feat. You may prove to be a worthy warrior after all.\n\nSkovald has entered Valhallas; you are running out of time. Legion has corrupted the minds of the Skovald's men. A battalion of unworthy vrykul is attempting to enter the portal to Valhallas.\n\nThe giants that protect the gates are fighting a losing battle. There is no end to Legion's onslaught.\n\nSpeak with the dragon, Vehdir, inside the gates near the portal. He will aid you on your next task.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38608] = { title = "Reclaim Valhallas", description = "", objectives = "" }
WordHunterWoW_QuestEN[38609] = { title = "Vignette: Iron Tunnel Foreman", description = "", objectives = "" }
WordHunterWoW_QuestEN[38610] = { title = "Arauk Nashal 70:JP3 - Gates of Valhallas -Tracking quest - Titan Vehicle - Bonus Objective", description = "", objectives = "" }
WordHunterWoW_QuestEN[38611] = { title = "Will of the Thorignir", description = "In the summit of storms the dragons await. Born of the gods, they will test your will. \n\nThey roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit.\n\nA friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!", objectives = "Meet with Dread-Rider Cullen outside of Hrydshal to begin the trial of the Thorignir.", completion = "These vrykul are so boring! Why does Nathanos send me on missions like this? Does he really think the Aegis is here?\n\nI hope you've come to stir up some trouble." }
WordHunterWoW_QuestEN[38612] = { title = "A Grapple a Day", description = "So some old magic vrykul is helping us out? I guess that's good, but this trial of yours might be tricky. You see, the only way up that mountain, is through those big walls.\n\nYou know, the ones with the mean-looking drakes on them.\n\nI scouted a bit, but couldn't get too far without those drakes trying to make lunch out of poor Duchess. The vrykul have them trained, which can't be good.\n\nI say we sneak in. I managed to snag a few grapple launchers earlier. Grab one and meet me outside the city walls.", objectives = "Pick up a Stormforged Grapple Launcher and meet Dread-Rider Cullen outside the wall of Hrydshal.", completion = "Yes, that should do quite nicely." }
WordHunterWoW_QuestEN[38613] = { title = "No Wings Required", description = "That thing looks like it's got the range to get us over the wall. There's a good spot to hook onto right past us - you should be able to spot it from here.\n\nOnce you're inside, do me a favor and see if you can distract the guards so I can slip through. I'll see what else I can find out about these vrykul.", objectives = "Use the Stormforged Grapple Launcher to launch over the wall at Hrydshal.", completion = "Those vrykul were so distracted seeing someone flying through their village, they never noticed me slip by. \n\nI hope that didn't get you too much unwanted attention." }
WordHunterWoW_QuestEN[38614] = { title = "To Weather the Storm", description = "When I was scouting this place out, I noticed the vrykul here are no strangers to the treacherous mountain path we're trying to get to. They've got some specialized equipment they're using, and if I were you I'd try to get my hands on some.\n\nYou'll want to find some climbing treads to keep your grip and an oiled cloak to keep you dry. They've also got these stones they carry to keep the lightning at bay, so you'll want to pick one of those up as well.", objectives = "Collect Climbing Treads, an Oiled Cloak, and an Enchanted Lodestone from Hrydshal.", progress = "Were you able to get all the gear you needed?", completion = "Well, the sizing might be a bit big, but I think you can make them work. \n\nThat path doesn't look pleasant, so it'll help to be prepared." }
WordHunterWoW_QuestEN[38615] = { title = "Impalement Insurance", description = "It looks like the elements aren't the only thing you'll need to worry about going up that path. Those harpoon launchers on the wall look pretty nasty, and unless we take them out first, they're likely to make short work of anyone trying to scale that path.\n\nThey're up on top of the walls, so you'll need to use that grapple launcher to get to them. Just try not to end up drake food!", objectives = "Grapple on top of the walls and dismantle 7 Tideskorn Harpoon Launchers atop in Hrydshal.", completion = "We won't have to worry about those scrap heaps anymore! \n\nIt looks like we've got a hitch in our plan though. That bridge was the only way up." }
WordHunterWoW_QuestEN[38616] = { title = "Built to Scale", description = "The vrykul around here seem to use scales from these drakes to fashion their armor. \n\nIf you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", objectives = "Collect Storm Drake Scales from the Stormwing drakes in Hrydhsal.", progress = "What have we here?", completion = "Good thinking. If the vrykul can use the drake scales for their armor, why not us? \n\nIt shouldn't be too tough to work this into something serviceable." }
WordHunterWoW_QuestEN[38617] = { title = "Another Way", description = "Wait, do you still have that grapple launcher? I think you can still get to the path if you can launch from the top of that tower. The gap doesn't seem too bad there.\n\nOf course, we'll have to take out the big guy out front first. He looks tough, but I think we have a chance if we can flank him.", objectives = "Defeat the Drekirjar Champion in Hrydshal, then climb to the top of the tower.", progress = "This should be a piece of cake!", completion = "What a fight! \n\nAnd here I thought this place would be boring." }
WordHunterWoW_QuestEN[38618] = { title = "Above the Winter Moonlight", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", objectives = "Grapple across from the tower and climb to the top of the mountain path.", completion = "You are here for the trial? I'm afraid you might be too late.\n\nThis battle with these Felskorn has taken its toll. I am too weak to grant you the power you seek...\n\nBut perhaps you may be able to help..." }
WordHunterWoW_QuestEN[38620] = { title = "Vignette: Pale Assassin", description = "", objectives = "" }
WordHunterWoW_QuestEN[38624] = { title = "Cry Thunder!", description = "You have proven yourself an ally of the Thorignir and we will lend you our strength. I would ask one last favor of our new champion, though. \n\nThe dragon who guided you to me awaits his vengeance against the vrykul. Together I wish for you to show these Drekirjar what it means to cross the Thorignir. Be they Felskorn or not, their malice has caused suffering to my brood. Their toll must be paid in blood.\n\nSpeak to Vethir when you are ready.", objectives = "Fly with Vethir and kill 150 of the God-King's allies in Hrydshal.", completion = "<The raven squawks, and Havi's voice fills your head>\n\nYou are indeed mighty, as the trial shows. \n\nBut valor is a different animal - one you think to tame?" }
