WordHunterWoW_QuestEN[38639] = { title = "Treasure: Swamp Blossom", description = "", objectives = "" }
WordHunterWoW_QuestEN[38640] = { title = "Treasure: Anti Pale Equipment", description = "", objectives = "" }
WordHunterWoW_QuestEN[38641] = { title = "The Temple of Elune", description = "Cenarius is in danger.\n\nIf his condition is not reversed soon, he will be lost to the Nightmare that threatens the Emerald Dream. To spare him that fate, we must have the Tears of Elune - the same relic you were sent here to retrieve.\n\nElune's temple is not far. Go there. Find Lyanis. Show her my seal and instruct her to release the tears into your custody.\n\nHurry, {name}. Time is short.", objectives = "Speak with Lyanis Moonfall at the Temple of Elune.\n\nProvided item:", completion = "You - you bear the mark of The Dreamer. Elune be praised!\n\nYou've arrived just in time, visitor. Shaladrassil's roots are at our doorstep..." }
WordHunterWoW_QuestEN[38642] = { title = "Vrykul Longboat", description = "", objectives = "" }
WordHunterWoW_QuestEN[38643] = { title = "A Village in Peril", description = "The corpse of Darcy Heathrow lies before you pierced by several arrows and knife wounds.\n\nIn one hand she clutches a note, written with a feeble hand, that reads:\n\n\"The dead march on Bradensbrook.\n\nHelp us, please!\"", objectives = "Speak to Mayor Heathrow at Bradensbrook.", completion = "We don't need any help, and we don't like strangers wanderin' around on our land." }
WordHunterWoW_QuestEN[38644] = { title = "The Farmsteads", description = "Forgive us, stranger. Mayor Heathrow has been under a lot of stress recently.\n\nI can't blame him: his own daughter, Penelope, has been missing for two days.\n\nIn fact, we could use information on several farmsteads to the south: Mayor Heathrow's house, Granny Marl's farm, and the Radcliffes' dock. Can you go check on the situation out there?\n\nHelp us, and perhaps the mayor's heart will soften.", objectives = "Check on the Heathrow house, Granny Marl's farm, and the Radcliffes' fishing dock.", progress = "How does it look out there?", completion = "I'm sorry for my suspicion earlier. We're all on edge with the recent attacks.\n\nI couldn't be more grateful to you and your friend.\n\nThanks to you, our situation is under control now. We've got a lot of rebuilding to do, but we'll survive." }
WordHunterWoW_QuestEN[38645] = { title = "Children of the Night", description = "I am no enemy to these people, but there is no convincing them of that.\n\nTheir village has come under attack by some very old friends of mine. Friends who are no longer... living.\n\nThere's no telling who or what controls them, but in life these noble soldiers would never engage in such acts. That's a mystery for another time.\n\nFor now, help me earn the trust of these villagers. Strike down the Black Rook enemies who are terrorizing their citizens.", objectives = "Kill 12 Risen Assassins, Black Rook Falcons, or Risen Hounds.", progress = "The attackers are night elves, yes, but they are not the same night elves I once knew.", completion = "Good. These innocent villagers have done nothing to deserve these attacks. You have done well to help them." }
WordHunterWoW_QuestEN[38646] = { title = "A Sight For Sore Eyes", description = "Do you see those ravenous birds flying above my farm? Vicious creatures are spreading their filth an' eatin' my crops.\n\nI'd get rid of them with my trusty gun, but my eyesight's gone downhill.\n\nTake this flare gun and mark them for me.\n\nOnce I get my sights on them, I'll make 'em scatter.", objectives = "Use Granny's Flare Gun to mark 6 Black Rook Falcons.", progress = "Heh? Is that you again?", completion = "Well love, we sure did take care of them! Thank you, <class>. Glad ta see I 'aven't lost my touch." }
WordHunterWoW_QuestEN[38647] = { title = "For the Corn!", description = "I've got a full summer's corn harvest just sittin' out in the field. I need some muscle to bring it in before the night elf raiders can destroy it.\n\nGet out there and bring me those crops, and I'll reward you handsomely.\n\nThe folks back in town need this food, and I sure as heck ain't eating rats for another winter.", objectives = "Collect 5 Barrels of Corn.", progress = "The corn isn't gonna gather itself.", completion = "All right, I'll get those barrels loaded up and delivered to the village in no time.\n\nThank you, <name>. There'll be a lot of full bellies because of you." }
WordHunterWoW_QuestEN[38648] = { title = "Black Rook Orders", description = "The letter is written in midnight ink:\n\n\"A demon invasion is imminent, but as long as the fires of Black Rook Hold blaze, we shall protect kaldorei lands. Kill any intruders who stand in our way.\"\n\n- K.R.\"\n\nPerhaps Jarod Shadowsong will want to see this.", objectives = "Return to Commander Jarod Shadowsong at Bradensbrook.The letter is written in midnight ink:\n\n\"A demon invasion is imminent, but as long as the fires of Black Rook Hold blaze, we shall protect kaldorei lands. Kill any intruders who stand in our way.\"\n\n- K.R.\"\n\nPerhaps Jarod Shadowsong will want to see this.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38649] = { title = "Silence in the City", description = "There is a troubling silence from Suramar City this day.\n\nOculeth just informed me that the teleporter to the Waning Crescent has gone dark. He is not able to reach Vanthir, nor am I.\n\nWhile I am hesitant to believe something dire has happened, I do feel this warrants investigation.\n\nSpeak with Oculeth and see if he can transport you to the Waning Crescent. We need to find out what happened.", objectives = "Speak to Chief Telemancer Oculeth.", completion = "Something is amiss. I can feel it in my bones." }
WordHunterWoW_QuestEN[38654] = { title = "Vignette: Giant Raptor", description = "", objectives = "" }
WordHunterWoW_QuestEN[38655] = { title = "Root Cause", description = "The massive roots of Shaladrassil are spreading a horrible corruption throughout the forest.\n\nIf we are to save Val'sharah, we will need to find a way to stop the encroachment of the world tree.\n\nIf you bring me enough corrupted root samples, I may be able to discover their secrets.", objectives = "Collect 30 Corrupted Root Samples.", progress = "Have you collected the root samples?", completion = "It is as I feared, <race>. This corruption is... irreversible.\n\nOur only course of action is to somehow find a way to fight it at its source." }
WordHunterWoW_QuestEN[38656] = { title = "Mark of the Demon", description = "The demonic rune glows in your hand, emanating dark power. A single word, inscribed in demon tongue, glows coldly... \n\n...GRAVAX...", objectives = "Return the Demonic Emblem to Isoraen Nightstar at the Temple of Elune.", completion = "I am impressed that you were able to defeat such a powerful demon. We are fortunate that you have lent us your aid." }
WordHunterWoW_QuestEN[38657] = { title = "Treasure: Swamp Sword", description = "", objectives = "" }
WordHunterWoW_QuestEN[38658] = { title = "Aid For the Wounded", description = "[PH] Many of our defenders have been gravely wounded on the battlefield. Take with you this moonstone and use it on our wounded allies on the battlefield. Heal their wounds and renew their courage against the forces of the enemy.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Revive 10 wounded allies by using the moonstone." }
WordHunterWoW_QuestEN[38659] = { title = "Val'sharah", description = "We recently received word from that the druid Malfurion Stormrage has identified the location of the next Pillar of Creation - the Tears of Elune.\n\nMalfurion awaits your arrival in Dalaran as soon as you are able, Highlord.", objectives = "" }
WordHunterWoW_QuestEN[38660] = { title = "Cleansing the Corruption", description = "All along the battlefield, the satyrs have erected dark totems that spread the corruption of the Emerald Nightmare upon the land.\n\nAs long as the Nightmare totems remain, we will not be able to hold back the corruption!\n\nIf you truly wish to aid us in the fight, destroy the totems that you encounter upon the battlefield.\n\nOur survival depends on it!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 6 Nightmare Totems on the Battlefield." }
WordHunterWoW_QuestEN[38661] = { title = "Nightmare Bombs", description = "[PH] The satyrs have taken to the skies on giant bats. From the air they rain down the corruption of the nightmare upon us.\n\nDisarm the nightmare bombs before they further corrupt the forest.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Revive 8 Nightmare Bombs on the Battlefield." }
WordHunterWoW_QuestEN[38662] = { title = "Tears for Fears", description = "The Tears of Elune are a sacred artifact, protected by my order for thousands of years. I tell you this so that you may understand the gravity of your request.\n\nThat said, Ysera is noble and wise and I trust in her guidance. You will find the tears in a vault at the eastern edge of the temple grounds.\n\nProceed with caution though, as that area has been overrun by demons.", objectives = "Retrieve the Tears of Elune.", progress = "Do you have the Tears of Elune?", completion = "Xavius has stolen our sacred artifact?\n\nElune, forgive me. I have failed you." }
WordHunterWoW_QuestEN[38663] = { title = "The Die is Cast", description = "Thanks to your efforts the temple is safe, for now.\n\nBut the Tears of Elune are stolen and Shaladrassil, the world tree that once protected this land, is now an instrument in the hands of our enemy. The Emerald Dream itself is being overrun by Nightmare.\n\nThe hearts of our people falter, their faith tested like never before. Return to Ysera with my report, {name}, such as it is.\n\nI shall plead with Elune with what time I have left here. May we somehow yet prevail.", objectives = "Speak with Ysera at the Grove of Cenarius.", completion = "This is dire news indeed, <name>.\n\nDraw upon your courage now, friend, for Azeroth needs her heroes more than ever before." }
WordHunterWoW_QuestEN[38664] = { title = "Tracking Quest: Saved Family 1", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38665] = { title = "Tracking Quest: Saved Family 2", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38666] = { title = "Tracking Quest: Eligible for Grumpy", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38667] = { title = "The Demon's Trail", description = "Xavius! How many times must I end that wretched satyr before he stays dead...\n\nWe must get to Shaladrassil and find Xavius before it is too late!\n\nMy wounds are grave, but they will heal... do not concern yourself with my safety. There is little time... we may already be too late...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Travel with Archdruid Malfurion Stormrage." }
WordHunterWoW_QuestEN[38668] = { title = "Our Last Hope", description = "Your jailor, Maiev Shadowsong, stands outside the open door to your cell. The leader of the Wardens has just finished removing your bonds.\n\nIn the distance, you can hear sounds of battle. The unmistakable stench of the Burning Legion wafts through the air.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Maiev Shadowsong in the Illidari Cellblock.Your jailor, Maiev Shadowsong, stands outside the open door to your cell. The leader of the Wardens has just finished removing your bonds.\n\nIn the distance, you can hear sounds of battle. The unmistakable stench of the Burning Legion wafts through the air.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38669] = { title = "Our Last Hope", description = "The Vault has fallen to the Burning Legion.\n\nIt pains me to say it, but all is lost, but for one glimmer of hope... YOU. Believe me when I say, I did NOT want to have to do this. However, it would seem I have no choice.\n\nHelp me, demon hunter, and I will grant you your freedom.", objectives = "Retrieve your new warglaives." }
WordHunterWoW_QuestEN[38670] = { title = "Goredome 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[38671] = { title = "Lost in Retreat", description = "Is this the end?\n\nOur beloved Malfurion. I saw him in the Dreamer's clutches, but Ysera was... changed. Twisted.\n\nShaladrassil, our mighty world tree, is corrupted beyond recognition.\n\nWe were forced to flee our home without our belongings. Some were heirlooms, sacred to us. Return them to me if you can, {class}, I beg you.", objectives = "Retrieve 5 Shadowfen Heirlooms in Shadowfen.", progress = "Have you retrieved them?", completion = "It is not much, but it is better than I could have hoped for. You have our gratitude." }
WordHunterWoW_QuestEN[38672] = { title = "Breaking Out", description = "We cannot fight our way out of the Vault alone.\n\nTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. \n\nFree them with haste. Their strength will be of great use to us.", objectives = "Free both Altruis the Sufferer and Kayn Sunfury.", progress = "<The lever seems to control the door.>", completion = "<Pull the lever.>" }
WordHunterWoW_QuestEN[38673] = { title = "The Wormtalon Crone", description = "A wicked coven of harpies have overtaken our village.\n\nIt was the twisting of the forest that forced us out of our village, but now that the harpies have moved in I fear that we may never be able to return.\n\nThe Wormtalon coven are led by a witch called Grelda the Crone. She has made her nest in a cave near our village.\n\nIf their leader is defeated, the remaining harpies will surely flee.\n\nSlay Grelda the Crone and we will be forever in your debt, <class>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Grelda the Crone." }
WordHunterWoW_QuestEN[38674] = { title = "Malfurion's Cure", description = "The cleansed Mooncaps glow radiantly in your hands as you lift them from the waters of the ancient moonwell.\n\nMender Onelle will need the Mooncaps in order to make a healing poultice for Malfurion's wounds.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver the Cleansed Mooncaps to Mender Onelle." }
WordHunterWoW_QuestEN[38675] = { title = "Heart of the Nightmare", description = "I know only that my husband is somewhere deeper in this twisted forest.\n\nHe is still alive, but it remains to be seen if he is whole.\n\n<Tyrande's expression hardens into a scowl as she peers at you.>\n\nElune herself cannot protect Xavius if he is not.", objectives = "Track Malfurion's path through the Nightmare.", completion = "No one is safe from this corruption." }
WordHunterWoW_QuestEN[38676] = { title = "7.0 Stormheim - Treasure 025 - Weeping Bluffs - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38677] = { title = "7.0 Stormheim - Treasure 026 - Weeping Bluffs - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38678] = { title = "Treasure: Bleeding Hollow Warchest", description = "", objectives = "" }
WordHunterWoW_QuestEN[38679] = { title = "Treasure: Jewel of the Fallen Star", description = "", objectives = "" }
WordHunterWoW_QuestEN[38680] = { title = "7.0 Stormheim - Treasure 027 - Weeping Bluffs - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38681] = { title = "7.0 Stormheim - Treasure 028 - Mountain Cave - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38682] = { title = "Treasure: Censer of Torment", description = "", objectives = "" }
WordHunterWoW_QuestEN[38683] = { title = "Treasure: Looted Bleeding Hollow Sack", description = "", objectives = "" }
WordHunterWoW_QuestEN[38684] = { title = "Reading the Leaves", description = "{name}, my friend. You must succeed where I have failed. You must find our dear Malfurion.\n\nAs the Nightmare consumes my thoughts, I hear the voices of these twisted trees. I must cling to sanity long enough to aid you.\n\nVenture into Ash'theran and bring me Corrupted Petals from the fallen denizens there.\n\nWith them, I might find your Archdruid while my mind is still my own.", objectives = "Collect 5 Corrupted Petals.", progress = "Ahh... the fear! The panic!\n\nI haven't the strength to fight much longer...", completion = "The waking world is slipping further and further from my mind. But on the vestiges of this corruption consuming my mind, I sense Malfurion!" }
WordHunterWoW_QuestEN[38685] = { title = "The Nameless King", description = "", objectives = "" }
WordHunterWoW_QuestEN[38686] = { title = "Treasure: Rune Etched Femur", description = "", objectives = "" }
WordHunterWoW_QuestEN[38687] = { title = "Close Enough to Touch", description = "He is near, {name}, I can feel it.\n\nWe must scour this place in search of my husband. I fear if we do not find him soon it will be too late.\n\nYou have been courageous throughout our search. I know you will not fail me now, {name}.\n\nThank you, and please hurry.", objectives = "Search for Malfurion within Shala'nir.", completion = "This cannot be!" }
WordHunterWoW_QuestEN[38688] = { title = "Hope Remains", description = "The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Tear of Elune to Archmage Khadgar in Dalaran." }
WordHunterWoW_QuestEN[38689] = { title = "Fel Infusion", description = "So many years of imprisonment has left us weak.\n\nThe Vault is overrun with demons.  Kill them and gather their souls to regain your strength.", objectives = "Infuse yourself with 100 energy from fallen demons.", completion = "The color has returned to your face, <name>." }
WordHunterWoW_QuestEN[38690] = { title = "Rise of the Illidari", description = "Look down there. We are vastly outnumbered.\n\nWe will need more allies on our side if we are to escape from here intact. Free the other Illidari imprisoned within the cells of this chamber.\n\nWe will need everyone to escape this place alive.", objectives = "Free 8 Illidari Prisoners.", progress = "Have you freed those you found in the cells?", completion = "We always knew the Illidari would be called upon to defend this world. It is why we sacrificed everything to become who... WHAT... we are." }
WordHunterWoW_QuestEN[38691] = { title = "Jarod's Mission", description = "Since Maiev chased after Gul'dan at the Vault of the Wardens, her sisters among the Wardens have been searching far and wide for her whereabouts.\n\nWith so few Wardens remaining, I volunteered to join the search. I hope I will find sign of her within Black Rook Hold.\n\nThe fortress will be well guarded, and I will need help to break through. Help me find her, and I will reward you handsomely.", objectives = "Speak to Jarod Shadowsong at Ravencrest Mausoleum.", progress = "Did you have any trouble getting here?", completion = "What does the Legion want with Ravencrest? He was dead and buried ten millennia ago." }
WordHunterWoW_QuestEN[38692] = { title = "Answering Aggression", description = "I weep for the Nightborne this day.\n\n<Silgryn gestures out the door.>\n\nElisande demonstrates the ultimate disdain for her people. So many lives... wasted!\n\nAll to relay a message: This is what happens to those who defy her.\n\n{name}, my friend, we must answer her. We must show her that she cannot slay her people without retribution.\n\nFight back, {name}.", objectives = "Kill 12 of Elisande's Forces in the Waning Crescent, Starcaller Retreat, and Siren's Vigil.", completion = "It had to be done." }
WordHunterWoW_QuestEN[38693] = { title = "Kill Feral Dogs", description = "You've done more than enough, <name>. My people and I can clean things up here.\n\nYou should return to town and report on our victory.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return to Anna Thornton at Barreltown." }
WordHunterWoW_QuestEN[38694] = { title = "Regroup", description = "These people may be able to hold out here, but I know for certain that we cannot.\n\nEvery moment we spend here places them in danger of Elisande's forces retaliating against us.\n\nWe need to move. We need to find a place to regroup and recover.\n\nFollow me. I think I know how we can get out of here.", objectives = "Escape Siren's Vigil.", completion = "Oculeth has anticipated our arrival. Good, one less thing to worry on." }
WordHunterWoW_QuestEN[38695] = { title = "Crackdown", description = "Thalyssra is right to be concerned!\n\nThe network has not responded to my attempts to re-establish connection with the Waning Crescent. I do not know what happened, but given the circumstances I believe it prudent to investigate in person.\n\n{name}, would you do the honors? I will send you as close to the Waning Crescent as I can.", objectives = "Investigate the events of the Waning Crescent.", progress = "Elisande... how could you?", completion = "Someone must have informed the Grand Magistrix of Vanthir's involvement in the rebellion. Such violence is...\n\nElisande... How could you?" }
WordHunterWoW_QuestEN[38696] = { title = "Vignette: Bleeding Hollow Horror", description = "", objectives = "" }
WordHunterWoW_QuestEN[38697] = { title = "The Sword of Truth", description = "Lord Ravencrest's army rises from the dead, but I believe they are controlled by Gul'dan's will.\n\nTake this - Lord Ravencrest's blade, Fal'shathil. It was known for a unique, magical quality. Those who gazed upon its mirrored blade found themselves unable to deny the truth.\n\nTake the blade and plant it in the ground. Attack the night elven ghosts near its light. Once they are weakened in its presence, perhaps they will regain their senses.", objectives = "Place Fal'shathil on the ground, then defeat Black Rook night elves within its holy light." }
WordHunterWoW_QuestEN[38699] = { title = "Competitive Exorcise", description = "Think you're good at sending demons back to the hell from whence they came? Show me!\n\nI once bagged 15 in under 10 minutes. Do better than that and there'll be brew money waitin' for ya.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 15 Burning Legion invaders in 10 minutes or less." }
WordHunterWoW_QuestEN[38700] = { title = "Vignette: Steelsnout", description = "", objectives = "" }
WordHunterWoW_QuestEN[38701] = { title = "Treasure: Strange Fruit", description = "", objectives = "" }
WordHunterWoW_QuestEN[38702] = { title = "Treasure: Dead Warrior's Helmet", description = "", objectives = "" }
WordHunterWoW_QuestEN[38703] = { title = "Treasure: Scout Rifle", description = "", objectives = "" }
WordHunterWoW_QuestEN[38704] = { title = "Treasure: Forgotten Iron Horde Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[38705] = { title = "Essence of Elements", description = "", objectives = "" }
WordHunterWoW_QuestEN[38707] = { title = "DEPRECATED", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[38708] = { title = "Purge the River", description = "", objectives = "" }
WordHunterWoW_QuestEN[38709] = { title = "Vignette: Cave Keeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[38710] = { title = "An Urgent Gathering", description = "A critical decision must be made, {name}.\n\nThe Legion devastated our forces at the Broken Shore. The mightiest army this world has ever known was reduced to cinders in moments.\n\nWe must gather those with the conviction to save our home. Travard of Tyr's Guard and Orik Trueheart have each made plans to do just that, but we must not let them walk alone.\n\nI ask that you seek them out and guide them to Krasus' Landing so that we may make this decision together.", objectives = "Gather Travard and Orik Trueheart, then meet Lord Maxwell Tyrosus at Krasus' Landing.", completion = "Thank you for helping us gather together, <name>. We must stand united." }
WordHunterWoW_QuestEN[38711] = { title = "The Warden's Signet", description = "The night elf was carrying a signet engraved with the crest of the Wardens.\n\nThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.", objectives = "Take the Warden's Signet to Jarod Shadowsong.\n\nProvided item:", completion = "<Jarod gazes at the ring for a long minute before closing his hands around it. He puts the ring in a pocket.>\n\nThis is Maiev's ring. She would never part with it.\n\nShe must be at Black Rook Hold!" }
WordHunterWoW_QuestEN[38712] = { title = "Houndmaster Ely", description = "", objectives = "" }
WordHunterWoW_QuestEN[38713] = { title = "The Crusade Calls", description = "((You have just finished the introduction sequence in Dalaran.))\n\nLord Maxwell Tyrosus of the Argent Crusade sent for you. He mentioned knowing of a weapon we could use against the Legion.\n\nAs much as I loathe their ilk, you should go to Krasus' Landing and speak with him. We need every advantage we can muster.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Lord Maxwell Tyrosus at Krasus' Landing.((You have just finished the introduction sequence in Dalaran.))\n\nLord Maxwell Tyrosus of the Argent Crusade sent for you. He mentioned knowing of a weapon we could use against the Legion.\n\nAs much as I loathe their ilk, you should go to Krasus' Landing and speak with him. We need every advantage we can muster.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38714] = { title = "Maiev's Trail", description = "The fortress grounds are just up ahead. There is a large area to search, but if we split up, I believe we can cover a lot of ground.\n\nSearch the prison cages, the forge, and the guard tower for any signs of Maiev. I will check the upper ramparts and meet you on the other side of the keep.", objectives = "Search the forge, the saber pens, and the guard tower.", progress = "We will give this area a thorough search.", completion = "Good work, <name>. There is no doubt that they have already moved Maiev into the prison cells beneath the tower." }
WordHunterWoW_QuestEN[38715] = { title = "The Rook's Guard", description = "Black Rook Hold is not the same place I knew. Its walls have crumbled, a ghostly echo of its former glory.\n\nIf Lord Ravencrest has returned, then surely he will have his former officers at his side.\n\nKester Farseeker, captain of the guard.\n\nTrelan Shieldbreaker, peerless master of maces.\n\nStarlys Strongbow, who could split arrows while blindfolded.\n\nIf we stand any chance of entering the tower itself, they must be eliminated.", objectives = "Kill Kester Farseeker, Trelan Shieldbreaker, and Starlys Strongbow.", progress = "Warriors and fighters came from across kaldorei lands to pledge loyalty to Master Ravencrest. We would have followed him to the ends of the earth.", completion = "Thank you, <name>. May their spirits be at peace." }
WordHunterWoW_QuestEN[38716] = { title = "Black Rook Hold", description = "Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest.\n\nThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.You will receive:", objectives = "Take the Warden's Signet to Jarod Shadowsong." }
WordHunterWoW_QuestEN[38717] = { title = "Black Rook Prison", description = "I did not come this far to lose her in the final moments.\n\nMaiev must be in the cells beneath Black Rook Hold.\n\nI scouted above, and the entrance to the prison is guarded by a fearsome jailor.\n\nI will sneak past and take out the guards inside. Defeat Araxxas, take the keys, and then meet me within.", objectives = "Kill Araxxas and collect the Prison Keys.", progress = "Do you have the keys?", completion = "Good, these keys should open any of the cells within the prison." }
WordHunterWoW_QuestEN[38718] = { title = "Kur'talos Ravencrest", description = "Lord Ravencrest was a fearless leader, a seasoned commander, a man of integrity and honor, a teacher, and a protector of his people.\n\nMalfurion, Illidan, Tyrande, and I... we were still young when he helped shape our destinies.\n\nThe sigil of his house was legendary. Observe, for a moment, the sigil over his former resting place and I shall tell you more of his legacy.", objectives = "Examine Ravencrest's Sigil.", completion = "The attacking spirits spoke of their lord and master. I fear the Legion has raised Lord Ravencrest to do their bidding. What price was paid for such a sinister revival, I do not know." }
WordHunterWoW_QuestEN[38719] = { title = "Illidari Freedom", description = "<The Illidari demon hunter is bleeding from several ghastly wounds. It appears he was left here to die.>\n\nWithin the prison are three of my... <cough>... comrades.\n\nWe were taken by surprise while scouting the area.\n\nI am not long for this world, but please, save them.", objectives = "Free Sirius Ebonwing, Cassiel Nightthorn, and Asha Ravensong.", completion = "The other Illidari did not make it, but I owe you my life. There is one thing I learned during my time in the prisons: the demons within Black Rook Hold must die." }
WordHunterWoW_QuestEN[38720] = { title = "No Reason to Stay", description = "Elisande's purge of the Waning Crescent came so swiftly that few could react. Many of my people are dead or taken.\n\nSome may have endured this atrocity. We need to make sure they are not left behind.\n\nI need you to search the houses nearby for any survivors. See that they flee before they are discovered. Reassure them that there is no reason to stay. \n\nNot here, not while Elisande's insanity reigns.", objectives = "Evacuate survivors in the Waning Crescent and Siren's Vigil.", progress = "Did you find anyone?", completion = "I see you managed to find some survivors. Good, that is a weight off my mind." }
WordHunterWoW_QuestEN[38721] = { title = "Lieutenant of the Tower", description = "All of your instincts were correct. Gul'dan raised Lord Ravencrest, and his ghostly army, from beyond the grave. Now, they serve the Legion, protecting secrets within the tower.\n\nAlthough Ravencrest commands from above, Lieutenant Desdel Stareye operates the prisons.\n\nHe tormented me these past few moons, but I did not yield.\n\n<Maiev runs a finger along her curved blade.>\n\nHis life must be ended.", objectives = "Kill Desdel Stareye.", completion = "Lord Stareye came from a noble house, but in war, he never came close to Ravencrest or my brother.\n\nNow that he is defeated, we can turn our attention to his commander.\n\nHowever, that will be no easy task. We must gather our strength before facing Lord Ravencrest himself." }
WordHunterWoW_QuestEN[38723] = { title = "Stop Gul'dan!", description = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens.\n\nGul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse.\n\nEven in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", objectives = "Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.", completion = "Excellent. You have absorbed the powers of these brutes. Look how strong you have grown!" }
WordHunterWoW_QuestEN[38724] = { title = "Brotherly Love", description = "Maiev will be somewhere in the prison. I found her discarded armor on my way here.\n\nLet's split up to search the cells more quickly.\n\nWe must find her.", objectives = "Find Maiev Shadowsong in Black Rook Prison.\n\nProvided item:", completion = "<Maiev's face is bruised, her lips cracked, and her body covered in scars. She looks thin and ragged, but she moves with purpose.>\n\nFor weeks they tried to break me. Amateurs!\n\nI kept my silence. I counted the minutes, measured their steps, and listened to the voices beyond my cell.\n\nI have been waiting for my chance to escape, and to strike back at my captors.\n\nNow, you bring my armor AND my blade. My salvation will be followed by bloodshed.\n\n<Maiev smiles.>" }
WordHunterWoW_QuestEN[38725] = { title = "Into the Foul Creche", description = "One of the demons that I interrogated revealed a particularly juicy bit of information. Apparently, there's an imp mother in the volcano that scribes Legion secrets.\n\nKor'vas has gone out to find that demon and bring those secrets back for us.", objectives = "Meet up with Kor'vas Bloodthorn at the Foul Creche.", completion = "<name>. I've found her." }
WordHunterWoW_QuestEN[38726] = { title = "Vignette: Magwia", description = "", objectives = "" }
WordHunterWoW_QuestEN[38727] = { title = "Stop the Bombardment", description = "Jace's wards are not going to hold out much longer. We need someone to go out there and make sure those Legion devastators are destroyed.\n\n<Kayn pointedly looks at you with his spectrally-enhanced vision.>", objectives = "Destroy the Legion Devastators.", completion = "True leadership is hard to come by. Leading from the front is an even rarer trait.\n\nWe are just about ready to assail Brood Queen Tyranna's command center." }
WordHunterWoW_QuestEN[38728] = { title = "The Keystone", description = "{name}, Brood Queen Tyranna is just ahead in the command chamber. The others already charged in. She has the Sargerite Keystone in her possession.\n\nFinally, the object of all our sacrifice is at hand.", objectives = "Kill Brood Queen Tyranna and take the Sargerite Keystone. Then, join the others down-below in the portal chamber.", progress = "<name>, are you ready?", completion = "Now that we have the keystone in our possession, there is just one last thing left to do..." }
WordHunterWoW_QuestEN[38729] = { title = "Return to the Black Temple", description = "Quickly, {name}, use the Sargerite Keystone.\n\nWe must get back to the Black Temple before it is too late!", objectives = "Use the Sargerite Keystone to activate the Fel Portal and return to the Black Temple.", completion = "<As you invoke the power of the Sargerite Keystone, the fel portal is suffused with an otherworldly energy.\n\nIt is time to return triumphant to the Black Temple and aid Lord Illidan in repelling the invading forces from Azeroth and Shattrath City.>" }
