WordHunterWoW_QuestEN[38737] = { title = "An End To War", description = "It appears that the great Ancient of War, Ironbranch, has fallen to the Nightmare.\n\nIt pains me greatly to ask this of you, but Ironbranch must be put to rest.\n\nIn life, he once stood vigil in Shala'nir as a protector of the world tree. In death, my dear friend is no more than a destructive weapon that will be used to cause even more violence.\n\nHe must be slain before he does more harm to Val'sharah.\n\nIn my heart, I know that he would thank you for this mercy...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Ironbranch." }
WordHunterWoW_QuestEN[38738] = { title = "7.0 Stormheim - Treasure 029 - Waterfall - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38739] = { title = "Treasure: Shaman Treasure", description = "", objectives = "" }
