WordHunterWoW_QuestEN[38743] = { title = "The Fate of Val'sharah", description = "Malfurion, my love.... My heart breaks for him, but I cannot follow where he goes.\n\nI have sworn myself to Elune, my goddess, to defend her temples and lands with all that I am. I cannot stand by while my order is in danger.\n\nMay she keep you in her graces, Malfurion.\n\n<Tyrande turns away, eyes glistening with tears.>", objectives = "Defend the Temple of Elune.", completion = "This shall be remembered as one of the darkest days in the history of our world. But hope remains. Elune's light has strengthened our resolve." }
WordHunterWoW_QuestEN[38744] = { title = "7.0 Stormheim - Treasure 030 - Statue - ZTO", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38745] = { title = "Hard Lessons", description = "Please understand, stranger, that I am a being of peace. I have discarded any vengeful nature long, long ago.\n\nIn my youth, however, many hard lessons were learned through discipline. When applied wisely and properly, discipline can be a great teacher and shaper of character.\n\nIt is in the spirit of wisdom and guidance that I would have you teach these harpies a memorable lesson.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Burn 5 Harpy Nests and Break 5 Harpy Eggs in the Wretched Grove." }
