WordHunterWoW_QuestEN[38759] = { title = "Set Them Free", description = "Cyana went down to the Molten Shore. She was going to help some of the demon hunters who came in through the gateway ahead of us. Instead, she got herself into trouble.\n\nThis inquisitor revealed they're being held prisoner by some new type of demon called a 'jailer'. The thing sucks the souls out of its victims. I doubt they can hold out much longer.", objectives = "Several of your demon hunters are in trouble. Get the Soulwrought Key to set them free.", progress = "Some of our demon hunters are missing. Did you see them back on the Molten Shore?", completion = "Their souls were being sucked dry by a jailer demon?\n\nThe Burning Legion in this place is far more powerful and brutal than we have ever seen before." }
WordHunterWoW_QuestEN[38760] = { title = "Treasure: Captain's Booty 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[38761] = { title = "Treasure: Captain's Booty 2", description = "", objectives = "" }
