WordHunterWoW_QuestEN[38763] = { title = "Stormheim - Vignette - Titan Vault", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38764] = { title = "Vignette: Murktide Alpha", description = "", objectives = "" }
WordHunterWoW_QuestEN[38765] = { title = "Enter the Illidari: Shivarra", description = "Our Shivarra demonesses are waiting at the Black Temple. It's a gamble bringing them here... they used to be part of the Burning Legion after all. But, they are some of the most powerful in Lord Illidan's arsenal.\n\n<Jace looks at you for a long moment.>\n\nI have a feeling that the ultimate sacrifice is going to have to be made in order to summon them in.", objectives = "Feed a powerful soul into the Legion Gateway Activator and then use it to summon in your Shivarra forces.", completion = "Grim. But demon hunters are no strangers to sacrifice. We have given everything to become what we are.\n\nThe Legion will fall. We await your orders, <name>." }
WordHunterWoW_QuestEN[38766] = { title = "Before We're Overrun", description = "The doomguard commander and his queen must be dealt with. His eredar are summoning in a huge number of reinforcements.\n\nWe need to put an end to him before the Legion overruns our new foothold up in the volcano!\n\nAs an added benefit, you can steal his demonic power.", objectives = "Slay Doom Commander Beliash and take his power for your own.", completion = "Already, the flow of demons from below has slowed to a trickle.\n\nI can sense the doom guard's energy. You have become more powerful." }
WordHunterWoW_QuestEN[38767] = { title = "Nightmaul", description = "", objectives = "" }
WordHunterWoW_QuestEN[38771] = { title = "Treasure: Book of Zyzzix", description = "", objectives = "" }
