WordHunterWoW_QuestEN[38776] = { title = "Treasure: Sacrificial Blade", description = "", objectives = "" }
WordHunterWoW_QuestEN[38777] = { title = "Leystone Deposit Sample", description = "This ore looks like nothing you've seen before.\n\nA mystical sheen moves through the metal in complex, unpredictable patterns. Your trainer in Dalaran would certainly like to see this.", objectives = "Bring the Leystone Deposit Sample to Mama Diggs in Dalaran.", progress = "What's that you've got there, boy?", completion = "It's so light. So pretty, too! Reminds me of elementium, a bit.\n\nIf you see any more ore like this, try and strike it with the grain. You'll waste much less of it." }
WordHunterWoW_QuestEN[38778] = { title = "Turn the Keys", description = "My roots wither... my branches die...\n\nThe Bonespeakers, they seek to silence the Runewood.  The runestones are the key...\n\nTurn the stones... release my bonds...", objectives = "Activate the Runestones within the Runewood.", progress = "My shackles remain...", completion = "So it was your footsteps I felt upon my woods as the runestones released their grip? \n\nYou have my thanks, outsider." }
WordHunterWoW_QuestEN[38779] = { title = "Treasure: Hidden BH Chest", description = "", objectives = "" }
WordHunterWoW_QuestEN[38780] = { title = "7.0 Val'sharah - River - Vignette: Thondrax - TRACKING - twh", description = "", objectives = "" }
