WordHunterWoW_QuestEN[38783] = { title = "7.0 Val'sharah - Treasure 018 - Andu'talah - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38784] = { title = "Leystone Seam Sample", description = "This ore has clearly absorbed some of the latent ley energies within the Broken Isles. It is cool to the touch, and reflects light in odd, playful angles.\n\nYour trainer in Dalaran should analyze this.", objectives = "Bring the Leystone Seam Sample to Mama Diggs in Dalaran.", progress = "What've ye brought me now?", completion = "Look at that! She's a lovely one, isn't she?\n\nTreat this type of ore with care, lad. No fat-muscle shoulder swings necessary - just a gentle tap on the right spot and you'll extract much more ore than a beginner." }
WordHunterWoW_QuestEN[38785] = { title = "Living Leystone Sample", description = "This is no normal leystone. It is much livelier, shimmering in complex, enthralling patterns. It is easy to stare at.\n\nYour trainer in Dalaran would certainly like to have a look at this.", objectives = "Bring the Living Leystone Sample to Mama Diggs in Dalaran.", progress = "Oh, my...", completion = "Now isn't that somethin'? You got this offa one of those rocky creatures down there?\n\nLooks like ye only brought me a bit o' the torso, though. Next time, make sure to get the arms and head too. Lots o' good meat in there." }
WordHunterWoW_QuestEN[38786] = { title = "Where Respect is Due", description = "Leystone is a sensitive ore. Our smiths can coax great power out of it, but as miners, we must treat it with respect, or else its power will retreat inward.\n\n<The tauren hands you what appears to be a GLASS mining pick.>\n\nThe next time you mine some leystone ore, use this pick. It will break if you strike too hard. THIS is the respect that leystone requires.", objectives = "Mine for leystone 35 times while using Ronos's Glass Pick.", progress = "You haven't broken my pick, have you?", completion = "You've learned much, <name>.\n\nStay a while. I have a story for you." }
WordHunterWoW_QuestEN[38787] = { title = "The Legend of Rethu Ironhorn", description = "A long, long time ago, a tauren by the name of Rethu entered this land. His exploits paved the road that all miners walk.\n\nIf you wish to learn more about mining, you must first learn about Rethu.", objectives = "Speak with Ronos Ironhorn to learn the tale of Rethu Ironhorn.", progress = "Listen well, <name>.", completion = "Echoes of Rethu's time in this land still remain, <name>. Be on the lookout for his influence when you are out in the field." }
WordHunterWoW_QuestEN[38788] = { title = "Treasure: Magic Brazier", description = "", objectives = "" }
WordHunterWoW_QuestEN[38789] = { title = "Rethu's Journal", description = "Tucked in between a few pieces of rubble, a scrap of paper catches your eye.\n\nMining carefully, you uncover the tattered remains of an old scroll. The tauren handwriting is archaic, but one word catches your eye:\n\n\"Rethu\".", objectives = "Bring the Torn Journal Page to Ronos Ironhorn in Highmountain.", progress = "Greetings, miner. What have you here?", completion = "This... this cannot be! A piece of Rethu's own mining log!\n\nLook here, miner... it details a leystone mining technique he was working on..." }
WordHunterWoW_QuestEN[38790] = { title = "Rethu's Pick", description = "This seam has been mined before - it bears the telltale diagonal ruts of a miner's pick.\n\nLooking down, that pick now lays on the ground - handle broken, pick-point dulled with use and years.\n\nCarved into the haft is a familiar name:\n\n\"Rethu\"", objectives = "Bring the Battered Mining Pick to Ronos Ironhorn in Highmountain.", progress = "What is that you hold, miner?", completion = "Rethu's own mining pick...\n\nWell, one of them, anyhow. Stories say he went through them almost weekly.\n\nStill, I've never seen one with my own eyes. Look at the wear on the blade, miner. The angles he used... the strength with which he struck: we could learn much from studying this artifact." }
WordHunterWoW_QuestEN[38791] = { title = "Rethu's Horn", description = "The corpse of the rocky beast yielded an unusual treasure: a battered chunk of tauren's horn.\n\nIt is clearly very, very old, but something about its color and curve reminds you of Ronos Ironhorn at the Ironhorn Enclave.", objectives = "Bring the Chunk of Horn to Ronos Ironhorn in Highmountain.", progress = "What... what is that, miner?", completion = "This... this could not be...\n\nThis is from a member my tribe, <name>. Where did you find this?\n\nOne of the first stories we ever learn about Rethu involves the day he lost his horn in battle. There is no way of knowing if this belonged to him but... but..." }
WordHunterWoW_QuestEN[38792] = { title = "Rethu's Lesson", description = "You... miner... let me see your pick a moment.\n\n<The tauren spirit eyes your mining equipment.>\n\nYou remind me of myself, when I once walked this land. Savor these moments, miner. They cannot last forever.\n\n<With a bow, the spirit disappears.>", objectives = "Report your encounter to Ronos Ironhorn in Highmountain.", completion = "You saw a spirit while out mining in the wilds?\n\nNo, I do not believe you. One mustn't spend too long out mining, it fatigues the mind. You must be seeing things.\n\nStill, something seems... different about you. You've learned something. Perhaps there's some truth to your tale after all..." }
WordHunterWoW_QuestEN[38793] = { title = "Rethu's Experience", description = "Miner... you... you know who I am?\n\nI see. That is good. My tribe continues to honor its roots.\n\nIf you return to the land of the Ironhorn tribe... let them know that they are looked upon with pride.", objectives = "Report your encounter to Ronos Ironhorn in Highmountain.", completion = "<The tauren listens as you describe your encounter with the spirit of Rethu Ironhorn.>\n\nI would not normally believe you, but... I can sense truth in your tale. You are a lucky miner.\n\nI am pleased to know that our ancestors look upon us with pride. We have chosen an admirable path.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[38794] = { title = "Rethu's Sacrifice", description = "Miner... speak with me a moment. I haven't much time in this place.\n\nI see you fight for your ore. I believe that is the most noble way to obtain your stone. It gives the land a fighting chance.\n\nStill, one mustn't be callous with their own life. Dig too deep, and the land will overcome you. No stone is worth the price I paid.\n\nBut that is a tale for another day...", objectives = "Report your encounter to Ronos Ironhorn in Highmountain.", completion = "The spirit of Rethu Ironhorn? Tell me everything he said.\n\nHe said he... dug too deep? I see. The Earthmother took him.\n\nThank you for coming to me, miner. This is a tale that the rest of the tribe must hear. We are all the wiser for it." }
WordHunterWoW_QuestEN[38795] = { title = "Felslate Deposit Sample", description = "This is one nasty-looking stone.\n\nYour trainer in Dalaran should see this.", objectives = "Bring the Felslate Deposit Sample to Mama Diggs in Dalaran.", progress = "You bring me somethin' new?", completion = "This is no natural stone, miner. It stinks of demon's blood. Where'd you find this?\n\nReminds me a bit of old fel iron. Come 'ere, lemme teach you a trick or two on how to properly gather this stuff." }
WordHunterWoW_QuestEN[38796] = { title = "Felslate Seam Sample", description = "This ore is remarkably heavy. More disturbingly, it seems to darken and hiss at your touch.\n\nPerhaps your mining trainer in Dalaran has some insights.", objectives = "Bring the Felslate Seam Sample to Mama Diggs in Dalaran.", progress = "Looks like you've been busy down there, miner.", completion = "This came out of a cliffside seam? Remember, ye can't mine seams like ye mine deposits. Totally different thing. I'll show ye my trick." }
WordHunterWoW_QuestEN[38797] = { title = "Living Felslate Sample", description = "Your miner's instinct is kicking in. Chunks of the infernal's corpse appear to be usable.\n\nStill, there must be a way to extract more ore from the demon's body. Perhaps your mining trainer in Dalaran will know how.", objectives = "Bring the Living Felslate Sample to Mama Diggs in Dalaran.", progress = "What's that?", completion = "This came from a blasted infernal? Look out, we've got mister COMBAT miner, here!\n\nSome o' this ore seems to 'ave lost its shine on the trip back, however. Next time, make sure to cut out the sword and spell wounds before ye mine it." }
WordHunterWoW_QuestEN[38798] = { title = "A Shred of Your Humanity", description = "To mine for felslate is to seek the very blood of demons. To improve at it, you must become part demon yourself.\n\nWhy the dirty look? You said it yourself: you're willing to make sacrifices.\n\nLuckily for you, I'm an expert in this area. I won't put you in any danger, as long as you trust me.\n\nAre you ready?", objectives = "Allow Felsmith Nal'ryssa to place three shards of felslate in your body.", progress = "Don't waste my time, miner.", completion = "It is done.\n\nStretch it out a bit.\n\nYou may experience some stray urges to burn worlds and sow chaos for the next week or so. Do your best to resist them." }
WordHunterWoW_QuestEN[38799] = { title = "Darkheart Thicket: Nal'ryssa's Sisters", description = "I was not the only miner in my family. I was the youngest of four sisters.\n\nI say \"was\" because the other three are gone.\n\nTwo of them went too far. They overloaded their bodies with felslate and succumbed to the will of Sargeras. They are more demon than elf, now.\n\nThe third, I have not heard from in quite some time. The last I heard, she was investigating the Darkheart Thicket.\n\nI fear she may have fallen, too - one way or the other.", objectives = "Go to the Darkheart Thicket and find Lyrelle's Signet Ring.", progress = "Any sign of my sister?", completion = "Yes, this is my sister's ring.\n\nThe fact that you found it on a demon's corpse suggests that she has either fallen in battle or, like my other sisters, thrown in her hat with the demons themselves.\n\nThank you for bringing this to me. We don't have many spare materials here on the front lines... but I can do without these." }
WordHunterWoW_QuestEN[38800] = { title = "Rin'thissa's Eye", description = "Oddly enveloped within the felslate deposit is a humanoid eye.\n\nIt quivers with life. You get the sense that it would blink at you if it had an eyelid.\n\nA mining expert should take a look at this.", objectives = "Bring the Ore-Bound Eye to Felsmith Nal'ryssa in Suramar.", progress = "Is... is that...?", completion = "It is. This eye once belonged to my sister, Rin'thissa.\n\nPoor fool, she cut out her own eye and replaced it with a hunk of ore. That was the tipping point... she's completely fel-maddened now.\n\nLearn from her mistake, <name>." }
WordHunterWoW_QuestEN[38801] = { title = "Lyrelle's Right Arm", description = "You blink and rub your eyes, but they do not deceive you. This is a woman's arm, completely enveloped within a felslate seam.\n\nThe arm is bloodless, but still twitches. Fel-colored streaks remain where veins once were.\n\nFelsmith Nal'ryssa will certainly want to see this.", objectives = "Bring the Severed Arm to Felsmith Nal'ryssa in Suramar.", progress = "Lyrelle, no...", completion = "This was my sister's. Lyrelle's.\n\nHer fate is clear now. She no longer needed that signet ring... the girl must have traded in her own mining arm for one carved out of felslate itself.\n\nAren't you glad we only used three small shards?\n\nTake this to heart, <name>: you can lose everything to greed if you don't exercise restraint. Poor Lyrelle paid that price for all of us." }
WordHunterWoW_QuestEN[38802] = { title = "Ondri's Still-Beating Heart", description = "What at first looked like another chunk of felslate is, in fact, a humanoid heart, encrusted in rock and filled not with blood but a vile, demonic substance.\n\nIt does not appear to belong to the beast you carved it out of... it seems that the infernal was holding it like a keepsake. Luckily your mining pick didn't hit it straight on.\n\nFelsmith Nal'ryssa will want to see this.", objectives = "Bring the Ore-Choked Heart to Felsmith Nal'ryssa in Suramar.", progress = "Ondri...", completion = "My sister Ondri was the first among us to mine, and the first among us to fall. Some Nathrezim dreadlord convinced her to replace her own heart - her heart! - with a chunk of felslate.\n\nI slew the dreadlord myself, but couldn't find the heart. This must be it.\n\nBig sister... I am sorry. Your loss will not be forgotten. We will learn from your missteps." }
WordHunterWoW_QuestEN[38803] = { title = "Rin'thissa", description = "My sister Nal'ryssa has her claws in you, doesn't she?\n\nThat weakling doesn't know the first thing about mining. She was always too afraid to take the leap. True knowledge comes only from the Great One, the God of Fel and Flame.\n\nYou want to truly learn how to mine? Come to Suramar's northwestern corner, and speak my name:\n\nRin'thissa.", objectives = "Summon and defeat Rin'thissa.", completion = "My sister's soul rests now. I have you to thank for that.\n\nRin'thissa was always a charmer. You did well to avoid her invitations, and even better to slay her and end her demonic possession. You've learned much since we first met, <name>." }
WordHunterWoW_QuestEN[38804] = { title = "Lyrelle", description = "Look at you, miner. Still held back by the limitations of your fragile, decaying flesh.\n\nTo truly become one with the demon-tinged rocks of these lands, you must shed your skin and submit to a darker power.\n\nJoin us, miner. Bring your feeble body to Felsoul Hold, and speak my name:\n\nLyrelle.", objectives = "Summon and defeat Lyrelle.", completion = "Poor Lyrelle.\n\nI do not blame you for putting her down, <name>. I thank you. I hope that you would do the same to me, if I were to slip and fall down that same path.\n\nJust... try to learn something from your ordeal. Reflect on your experience. I would hate to see her sacrifice be for nothing." }
WordHunterWoW_QuestEN[38805] = { title = "Ondri", description = "You are nothing compared to me. You think yourself hardened, experienced... heroic, even. Hah!\n\nYou have no idea what I've been through. The tortures I've endured, the sacrifices I've made. All for the sake of my trade!\n\nYes, I'm a miner, just like you. Want to learn what I have to teach? Come to the Crimson Thicket in Suramar, and speak my name:\n\nOndri.", objectives = "Summon and defeat Ondri.", progress = "Ondri has always heartless, one way or the other.", completion = "My sister's villainy is finally at an end.\n\nShe was always the wisest among us. Sad that she had to go out the way she did. I'm certain there was much she could have taught us." }
WordHunterWoW_QuestEN[38806] = { title = "Infernal Brimstone Sample", description = "This ore. Smells. Horrible. It combines the odor of sulfur with all the worst parts of a rotting corpse.\n\nSomeone will probably want it for something.\n\nMaybe your mining trainer in Dalaran will take it off of your hands.", objectives = "Bring the Infernal Brimstone Sample to Mama Diggs in Dalaran.", progress = "Excuse me, I must have... wait, that smell is coming from YOU?", completion = "This odiferous morsel ye've brought me... it's infernal brimstone, isn't it?\n\nAmazing.\n\nI've heard tales, but I've never actually SEEN the stuff before.\n\nI've got to study this. In the meantime, here's all I know about this rare, rare ore." }
WordHunterWoW_QuestEN[38807] = { title = "Infernal Brimstone Analysis", description = "In order to mine Infernal Brimstone, we first need to understand the way in which ore comes into being. I currently have three of my apprentices doing research on different ores around the world.\n\nFind Forinn Stoneheart in Deepholm, Rhol Landers in Twilight Highlands and Krul Rockhorn in Icecrown and collect any information they've gathered on the ore at those locations.", objectives = "Collect the reports from Mama Diggs' apprentices in Icecrown, Deepholm and Twilight Highlands.", progress = "What's that you've got there, boy?", completion = "Fascinating..." }
WordHunterWoW_QuestEN[38808] = { title = "Bjornharta", description = "The afterlife leaves the dead hungry for the delicacies of their former lives. For the vrykul kings, none such offering is prized more than Bjornharta - a celebratory feast of an engorged bear heart. \n\nThe bears of the Runewood eat well, and have long been prized for their tender meat. Hunt them and find a suitable heart of offer to the ancient rulers. They will not be able to resist such an offering.", objectives = "Collect 4 Engorged Bear Hearts from Voracious Bears in the Runewood.", progress = "How went the hunt, outsider?", completion = "These hearts are fat and bloody. \n\nThe slumbering rulers will not refuse an offering of Bjornharta." }
WordHunterWoW_QuestEN[38809] = { title = "Treasure: Mushroom Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[38810] = { title = "The Dreaming Fungus", description = "So an outsider would seek to be judged by the ancient rulers of the vrykul? Curious, this. Know that they will not take to your presence kindly, stranger.\n\nIf you are so hasty to meet judgment, you can call them forth with a ritual of wakening. To complete this ritual, you will require an aromatic to burn and an offering to present.\n\nA plant grows in the Runewood that will make a suitable incense. Gather it, and I will instruct you further.", objectives = "Collect 8 Soulcaps in the Runewood.", progress = "What do you bring?", completion = "Yes, these Soulcaps should be adequate for your ritual. \n\nSpeak with me once you are ready to proceed and I will guide you further." }
WordHunterWoW_QuestEN[38811] = { title = "Judgment Day", description = "You have proven resourceful thus far, stranger. As promised, I will instruct you on the ritual of wakening.\n\nFirst, you must place the offering directly atop the grave of the ruler you wish to awaken. Burn the incense so that its aroma wafts over the grave. If your offering is adequate, the ruler will rise, and you may ask your judgment.\n\nTake care, outsider. The dead vrykul kings will not enjoy being awakened from their slumber.", objectives = "Receive judgment from the ancient vrykul rulers.", completion = "Ashildir's grave has been disturbed, outsider. \n\nDo you know something of this?" }
WordHunterWoW_QuestEN[38812] = { title = "Vignette: Shadowthrash", description = "", objectives = "" }
WordHunterWoW_QuestEN[38813] = { title = "Orders for Your Captains", description = "All that is left is to deliver your orders to our Illidari captains. The mightiest of the Legion's forces have arrayed themselves within the volcano. But, they will not remain on the defensive for long.\n\nWe must strike first and we must strike hard.\n\nOnce we destroy them, we can fly up to the command ship, defeat Brood Queen Tyranna, and take the keystone for our own. Lord Illidan will be pleased.", objectives = "Brief your Illidari captains on where to attack the Burning Legion within the volcano.", progress = "Are we ready to commence the assault?", completion = "Our forces have engaged the Legion.\n\nSoon we will stand together victorious with Lord Illidan at the Black Temple." }
WordHunterWoW_QuestEN[38814] = { title = "Treasure: Mystical Staff", description = "", objectives = "" }
WordHunterWoW_QuestEN[38815] = { title = "Waking the Shieldmaiden", description = "With the rituals disrupted and her bones returned, we may be able to wrest Ashildir from the grasp of these Bonespeakers.\n\nDeeper within Haustvald, the mystics possess a special altar that can reunite the body and spirit of a fallen warrior. With this, we may be able to return Ashildir's spirit into her bones, and out of the grasp of these foul mystics.\n\nGo outsider, I will rally her guard.", objectives = "Use the Rune of Reformation to return Ashildir's spirit to her bones.", completion = "Where... where am I now? \n\nI... know you..." }
WordHunterWoW_QuestEN[38816] = { title = "Breaking the Bonespeakers", description = "The crimes of these ritualists must not go unpunished, but we cannot be their executioners. The rune magic they practice grants them untold power over the dead.\n\nYou, however, are not dead, and I can sense great power from you. Take the fight to these heretics, and show Ashildir that you are truly worthy of her judgment!", objectives = "Defeat 15 Bonespeaker vrykul or their allies in Haustvald.", completion = "Your glorious battle honors the Valkyra queen." }
WordHunterWoW_QuestEN[38817] = { title = "Regal Remains", description = "So you seek the judgment of the queen of the Valkyra? This must be your fault!\n\nThe Bonespeakers of Haustvald have committed an atrocity and stolen Ashildir's bones. They must have done this to keep an outsider from completing the trials. You must not let this stand!\n\nEnter Haustvald and retrieve her remains. I hope, for your sake, that Ashildir is in a forgiving mood.", objectives = "Collect 8 Ashildir's Bones in Haustvald.", progress = "Were you able to recover her remains?", completion = "The treachery of the Bonespeakers knows no limit. \n\nTheir rituals seek to sunder the very essence of our queen, but we will use their own magic to return her to us!" }
WordHunterWoW_QuestEN[38818] = { title = "The Final Judgment", description = "In my fragmented state, I captured glimpses of a hero meting out justice to the corrupted mystics of Haustvald. I see now, this hero was you, {class}. \n\nI know you seek my judgment, but my spirit is still fragmented. As we speak,  Runeseer Faljar is calling upon dark, forbidden magics in an attempt to banish my spirit to Helheim. If he succeeds, your trial will be lost.\n\nMy connection here is fading. Go, there is little time!", objectives = "Defeat Runeseer Faljar in Haustvald.", completion = "I cannot believe this fate... \n\nI am sorry, outsider, for I had underestimated Faljar's power.\n\nThat he could banish us here... is unthinkable." }
WordHunterWoW_QuestEN[38819] = { title = "Their Numbers Are Legion", description = "Yes, those devastators must be silenced, but there's also a great deal more to be done.\n\nDespite the odds, we're counting on you. The Brood Queen's primary leaders are in control of the volcano. They must be killed. We must smash the Legion and do anything else necessary to achieve absolute victory.", objectives = "Wage war upon the Brood Queen's Court and the Burning Legion within the greater Inferno Peak area.", completion = "I am in complete agreement. From where I'm standing, you utterly decimated their forces.\n\nWhat do you think? Are we ready to fly up to that command center and take the Sargerite Keystone?" }
WordHunterWoW_QuestEN[38820] = { title = "Vignette: Captain Grok'mar", description = "", objectives = "" }
WordHunterWoW_QuestEN[38821] = { title = "Treasure: The Commander's Shield", description = "", objectives = "" }
WordHunterWoW_QuestEN[38822] = { title = "Treasure: Arcane Wand", description = "", objectives = "" }
WordHunterWoW_QuestEN[38823] = { title = "The Runes that Bind", description = "The stone tablet here describes a ritual where a powerful spirit can be broken into weaker pieces by binding them to special runestones. It looks like the Bonespeakers may be using this very ritual to weaken the spirit of Ashildir.\n\nIt may be impossible to summon her with her spirit so weakened. The rituals must be stopped.", objectives = "Destroy the Ritual Stones to stop the rituals binding Ashildir's spirit in Haustvald.", completion = "These mystics have gone to great lengths to weaken Ashildir. \n\nWe must hope that her spirit is strong enough for the wakening." }
WordHunterWoW_QuestEN[38825] = { title = "Blazing Crusader", description = "", objectives = "" }
WordHunterWoW_QuestEN[38827] = { title = "Your Will Be Done", description = "Lord Grayson Shadowbreaker has drawn a rough map of what we know of the Broken Isles.\n\nYou should speak with him at once - he can best advise you on where we should first strike against the Legion.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Lord Grayson Shadowbreaker.Lord Grayson Shadowbreaker has drawn a rough map of what we know of the Broken Isles.\n\nYou should speak with him at once - he can best advise you on where we should first strike against the Legion.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38833] = { title = "The Art of Demonsteel", description = "The Firmament Stone is one of the few anvils beneath the sky that can tolerate the hammer strikes necessary to craft demonsteel.\n\nHere, I will show you.\n\nTwo parts leystone, one part felslate. No heat, no tempering, just pure strength and finesse.\n\nTry it. I will coach you.", objectives = "Work with Muirn Ironhorn to craft a Demonsteel Bar.", completion = "There you have it... demonsteel.\n\nWelcome to the next level of smithing, <name>." }
WordHunterWoW_QuestEN[38834] = { title = "Into the Fray", description = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely.\n\nCome, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", objectives = "Speak with the lead demon hunter at Illidari Stand.", completion = "The two of you are a welcome sight. We pushed the demons out of these ruins, but they are stronger than any we have encountered before.\n\nYour help is appreciated. If we do not crush this Legion invasion now, they will overrun Azsuna and then the rest of the Broken Isles." }
WordHunterWoW_QuestEN[38836] = { title = "Aktar's Post", description = "", objectives = "" }
WordHunterWoW_QuestEN[38837] = { title = "Vignette: Mordvigbjorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[38838] = { title = "Vignette: Enraged Earthservant", description = "", objectives = "" }
WordHunterWoW_QuestEN[38839] = { title = "Done with Waiting", description = "Mom got a message and said blood called for blood. She told me to wait here while she went out, but it's been two weeks since then. I'm tired of waiting.\n\nI'll stay home if you go find her. She said she was going to the cliffs far to the south.", objectives = "Travel to the southern cliffs of Val'sharah and speak to Makra Knifewhisper.Mom got a message and said blood called for blood. She told me to wait here while she went out, but it's been two weeks since then. I'm tired of waiting.\n\nI'll stay home if you go find her. She said she was going to the cliffs far to the south.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38840] = { title = "Fishy Business", description = "Makrura are massing down by the shore, and far too many of them seem to practice water magic.\n\nI think once they've got enough spellcasters, they're planning to summon a massive wave.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 3 Murktide Wavecallers on the southern coast of Val'sharah." }
WordHunterWoW_QuestEN[38841] = { title = "Die, Fish-People", description = "Makrura are massing down by the shore, and far too many of them seem to practice water magic. I think they're planning to summon a massive wave.\n\nAlso, I've come a long way, and I'm out of supplies. I'm so hungry, I could eat almost anything. Even the makrura you kill. Just cut the heads off first.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 3 Intact Murktide Tails to Makra Knifewhisper on the southern cliffs of Val'sharah." }
WordHunterWoW_QuestEN[38842] = { title = "Faerie Fracas", description = "", objectives = "" }
WordHunterWoW_QuestEN[38843] = { title = "Smashing Eggs", description = "I promised I'd stay home, but there were satyrs, and you were taking so long....\n\nI'm sorry. Please don't tell Mom.\n\nBut did you see? Those fish-people are breeding! You've got to do something!", objectives = "" }
WordHunterWoW_QuestEN[38844] = { title = "Rally the Wilds Buff Received", description = "", objectives = "" }
WordHunterWoW_QuestEN[38845] = { title = "Unused", description = "<Oronok adjusts his posture and stands to his full height.>\n\nI had to be sure, <name>. And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are <female/male>. Which is to say, not at all.\n\nIf you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.Upon completion of this quest you will gain:", objectives = "Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to listen to his story. Speak to Oronok to begin hearing his story." }
WordHunterWoW_QuestEN[38847] = { title = "Vignette: Berserker", description = "", objectives = "" }
WordHunterWoW_QuestEN[38849] = { title = "Burn Those Bodies", description = "Looks like some people fought the fish-people and lost. Now their bodies are just lying there, rotting. Gross!\n\nWe can't leave everybody like that. If you could burn a few of those corpses, I'd feel better. Here, take this torch.", objectives = "" }
WordHunterWoW_QuestEN[38850] = { title = "The Fate of Tirion Fordring", description = "", objectives = "" }
WordHunterWoW_QuestEN[38851] = { title = "Thank You", description = "Could we talk for a second?\n\nMeet up somewhere, I mean? AWAY from my sister?", objectives = "" }
WordHunterWoW_QuestEN[38855] = { title = "zzDEPRECATEDzz Fighting on the Front", description = "[TEMP] While you are here, maybe you could help out a little? Normally you'd get this at the objective map in Lion's Watch. Please help out here.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "[TEMP] Complete the Iron Front Daily." }
WordHunterWoW_QuestEN[38856] = { title = "Holy Retribution", description = "I fell in what you now call Tirisfal Glades at the claws of two of Yogg'Saron's most powerful lieutenants... the C'Thraxi. I was able to slay one in my death throes - Az'jtal.\n\nNow, the dark forces deep beneath Azeroth have begun to usher Az'jtal once again into this world. You must go to Tyr's Fall and strike Az'jtal down again before it can fully manifest.\n\nOnly once this deed is done may you receive my blessing upon the Ashbringer.You will learn:", objectives = "Strike down Az'jtal at Tyr's Fall in Tirisfal Glades." }
WordHunterWoW_QuestEN[38857] = { title = "A Favor for Mr. Shackle", description = "Throm'ka, {class}. My name is Seska. I represent a... trading company. As you can see, I've fallen victim to these giants and their naga allies.\n\nThree of my associates were also captured while surveying this cove. I'm certain that my employer, Mr. Shackle, would be most grateful if you could procure their release.", objectives = "Free Cleave Thunderhill, Gentle Rosh, and Grace the Green.", progress = "You say your name is <name>? Welcome to our humble den. Seska is very grateful for her freedom.\n\nYou haven't perchance seen the rest of my people?", completion = "Excellent, my good sir. I cannot thank you enough for the freedom of my people. Rosh is especially appreciative.\n\n<Gentle Rosh grunts.>\n\nPerhaps you and I can do some more business together." }
WordHunterWoW_QuestEN[38861] = { title = "7.0 Val'sharah - Treasure 019 - Lunarwing Shallows - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38862] = { title = "Thieving Thistleleaf", description = "Why the Thistleleaf are collecting the Lunarwing eggs is anyone's guess, but you can be sure it's not to give them a loving home.\n\nSaylanna Riverbreeze will know what to do with these.", objectives = "Collect 5 Stolen Lunarwing Eggs in the Lunarwing Shallows.", progress = "Gather as many eggs as you can and bring them back to me. I will keep them safe.", completion = "Until I can discover what is vexing the Thistleleaf, I'll have to look after the Lunarwing eggs. At least I know they will be safe." }
WordHunterWoW_QuestEN[38863] = { title = "Treasure: Partially Mined Apexis Crystal", description = "", objectives = "" }
WordHunterWoW_QuestEN[38864] = { title = "7.0 Val'sharah - Treasure 020 - Lunarwing Shallows - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38865] = { title = "Battle At The Iron Front", description = "", objectives = "" }
WordHunterWoW_QuestEN[38866] = { title = "Battle At The Iron Front", description = "", objectives = "" }
WordHunterWoW_QuestEN[38867] = { title = "Inspiration Strikes", description = "The blood of this creature glows with magical energy. It doesn't SEEM to be poisonous.\n\nYour training in the culinary arts has presented you with some strange ingredients before, but this one is particularly inspiring. Perhaps someone within the  Azurewing Repose can suggest a preparation for Leyblood.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain 3 vials of Leyblood, then bring them to Cedonu in Azurewing Repose." }
WordHunterWoW_QuestEN[38868] = { title = "Assault on the Ruins of Kra'nak", description = "", objectives = "" }
WordHunterWoW_QuestEN[38869] = { title = "Assault on the Ruins of Kra'nak", description = "", objectives = "" }
WordHunterWoW_QuestEN[38870] = { title = "Bleeding the Bleeding Hollow", description = "", objectives = "" }
WordHunterWoW_QuestEN[38871] = { title = "Bleeding the Bleeding Hollow", description = "", objectives = "" }
WordHunterWoW_QuestEN[38872] = { title = "The Dark Lady's Bidding", description = "Uh, are these guys friendlies? I guess it's a good sign they haven't tried to eat Duchess... yet.\n\nAnyway, I have orders. Nathanos caught up with the dark rangers, who were sent forward aboard the Oblivion on a secret mission from Lady Sylvanas herself! Unfortunately the Alliance caught wind of our plan, and now Greymane is attacking the outpost!\n\nWe could really use you over there, {name}. Duchess can take you there, just give me the word.", objectives = "Meet with Nathanos Blightcaller in Dreadwake's Landing.", completion = "Finally someone competent arrives at this sorry excuse for an outpost. \n\nOur efforts to complete Sylvanas's mission are at a standstill, but now we have even more pressing matters on our hands." }
WordHunterWoW_QuestEN[38873] = { title = "Clear the Deck!", description = "Our mission in Skold-Ashil will have to wait, {class} - for now, we have more pressing matters to attend to.\n\nI had just recently arrived with reinforcements for our assault when Greymane's ship sailed in and began barraging our walls. We deployed our siege weapons, but their ground forces quickly overwhelmed us.\n\nIf you can get to those catapults and take out the dogs manning the cannons, it may give us the window we need to push the attack!", objectives = "Fire 4 Forsaken Catapults in Greymane's Offensive.", completion = "Hah! Greymane will find his cannons aren't so useful when the blight takes his crew!" }
WordHunterWoW_QuestEN[38874] = { title = "BAD", description = "", objectives = "" }
WordHunterWoW_QuestEN[38876] = { title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.You will receive:", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle." }
WordHunterWoW_QuestEN[38877] = { title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.You will receive:", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle." }
WordHunterWoW_QuestEN[38878] = { title = "Shielded Secrets", description = "Our goal lies within that vault, {class}. I don't have time to explain in detail - just know that it is vital to the Forsaken that we succeed.\n\nThe shieldmaidens have proven tenacious in their defense, but I believe there may be another way in. A chosen few of their order are allowed entrance, and I need you to find out how.\n\nIn the town I have seen intricately engraved shields which I believe are passed down from these champions. The scenes they depict may be the key to passing into the vault.", objectives = "Examine 6 Engraved Vrykul Shields in Skold-Ashil.", completion = "I would hope that you bring me some good news, <class>. \n\nFor both of our sake." }
WordHunterWoW_QuestEN[38882] = { title = "A New Life for Undeath", description = "It seems that you are full of surprises, {name}. With the blessing of the Valkyra queen, you have opened a path that will shape the destiny of Azeroth.\n\nI invite you to bear witness, for today a new day dawns on the Forsaken!", objectives = "Follow Sylvanas into the Vault of Eyir.", completion = "It looks like we underestimated Greymane's tenacity - a mistake that cost the Forsaken dearly. \n\nThis Eyir cannot hide for long, however. If I must I will hunt her through the Halls of Valor! \n\nGo now, <class>. I will call upon you when you are needed." }
WordHunterWoW_QuestEN[38885] = { title = "Shivering Ashmaw Cub", description = "", objectives = "" }
WordHunterWoW_QuestEN[38886] = { title = "7.0 Val'sharah - Treasure 021 - Sleeper's Barrow - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38887] = { title = "7.0 Val'sharah - Bluffs - Vignette: Swiftflight - TRACKING - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38888] = { title = "The Highmountain Tauren", description = "Ye've brought me a bit of interesting rocks to look at, {name}. I've got a special assignment for ye, if ye're up for it.\n\nI hear stories about these tauren, up in Highmountain, who claim mastery over minin'. I don't know if they're as talented as you or me, but they've been minin' leystone longer.\n\nPay 'em a visit. See what they have to say.", objectives = "Report to Ronos Ironhorn in Highmountain.", completion = "You are indeed a miner. You have the look of it. There is ore in your blood." }
WordHunterWoW_QuestEN[38889] = { title = "Adopting the Adorable", description = "", objectives = "You kneel down and hold out a hand. The baby bear sniffs at your fingers, looking up at you trustingly.\n\nThis bear cub is too little to fend for itself. Will you take it with you on your travels?" }
WordHunterWoW_QuestEN[38890] = { title = "Not Dead Yet!", description = "They're not dead yet! A little nitro here, a jolt of electricity there... we can bring 'em back! And then, they can pay me! Whaddya say, <name>? Wanna go into business with me?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Nitro-Electric Jumpstarter to resurrect 5 Gadgetzan Bruisers." }
WordHunterWoW_QuestEN[38892] = { title = "Scouting Report", description = "We were supposed to meet back here, and then sneak back to Gatgetzan. That was hours ago, <name>! The others fanned out across all of Tanaris to gather intel.\n\nAnything you can find will help in the defense of Gadgetzan. Keep your eyes open, <name>!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Goblin Intel from any Steamwheedle Scout in Tanaris." }
WordHunterWoW_QuestEN[38893] = { title = "7.0 Val'sharah - Treasure 022 - Whispering Bluffs - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38894] = { title = "Founded Garrison", description = "", objectives = "" }
WordHunterWoW_QuestEN[38895] = { title = "7.0 Val'sharah - Vignette: Swiftflight - Treasure001 - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38896] = { title = "Tearing down the Legion", description = "A piece of paper is tacked to the controls. On it is a tally of demons slain by the previous pilot.\n\nYour ego demands satisfaciton.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 15 Legion Invaders while piloting a vehicle during a Tanaris invasion." }
WordHunterWoW_QuestEN[38900] = { title = "7.0 Val'sharah - Bluffs - Vignette: Nightcaller - TRACKING - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38901] = { title = "The Felsmiths", description = "Ye have a knack with this felslate, lad. Best ship ye off to someone who knows the stuff better than I.\n\nThe Illidari have a knack with all things demonic, really, and I've heard about a few miners who've set up shop out near the demons in Suramar.\n\nPay 'em a visit. See what they have to teach ye.", objectives = "Report to Felsmith Nal'ryssa in Suramar.", completion = "You want to mine felslate?\n\nDo you really think you have what it takes?\n\nAre you willing to make sacrifices?\n\nGood." }
WordHunterWoW_QuestEN[38902] = { title = "Vignette: Coruscating Bloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[38903] = { title = "7.0 Val'sharah - Bluffs - Vignette: Nightcaller - Interaction - TRACKING - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38904] = { title = "Return to the Broken Shore", description = "Fear not, {name}. I'm angry, but I don't chase my own death.\n\nWe will fly in and scout the ideal point of attack. The demons are still drunk on their victory, but we will put a swift end to their revelry!\n\nTake my spare mount and we will fly to the Broken Shore. There we will bring honor to our dead.", objectives = "Take Saurfang's spare mount to the Broken Shore and fight alongside him to restore your honor.", completion = "Welcome to Skyhold, hero. Normally one must die to gain entrance, but times have changed." }
WordHunterWoW_QuestEN[38906] = { title = "To the Rescue", description = "Saurfang, Wyrmsbane, and Anselm could not wait for reinforcements, they have ventured into that mess to cut off the heads of demon captains. I'm sure they do not require help but time is of the essence.\n\nIf you could go and assist them in killing the demon captains, we can get on with killing the portal guardian.", objectives = "Assist the warriors in killing the demon captains in the Fel Ingress." }
WordHunterWoW_QuestEN[38907] = { title = "Keepers of the Hammer", description = "The Highmountain Tribes had intended to pledge our allegiance to your forces. We know war has come with the Burning Legion.\n\nHowever, we have been betrayed from within and must now ask for your aid.\n\nA great relic, the Hammer of Khaz'goroth, was stolen from our people by the vile drogbar.\n\nWe need your help in recovering it.", objectives = "Meet Mayla Highmountain at Thunder Totem in Highmountain.", progress = "We must be swift. I was overlong in finding you.", completion = "I know you seek the Pillar of Creation but I am sad to say it was one of many things we lost today." }
WordHunterWoW_QuestEN[38909] = { title = "Get to High Ground", description = "It is no accident that Dargrul attacked the Rivermane in force. It is their farms and their pastures that supply food for the region.\n\nPlease, get Jale to Thunder Totem. With luck, Mayla will have reinforcements to send to the area.\n\nWe will rally the survivors here and follow as quickly as we can.", objectives = "Bring Jale Rivermane to Thunder Totem.", progress = "Have you had any luck with the Rivermane?", completion = "Riverbend was... destroyed? That disgusting beast Dargrul! I will not stop until I see him dead.\n\nBut we cannot do that with the army we have.\n\nWe need help from the other tribes." }
WordHunterWoW_QuestEN[38910] = { title = "Rocs vs Eagles", description = "High Crawliac has taught her witches how to curse our beloved eagles into the vile rocs you see assaulting the valley.\n\nThere is no way to break this curse once it has taken hold.\n\nWe will take to the skies and do battle with the rocs, but we need your help on the ground.\n\nHead north through Darkfeather Valley and release any eagles that you find.\n\nEvery eagle you save is one less roc we must kill later.", objectives = "Save 7 Captive Great Eagles.", completion = "Your bravery has returned to us some of our fine feathered friends. Well done.\n\nNow how do you feel about a frontal assault?" }
WordHunterWoW_QuestEN[38911] = { title = "The Rivermane Tribe", description = "What has happened here requires more time than I have to explain. In short, our tribes have scattered in the wake of the attack that left the Hammer of Khaz'goroth in the hands of the barbaric drogbar.\n\nEven now the drogbar are raiding the Rivermane tribe, and I have too few braves left to send to their aid. \n\nWe need a hero. Please, go to Earthmother's Bounty and lend what aid you can.", objectives = "Meet Jale Rivermane at Earthmother's Bounty.", completion = "Mayla was still able to send help? I could hug that child.\n\nWelcome, outsider. I am Jale Rivermane, Chieftain of the Rivermane tribe. And we could really use your help." }
WordHunterWoW_QuestEN[38912] = { title = "The Bloodtotem Tribe", description = "The Bloodtotem are led by Torok, a volatile but useful tauren chieftain. He is wary of outsiders, but I believe you have already met an emissary to their tribe--Oakin Ironbull--whom you rescued at Riverbend.\n\nUse that small thread and you may be able to bring the Bloodtotem back into the fold. Highmountain needs them if we are to defeat the drogbar and reclaim the Hammer of Khaz'goroth. Be on your guard, {name}.", objectives = "Meet Oakin Ironbull at Cliff's Edge.", completion = "Outsider, you are one of few from beyond Highmountain who has made it into these woods alive. With me vouching for you, the Bloodtotem have been given a no-kill order by Torok." }
WordHunterWoW_QuestEN[38913] = { title = "The Skyhorn Tribe", description = "The Skyhorn people are some of the greatest pathfinders and hunters this world has ever known.\n\nThey are a proud people, but should be willing to listen to reason.\n\nIf the roads feel unsafe, you may ask any flight master in Highmountain to fly you there.\n\nPlease, {name}, go to their leader Lasan and remind him that only together, we are Highmountain.", objectives = "Meet Lasan Skyhorn at Skyhorn.", completion = "Ha ha! And what are you, tiny creature? Have you come to battle us or join us in battle?" }
WordHunterWoW_QuestEN[38914] = { title = "Secrets of Highmountain", description = "Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor.\n\nTo this end I have sent word for one of your allies to join us.\n\nWhen you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Spiritwalker Ebonhorn in Thunder totem.Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor.\n\nTo this end I have sent word for one of your allies to join us.\n\nWhen you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38915] = { title = "Battle of Snowblind Mesa", description = "Your timing is fortunate. Our forces at Snowblind Mesa report seeing the Underking above ground.\n\nWhat is more, he is lightly guarded, and has the hammer with him. Thanks to your efforts, we can meet them in battle.\n\nMeet us at Snowblind Mesa and let us take the fight to Dargrul together.", objectives = "Journey to Snowblind Mesa.", completion = "That... is a lot of drogbar." }
WordHunterWoW_QuestEN[38916] = { title = "Secrets of Highmountain", description = "Mayla's father, Ulan, was our last high chieftain. He was slain trying to stop the Underking from seizing the Hammer of Khaz'goroth.\n\nI have watched Mayla all her life and can tell you she has both the courage and the strength to wear the mantle of High Chieftain.\n\nShe needs only our help to realize it herself.\n\nWill you meet us at the city entrance along the southern bluff? There is a ritual that might help, but we will need your aid to survive it.", objectives = "Meet Spiritwalker Ebonhorn at the southern bluff of Thunder Totem.", completion = "Ah, thank you for coming. Mayla is as stubborn as her father if not more so." }
WordHunterWoW_QuestEN[38922] = { title = "Littlefur", description = "Stranger, I beseech you! My once peaceful brethren are now cursed with insatiable wrath.\n\nMy nephew and I tried to leave against the Chieftain's wishes. The clan wrested him from me, and would have torn me apart if I did not flee.\n\nHe is trapped in the village, and I fear the worst.\n\nGreat {class}, please save him. I am too old and too weak to do it myself.", objectives = "Speak to Littlefur at Smolderhide Thicket.", completion = "Uncle?" }
WordHunterWoW_QuestEN[38923] = { title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", objectives = "Defeat the enemy faction at the event locations in Ashran and slay their leader within their base.", progress = "COMMANDER! GOOD SHOWING OUT THERE!", completion = "NICE WORK. TOO BAD THE ALLIANCE IS STILL BEATING DOWN OUR GATES! GET BACK OUT THERE!" }
WordHunterWoW_QuestEN[38924] = { title = "Continue the Domination", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", objectives = "Defeat the Alliance at the event locations in Ashran and kill Grand Marshal Tremblade.", completion = "NICE WORK. TOO BAD THE ALLIANCE IS STILL BEATING DOWN OUR GATES! GET BACK OUT THERE!" }
WordHunterWoW_QuestEN[38925] = { title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", objectives = "Defeat the enemy faction at the event locations in Ashran and slay their leader within their base.", completion = "Well done. That will give the Horde something to think about next time they decide to test us here in Ashran." }
WordHunterWoW_QuestEN[38926] = { title = "Continue the Domination", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", objectives = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath.", completion = "Well done. That will give the Horde something to think about next time they decide to test us here in Ashran." }
WordHunterWoW_QuestEN[38927] = { title = "Battle Hardened", description = "Defeat your opponents on the battlefield and you will be rewarded.", objectives = "Win 3 Rated Battleground matches." }
WordHunterWoW_QuestEN[38929] = { title = "Battle Hardened", description = "Defeat your opponents on the battlefield and you will be rewarded.", objectives = "Win 3 Rated Battleground matches." }
WordHunterWoW_QuestEN[38931] = { title = "Hero's Call: The Hinterlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Gryphon Master Talonaxe at the aviary in Aerie Peak.\n\nOur new brothers in the Alliance need your help to fend off the aggressive Horde offensive in their beloved homeland. Travel north from the Arathi Highlands, through the dwarven mountain pass and follow the road northwest to Aerie Peak.\n\nFor the glory and honor of the Alliance!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Travel to Aerie Peak in The Hinterlands and speak with Gryphon Master Talonaxe.By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Gryphon Master Talonaxe at the aviary in Aerie Peak.\n\nOur new brothers in the Alliance need your help to fend off the aggressive Horde offensive in their beloved homeland. Travel north from the Arathi Highlands, through the dwarven mountain pass and follow the road northwest to Aerie Peak.\n\nFor the glory and honor of the Alliance!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38932] = { title = "Equipment Blueprint: Bilge Pump", description = "This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.", objectives = "Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.", progress = "Those look like some equipment blueprints!", completion = "This is a blueprint for some high tech naval equipment.  I should be able to reverse engineer the plans and have this equipment available for you shortly!" }
WordHunterWoW_QuestEN[38933] = { title = "Logistical Matters", description = "I think we are ready to... reintroduce ourselves to the Legion on the Broken Isles.\n\nLord Grayson Shadowbreaker has volunteered to help coordinate our forces on the ground. You should speak with him immediately, Highlord.", objectives = "Speak to Lord Grayson Shadowbreaker.", completion = "Now is the time to strike back against the Legion." }
WordHunterWoW_QuestEN[38934] = { title = "Silas' Secret Stash", description = "A great Darkmoon prize do you now seek, but be ye warned, it is not for the meek.\n\nYour very first clue to send you on this caper, you will find printed on the back of this paper.", objectives = "Find Silas' Secret Stash." }
WordHunterWoW_QuestEN[38935] = { title = "His Name Was... Stormstout", description = "The land is ripe with rumors of an unusual pandaren monk whose power was matched only for his appetite for brew.\n\nHe was traveling with his young niece who's mouth seems to get them into a lot of trouble.\n\nThe locals say these two were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.", objectives = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", completion = "Ha ha! You were sent by Bolo? The \"Keg Mender,\" right? From the Drunken Hozen?\n\nHow is his eye healing? Is his friend still hung over?\n\nAhh... that was an enjoyable evening." }
WordHunterWoW_QuestEN[38936] = { title = "The Road to Kun-Lai", description = "Lorewalker Cho has sent word that several of your companions survived the conflict in the Jade Forest and have been moved to Kun-Lai Summit to seek healing.\n\nThey need your help if they are to survive!\n\nTo reach Kun-Lai Summit, travel to the Valley of the Four Winds and look for the Highroad Grummle that can be found at the base of the Veiled Stair along the northeastern border.\n\nThey can guide you the rest of the way.", objectives = "Travel through the Veiled Stair to Binan Village.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet, but as you can see, we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?" }
WordHunterWoW_QuestEN[38937] = { title = "Unused - Wraith Zapper", description = "I came here to exorcise the manor. Unfortunately it's haunted by a wizard, and he's summoned quite a few wraiths to bolster his power.\n\nI'm no match for them, but perhaps you are. My gun can harvest the wraiths' ectoplasmic energy. Then we can turn it against him.\n\nBy my estimates, you'll need to zap 7 wraiths before the gun is fully charged. Here, take it.", objectives = "Zap 7 Wraiths near the haunted manor on the hill in western Bradensbrook.\n\nProvided item:" }
WordHunterWoW_QuestEN[38938] = { title = "Unbearable", description = "Not far away, a bear cub looks to be in some distress. Perhaps you should investigate?", objectives = "Investigate the Shivering Ashmaw Cub in southern Val'sharah." }
WordHunterWoW_QuestEN[38939] = { title = "Assault on Skold-Ashil", description = "<insert>You will receive:", objectives = "<insert>" }
WordHunterWoW_QuestEN[38940] = { title = "First Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[38943] = { title = "7.0 Val'sharah - Treasure 023 - Moonclaw Vale - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[38944] = { title = "Sew It Begins", description = "Every time Dalaran takes us to a new shore, I get anxious over what types of fabric and cloth we might find below.\n\nThreads imbued with magic? Something demonically-tinged?\n\nUgh, I hope it's not FURS again.\n\nYou're an adventurer... and tailor to boot. Head on down there and see what you can scrounge up!", objectives = "Obtain 10 Shal'dorei Silk. You can find Shal'dorei Silk on humanoids within the Broken Isles, obtain some from a fellow adventurer, or you may visit the Auction House and buy some.", progress = "I wouldn't mind working with some cashmere...", completion = "Now this... this I can work with!\n\nReminds me of some old night elven festival cloth I've seen." }
WordHunterWoW_QuestEN[38945] = { title = "This Should Be Simple... Right?", description = "I have plenty of silk patterns that we can put this cloth to work on.\n\nHelp me to prepare the materials, {name}. We're going to put this cloth to good use and make you a new robe.", objectives = "Craft a Handcrafted Silkweave Robe on Tanithria's Finishing Bench. You can find the pattern in your tailoring pattern list. You can find the materials for the pattern in her shop.", progress = "We're back in business again. How exciting!", completion = "That's a shame. Without the ability to do any stitching, we can hardly do anything with this fabric.\n\n<Tanithria pouts.>\n\nStill, there ARE patterns we know that don't require stitching. Shoulderpads are easy, and belts should be a cinch." }
WordHunterWoW_QuestEN[38946] = { title = "Consult the Locals", description = "Whoever wove this fabric CAN'T have intended it only for belts and shoulderpads. There must be some way to sew thread into this material.\n\nHead on down to Azsuna and try to find a tailor. We need to sew if we're going to do any real tailoring.", objectives = "Find a tailor in Azsuna.", completion = "My my, look at you! Such an attractive young <class>, and all bedecked in magical finery and weaponry. To what do I owe the pleasure?\n\nAha! Tailoring! It's your lucky day, er...\n\nI'm sorry, what was your name? <name>?\n\nIt's your lucky day, <name>! I happen to be one of the best tailors in Suramar..." }
WordHunterWoW_QuestEN[38947] = { title = "Runic Catgut", description = "Let me guess... thread troubles? Mm-hm.\nI suspected as much. My people weave sumptuous silks, but those silks can be fickle about the types of thread they'll accept.\n\nShal'dorei silk has a bit of ley energy woven right into it. You need something that's learned to coexist with the ley energies of this land.\n\nI'm talking about owlcats, my good friend! They have what you need. You'll find them amongst the ruins of Llothien.", objectives = "Obtain 3 pieces of Runic Catgut.", progress = "They are quite remarkable creatures, really. I used to keep one as a pet and mount... but that was a lifetime ago.", completion = "Perfect. Marvelous!" }
WordHunterWoW_QuestEN[38948] = { title = "Hard Times", description = "When I worked at the tailoring guild in Suramar, I would usually work off of a pattern. Something that inspired me.\n\nUnfortunately, I've run into streak of bad luck, and I'm ashamed to say that I no longer have my patterns.\n\nThe naga sorceresses in the lagoon to the west, however, have expertly-sewn wristwraps. And the nightfallen to the north wear robes that we can use... if you can pry one from their greedy clutches.", objectives = "Obtain a Stained Silken Robe and a set of Hatecoil Wristwraps.", progress = "What've you got in your hands, there?", completion = "You, <name>, are a person of great skill. I send you out for patterns, and you do so without question. Remarkable!" }
WordHunterWoW_QuestEN[38949] = { title = "So You Think You Can Sew", description = "Very good, I think we're ready to begin.\n\n<Lyndras steals a glance at your powerful weapon. A look of hunger washes over his face before he shakes it off and continues.>\n\nLet's prepare our materials and make the robe and bracers that you so rightfully deserve!", objectives = "Craft a Rune-Threaded Silkweave Robe and a set of Rune-Threaded Silkweave Bracers at Lyndras' Finishing Table. You can find the patterns in your tailoring pattern list.", progress = "You're pretty lucky to have found me.", completion = "There you have it!\n\nNo, no, don't thank me. I'm just happy to have been of service." }
WordHunterWoW_QuestEN[38950] = { title = "The Wayward Tailor", description = "Might I ask a favor, {name}?\n\nAs I am recently without a home, shop, family, or friends, I was wondering if you might show me your floating city? I must admit, I am VERY curious about the place. I've also heard good things about their tailoring shop.\n\nI have no way of getting there myself, but certainly such a magical city has SOMEONE who can summon me.\n\n<Lyndras looks at you with hopeful apprehension.>", objectives = "Speak to Lalla Brightweave in Dalaran, and ask her to summon Lyndras.", progress = "Did you find a tailor yet?", completion = "Your friend certainly has an... interesting appearance.\n\nHe taught you to sew this silk? Hmm. Maybe we should keep him around for a while." }
WordHunterWoW_QuestEN[38951] = { title = "A Needle Need", description = "This shop has almost everything we need. Unfortunately, the quality of your sewing needles is lacking.\n\nI do know where you can get better needles. The sprites of Val'sharah are covered with spines which, fortuitously, are perfect for the type of sewing we need.\n\nI hate to be such a prickler stickler, but these needles really will make a difference.", objectives = "Obtain 150 Spritethorns.", progress = "Your friend thinks these needles will make a difference?", completion = "Hmm... he may have a point.\n\nThese needles ARE quite strong, and they have a nice bounce to them. Still, I do take issue with their shape and feel. I have an idea." }
WordHunterWoW_QuestEN[38952] = { title = "Meticulous Precision", description = "The needles are sharp, but look at them closely. Some have a curve to them, others have a spur hanging off the side. Look at this one... it's got a ninety-degree crook in it! I have no desire to sew around a corner.\n\nTiffany Cartier in the jewelcrafting shop has a good eye for this sort of thing. Bring these needles to her, and she'll straighten them out.", objectives = "Bring the Spritethorns to Tiffany Cartier in Dalaran.", progress = "What's this, <name>?", completion = "Look at these! Strong, light, flexible, sharp, with a refined curve and a smooth edge. You've certainly put your Dalaran touch on it. It's the best of both worlds!\n\nEnough fussing over our tools, now. Shall we sew?" }
WordHunterWoW_QuestEN[38953] = { title = "Advanced Needlework", description = "You've already learned the patterns for bracers, belts, epaulets, and of course, robes. Unfortunately, your technique was wasteful... you need a better method.\n\nThat's where our needles come in.\n\nHere, I'll show you how to improve the process of these patterns.", objectives = "Make an Embroidered Silkweave Robe on Tanithria's Finishing Bench. You will need to gather the materials in her shop.", progress = "Keep your eye on your needlework. Don't lose focus now.", completion = "Now isn't that just lovely. Go on, try it out yourself!" }
WordHunterWoW_QuestEN[38954] = { title = "Where's Lyndras?", description = "That's strange. Lyndras was here one moment, and then he ran off the next. He had such a strange look on his face.\n\nPerhaps we should track him down.", objectives = "Find Lyndras.", completion = "Sorry about that, <name>. You caught me snooping around. I suppose my curiosity got the better of me.\n\nAllow me to make it up to you." }
WordHunterWoW_QuestEN[38955] = { title = "Sew Far, Sew Good", description = "Your tailoring skill really is impressive and, although I don't have my patterns with me, I do have some patterns memorized. One of those patterns is for a simple bag.\n\nFollow my lead, {name}.", objectives = "Craft a Silkweave Bag. You will need to gather materials inside the Dalaran tailoring shop.", progress = "There's nothing quite like a new bag.", completion = "There you have it. Not the best bag in the world, but it's better than most.\n\nI want to apologize again for running off, <name>. My hunger... err, curiosity... occasionally gets the better of me. I promise it will not happen again." }
WordHunterWoW_QuestEN[38956] = { title = "Where's Lyndras Again?", description = "Oh dear.\n\nHe had just promised you that he wouldn't wander off, and then he did it again!\n\nI'm starting to think that this Lyndras character might be a bit too impetuous for my tastes.\n\nPlease, go find him, before he gets into any more trouble.", objectives = "Find Lyndras in Dalaran.", completion = "My most sincere apologies, <name>. Not only did I make a spectacle of myself, I fear I may have also put the good name of your tailoring shop at risk.\n\nYou have every right to be upset with me." }
WordHunterWoW_QuestEN[38957] = { title = "Taking Inspiration", description = "I wish I had more patterns to share, but my notebook was lost along with my shop. We'll need to come up with some patterns on our own.\n\nI've been thinking about the leather breeches that the Stormheim vrykul wear. They're certainly much thicker and heavier than anything we could sew, but their embellishing runework is quite impressive.\n\nIf I had a few pairs, perhaps I could re-imagine this runework on a more... refined garment.", objectives = "Obtain 6 Runed Breeches.", progress = "I'm looking forward to this.", completion = "Aha! This will be much simpler than I'd first thought.\n\n<Lyndras takes a moment to jot some instructions down on a scrap of vellum.>\n\nHere, <name>. You should have it." }
WordHunterWoW_QuestEN[38958] = { title = "The Right Color", description = "Your assistance, {name}, if you have a moment.\n\nI've been attempting to reproduce a pattern for footwear that I spotted a while back, but I'm having trouble getting the right color for my dye. Our black dye is too dark, our blue dye is too bright, and mixing the two doesn't look right.\n\nThe color I'm looking for is more of a squid-ink blue. If, in your travels, you come across any dyes of this color, would you do me the favor of bringing some to me?", objectives = "Obtain 10 Helsquid Ink.", progress = "I'm quite close to completing these slippers.", completion = "Marvelous!" }
WordHunterWoW_QuestEN[38959] = { title = "Left Behind", description = "I do truly want to help you work on your tailoring, but without my patterns or my supplies, there isn't much more I can do save for teaching you what little I remember.\n\nIf my memory still serves true, you're just missing a good pattern for some gloves and a hood.\n\nThe first thing I need you to do is grab a few things from where you first met me. Here's what I need...", objectives = "Gather Lyndras' Pinking Shears, his Box of Measuring Tools and his Threading Needles from where you first met him in Azsuna.", progress = "I had no clue I'd be magically teleported here, otherwise I would have gathered my things myself.", completion = "Excellent! It's always nice to have familiar things.\n\nThis will make instructing you much easier for me." }
WordHunterWoW_QuestEN[38960] = { title = "Lining Them Up", description = "Since you're heading to Azsuna, you may as well gather some lining for our projects.\n\nThe bears of Azsuna are known for how soft, yet durable their fur is.\n\nHunt them in the woods around Llothien and bring their fur back with you.", objectives = "Gather 15 Bear Furs.", progress = "Don't take them for easy prey. They're as vicious as they are cunning.", completion = "This will be plenty." }
WordHunterWoW_QuestEN[38961] = { title = "Eye of Azshara: The Depraved Nightfallen", description = "In order to craft the gloves, we'll require a special item. This will be no easy task to recover it, {name}.\n\nThe naga of Azsuna are said to be hard at work trying to summon a terrible creature into this world.\n\nThe creature's heart holds immense energy that we can use to channel into the gloves, making them incredibly powerful.\n\nI need... I mean, we need that heart if we are to produce a suitable pair of gloves for someone of your presence.", objectives = "Go to the Eye of Azshara, defeat the Wrath of Azshara and recover the Heart of the Storm.", progress = "What were you able to find?", completion = "Lyndras ran off again before you could return, <name>. He left a note and a pattern for you.\n\nThe note reads,\n\n\"I'm sorry, <name>, but I'm afraid I may become a threat to the fellow tailors of this shop. I'm off to find somewhere to try and control my urges, or fall into depravity. It has been an honor training you.\n\nSincerely,\n\nLyndras\"\n\nHow sad..." }
WordHunterWoW_QuestEN[38962] = { title = "The Path to Suramar City", description = "I recall Lyndras mentioning a guild of tailors within Suramar City. Perhaps they could further our understanding of how to utilize this new cloth.\n\nUnfortunately from what I've heard, they've sided with the demons and anyone opposed to them is to be killed on sight.\n\nYou must find a way to move safely within the confines of their city if we're to continue our research.", objectives = "Assist the nightfallen of Suramar until you discover a way to move safely amongst the elves of Suramar City.", completion = "Now that you can move safely around the city, it's time to find some new masters." }
WordHunterWoW_QuestEN[38963] = { title = "The Final Lesson?", description = "Now that we have everything we need, let's work on the hood.\n\nAfter we're finished, we'll move onto the gloves.", objectives = "Create a Handcrafted Silkweave Hood on Tanithria's Finishing Bench. You will need to gather the materials in her shop.", progress = "Come now, <name>. Let us sew.", completion = "Well done, <name>. Before long you may be the one teaching me a thing or two." }
WordHunterWoW_QuestEN[38964] = { title = "Where's Lyndras Now?", description = "Lyndras couldn't have gone very far. I mean, we're floating a thousand feet over the sea. \n\nI heard some commotion across the way this morning near the alchemy shop. I pray that wasn't Lyndras.\n\nCould you please go over there and make sure?", objectives = "Go the alchemy shop across the street." }
WordHunterWoW_QuestEN[38965] = { title = "Assault on Violet Hold: Into the Hold", description = "With Lyndras being locked up in Violet Hold, you feel responsible for him and must discover the truth behind his actions.\n\nPerhaps if you were able to speak with him, you could find a way to have him released from the hold and put back into your custody.\n\nGo into Violet Hold and find out what happened to Lyndras.", objectives = "Go into Violet Hold and find out what happened to Lyndras.", progress = "Did you discover what happened to Lyndras?", completion = "<Tanithria listens to your account of Lyndras' fate.>\n\nI... I see. That's a shame.\n\nI had grown to enjoy his company, you know. If you'll excuse me, I need a moment to think about him." }
WordHunterWoW_QuestEN[38966] = { title = "Secret Silkweaving Methods", description = "Okay, done mourning! Let's look through his stuff.\n\n<Tanithria takes a moment to leaf through Lyndras' journal. Her eyes open wide.>\n\nOur friend has been keeping secrets from us. Look at this! Every single one of the recipes he's taught us can be improved.\n\nLet's start simple, with some bracers. I can supply most of the materials, but you'll have to talk to Alard Schmied in the blacksmithing shop to get this powdered brimstone.", objectives = "Craft some Masterwork Silkweave Bracers.\n\nYou will need to gather materials from the Dalaran tailoring shop and blacksmithing shop.", progress = "These patterns are fascinating. I never knew you could get this kind of result out of simple silks.", completion = "The good news is that we can now craft more efficient patterns out of silkweave.\n\nThe bad news is that we've expended the remainder of Lyndras' knowledge. Where should we turn next?" }
WordHunterWoW_QuestEN[38967] = { title = "The Nightborne Connection", description = "Now that you're able to disguise yourself, you should go to Suramar City and try to find this guild of tailors.\n\nGood luck, {name}, and try not to get caught.", objectives = "Speak with Leyweaver Tytallo in Suramar.", completion = "Ah, a fellow tailor. Pleasure to make your acquaintance, uh... <name>, was it?\n\nI trust you'd like to come into the fold of our guild? Where did you receive your prior training?" }
WordHunterWoW_QuestEN[38968] = { title = "Proof of Loyalty", description = "<Tytallo listens as you recount what happened with Lyndras.>\n\nI see. You sound almost... sympathetic to the wretch.\n\nThe nightfallen are liars and thieves. ALL of them. Lyndras included.\n\nI will not tolerate a student that has any respect or sympathy for those... things. And have you witnessed what they turn into at the depths of their depravity?\n\nIf you want to get on my good side, do not return until you are covered in the blood of the withered.", objectives = "Slay 25 withered within Suramar.", progress = "If you wish to earn my tutelage, you must first prove that you are on our side.", completion = "Hmm.\n\nVery well. We may continue." }
WordHunterWoW_QuestEN[38969] = { title = "Master of Silkweave", description = "While Tytallo is busy exacting withered genocide, it falls on me to take care of the more mundane aspects of training.\n\nWe're going to need to see how talented you are.\n\nCraft an entire set of silkweave armor for me. Leyweaver Mithrogane can provide you with a proper mannequin for displaying it.", objectives = "Purchase a Shal'dorei Mannequin from Leyweaver Mithrogane, then craft an entire set of silkweave armor and place them on the mannequin.", progress = "If you wish to learn what we're about to teach you, you need a solid foundation.", completion = "Your stitching is still a little rough, but you've already mastered all of the basics.\n\nWell done.\n\nI don't say that very often. Savor it." }
WordHunterWoW_QuestEN[38970] = { title = "The Queen's Grace Loom", description = "Great power comes only with sacrifice. Even the most masterful tailor can only do so much with silkweave. To improve your patterns any further, bargains must be made.\n\nYou are prepared, {name}, to learn about working with Imbued Silkweave.\n\nUse the teleportation crystal behind me, and speak with Azayna, the leader of our order.", objectives = "Use the Teleportation Crystal in the Leyweavers' Hall, then speak with Leyweaver Azayna.", progress = "Return once you've spoken with Azayna.", completion = "Don't look at us that way, <name>. Selling our services to the demons may have been morally dubious, but our skills have grown exponentially since Azayna made the deal.\n\nContinue your training with us, or don't. If you want to leave now, nobody's stopping you. If you want to learn more... we are the only game in town." }
WordHunterWoW_QuestEN[38971] = { title = "Exotic Textiles", description = "I'm risking my life and career to be here, tailor.\n\nI've been curious about demonic cloth, and my attempts to obtain some through approved means have been met with resistance.\n\nI simply must see this cloth for myself.\n\nI don't wish to disrupt Azayna's pact with the demons, but you - you can attack the demons without drawing attention to our guild.\n\nI'm particularly interested in a particular demon's set of robes. Bring me a scrap, and I'll teach you what I know.", objectives = "Obtain the Fel Inscribed Shroud.", progress = "Probably better that you fight the thing, anyhow. I'm useless with a weapon.", completion = "Excellent work. I will get to studying this fabric right away. As promised, I will teach you what I know. Are you acquainted with our patterns for gloves?" }
WordHunterWoW_QuestEN[38974] = { title = "Halls of Valor: The Right Question", description = "One might ask what a leyweaver is doing standing over a dead vrykul's body. But such questions only stir up trouble.\n\nInstead let us ask what can be learned from those who have passed on. A question like that promotes progress.\n\nI assume you're here to learn from me, the pattern for Imbued Silkweave pants, yes?\n\nIf that's true, then I'll need something from one who has passed on. In the Halls of Valor the great guardian, Hymdall resides.\n\nBring me his loincloth and I will teach you my pattern.", objectives = "Defeat Hymdall in the Halls of Valor and recover his loincloth.", progress = "Asking the right questions will get you far.", completion = "<Tellumi takes the loincloth from you and gives you a sly smile.>\n\nI trust you now see looking at a situation from a functional angle than a reactionary one will earn you far more knowledge." }
WordHunterWoW_QuestEN[38975] = { title = "Inspire Me!", description = "I am, and always will be, a student of robemaking and dressmaking. You can keep your gloves, belts, and cloaks. Nothing beats a good robe.\n\nI'll share my pattern for an imbued silkweave robe with you if you can teach me some of the robe and dress patterns you've learned along your tailoring journey.", objectives = "Craft a Brown Linen Robe, a White Woolen Dress, a Simple Black Dress, a Frostwoven Robe, and a Spiritmend Robe while standing near Leyweaver Mithrogane.\n\nIf you do not know a pattern, you can learn it from tailoring trainers in major cities.", progress = "I never turn down the opportunity to learn a new robe pattern.", completion = "Not quite what I'd expected, but it was an interesting history lesson, at least. You can keep the robes, I've learned all I need just by watching you work.\n\nNow, as promised, I shall show you what I know." }
