WordHunterWoW_QuestEN[38989] = { title = "Your Orders, General?", description = "General, your forces in Tanaan Jungle await your orders. Travel to the Planning Map there to issue your commands.\n\nFor the Horde!", objectives = "Go to the Tanaan Planning Map in Tanaan Jungle.", completion = "Lok'tar General. Your forces await your orders." }
WordHunterWoW_QuestEN[38990] = { title = "The Call of Icecrown", description = "<A powerful presence again touches your thoughts.>\n\nI have ordered your brethren to Icecrown to prepare for the coming conflict, but I have a more important fate in mind for you. You, {name}, will be the hand of our vengeance!\n\nUse the Death Gate to return to Acherus and I shall reveal your role in this.", objectives = "Use your Death Gate ability to travel to Icecrown and obtain the Blades of the Fallen Prince.", progress = "It is time to begin, <name>.", completion = "The Lich King made a wise choice in giving you those blades, <name>. You've more then proven yourself worthy of them.\n\nI have to admit though, I'm glad it wasn't me, I'm through with having magical weapons dictate my fate." }
WordHunterWoW_QuestEN[38992] = { title = "Mograine's Oath", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38993] = { title = "First Mission Sent", description = "", objectives = "" }
WordHunterWoW_QuestEN[38994] = { title = "TRACKING Encounter Botanist", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Botanist Darkgrove(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[38995] = { title = "Unused", description = "", objectives = "" }
WordHunterWoW_QuestEN[38996] = { title = "Your Orders, General?", description = "Exarch Yrel has sent word from Lion's Watch in Tanaan Jungle that your forces stand ready for their new orders.\n\nFor the Alliance!", objectives = "Speak with Yrel at Lion's Stand in Tanaan Jungle.", completion = "Greetings General. Your forces await your orders on the Planning Table." }
WordHunterWoW_QuestEN[39000] = { title = "We Don't Need No Library Card", description = "If history is any indication, Gul'dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves.\n\nAs you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul'dan's lieutenants.\n\nThey're dangerous, so don't read any of them. Not even the pictures.\n\n<Khadgar shudders.>\n\nESPECIALLY the pictures.", objectives = "Collect 33 Tomes of Chaos from bosses in Hellfire Citadel.", progress = "What about those books, <name>?", completion = "<Khadgar gingerly looks over the spine of each book as you hand it to him, growing more and more visibly disgusted.>\n\nWill you look at these? This is like a set of encyclopedias for psychopaths." }
WordHunterWoW_QuestEN[39001] = { title = "To Farahlon!", description = "<name>, have you ever heard of Farahlon? Archmage Vargoth would never stop talking about it - beautiful fields and forests dotted with natural crystalline formations that make it the magical nexus of Draenor. It's nearly impossible to get to. The magical storms in the seas around it are frequent and unpredictable.\n\nFor your ring, we'll need a magical artifact from Farahlon. You will need an absolutely top-notch crew to sail safely to the region and get back alive. Choose carefully and get me that artifact!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use your shipyard to complete the \"To Farahlon!\" Naval Mission and retrieve the Pearl of Farahlon." }
WordHunterWoW_QuestEN[39002] = { title = "Ogres of the Deep", description = "It might surprise you to know that at its peak the Gorian ogre empire had a small but powerful navy. It probably wouldn't surprise you to learn that many of its largest warships sunk. They were built out of stone.\n\nI've found an old chart indicating the last-known position of \"The Emperor's Foot,\" lost at sea with a valuable artifact I need. An ogre decoder.\n\nRight! To salvage it you'll need a submarine and a crack crew. This is an extremely dangerous mission which is why I'm giving it to you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use your shipyard to complete the \"Ogres of the Deep\" Naval Mission and retrieve the Soaked Ogre Decoder." }
WordHunterWoW_QuestEN[39003] = { title = "Cooking the Books", description = "{name}, we've got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can't just burn them. Cordana will know what to do.\n\nTake these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.", objectives = "Deliver Gul'dan's Library of Chaos to Cordana at Zangarra and ensure they are destroyed.", progress = "<Khadgar smiles.>\n\nSo, how is Cordana doing? Is all well at my tower?", completion = "<Khadgar's face falls as you describe your encounter at the tower.>\n\nCordana...? Oh no no no...She's been very distant lately. I just... I thought it was part of her stone-cold warden routine. I didn't realize...\n\nAh, <name>! You see? This is exactly what Gul'dan does. He finds our weakness and turns it against us. Be careful who you trust. Ah, Cordana!\n\n\n\nCordana." }
WordHunterWoW_QuestEN[39004] = { title = "Darkness Incarnate", description = "We have one final task before us, {name}. We must defeat Gul'dan and unravel his plans for this world.\n\nI have no reward to offer you - I have given you everything I can.\n\nCome. When you and your allies are ready, we march on Hellfire Citadel... and end this.", objectives = "Hunt down and engage Gul'dan within the Hellfire Citadel.", progress = "We must thwart Gul'dan!", completion = "<Khadgar's face is ashen.>\n\nDraenor is saved, <name>. But the Legion is more powerful than even I had imagined. And Gul'dan, that snake - he's still alive. Somewhere.\n\nStay here and celebrate with the others, <name>. You've earned it. But I will soon return to Azeroth to deal with this, and I hope you will join me there when the time comes." }
