WordHunterWoW_QuestEN[39006] = { title = "Second Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39009] = { title = "Third Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39010] = { title = "Third Mission Sent", description = "", objectives = "" }
WordHunterWoW_QuestEN[39011] = { title = "Black Rook Invasion", description = "Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village's food supply.\n\nWe're the last family living this close to the castle, but we daren't retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?", objectives = "Kill 7 Black Rook Assassins in Bradensbrook." }
WordHunterWoW_QuestEN[39015] = { title = "Grumpy", description = "", objectives = "<The puppy wags its tail furiously as soon as he spots you. He seems extremely grateful.>" }
WordHunterWoW_QuestEN[39016] = { title = "Unused - The Fish Must Flow", description = "Our village is running low on food, and undead spies from Black Rook Hold have started targeting our fishers.\n\nIt's a surgical move, hitting our people and our food supply all at once.\n\nHelp us out and send those ghosts a message. Pare down their forces and bring back the food they've stolen.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Stolen Fish from the Black Rook Assassins and Black Rook Lieutenants in Bradensbrook." }
WordHunterWoW_QuestEN[39017] = { title = "Rise to the Occasion", description = "The Lich King made a wise choice in giving you that weapon, <name>.\n\nYou've proven your strength and cunning on countless occasions and it is time that you have a position fitting for your accomplishments.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Highlord Darion Mograine within Acherus." }
WordHunterWoW_QuestEN[39018] = { title = "Call of the Archmage", description = "Archmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", completion = "<The Archmage looks damp and uncomfortable.>\n\nI apologize for the conditions here, <name>. I had no choice. I summoned this tower at the optimal confluence of arcane energies. My hope is to finish my work here before all my books get musty.\n\nSo then! Let's get to it." }
WordHunterWoW_QuestEN[39019] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", completion = "Welcome back, my friend. We have much work to do." }
WordHunterWoW_QuestEN[39020] = { title = "A Burning Path Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "Follow the blazing star, and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[39021] = { title = "A Frozen Path Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "Follow the chill star, and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[39022] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", completion = "Welcome back, my friend. We have much work to do." }
WordHunterWoW_QuestEN[39023] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39024] = { title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39025] = { title = "Grasp of the Underking", description = "If we have one good fortune in this it is that Dargrul has no knowledge of how to use the hammer.\n\nHe keeps thinking of the hammer as a weapon instead of a tool of creation.\n\nEven so, he has imprisoned our tribesman in fists of stone summoned from the earth. Our weapons have proven useless against this magic.\n\nYou might have power enough to break these fists. Can you help?", objectives = "Rescue Jale Rivermane, Warbrave Oro, and Oakin Ironbull.", progress = "How are the captives? Did you find them alive?", completion = "It has been an age or more since the drogbar last walked the surface in such numbers.\n\nThey became the dark stories we tell children." }
WordHunterWoW_QuestEN[39026] = { title = "The Drogbar", description = "It wasn't enough for Dargrul to just destroy this village. He has also sent his Stoneraiders to take what is left.\n\nPlease champion, prove to my people that you are the hero I foresaw.\n\nSlay enough of these Stoneraiders that it breaks their resolve.", objectives = "Slay 8 Drogbar in Riverbend.", progress = "The drogbar were supposed to be our allies against the Burning Legion.", completion = "Your battle skills are impressive." }
WordHunterWoW_QuestEN[39027] = { title = "Dargrul and the Hammer", description = "We are about to follow a drogbar into a cave, something we warn our children never to do.\n\nEven so, several of our warbraves have already followed Dargrul inside.\n\nCome, join us in battle and let us reclaim the Hammer of Khaz'goroth.", objectives = "Confront Dargrul the Underking.", progress = "This is a hard day.", completion = "Oro and the others? Did they make it out as well?\n\nSuch destruction. So many good warbraves have fallen today.\n\nIt is clear now, we will need the full might of the Highmountain tribes if we are to recover the hammer." }
WordHunterWoW_QuestEN[39028] = { title = "REUSE ME", description = "asdfYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "asdf" }
