WordHunterWoW_QuestEN[39031] = { title = "Vignette: Ivory Sentinel", description = "", objectives = "" }
WordHunterWoW_QuestEN[39032] = { title = "A Summons from Saylanna", description = "Sprites have always been mischievous creatures, but lately their mischief has turned to violence.\n\nOne of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds.\n\nThe Lunarwing Shallows lie to the south. You will find Saylanna there.", objectives = "Seek out Saylanna Riverbreeze in the Lunarwing Shallows.Sprites have always been mischievous creatures, but lately their mischief has turned to violence.\n\nOne of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds.\n\nThe Lunarwing Shallows lie to the south. You will find Saylanna there.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39033] = { title = "The Time to Strike", description = "This configuration of the stars causes an unusual vibration in the crystals strewn across Draenor, relics of the ancient Apexis. Some swear that the crystals will multiply when left unattended beneath the night sky, but none have seen the phenomenon firsthand. Regardless of the true cause, these crystals should be far more plentiful should you seek them out.", objectives = "Complete 5 Objectives in Apexis-yielding areas.", progress = "Ah, the unmistakable hum of crystals when the Apexis star shines....", completion = "Well done, <name>. Fortunately, a skilled diviner can use Apexis crystals to reveal oil deposits beneath the earth. I cannot teach you this art, but you may nevertheless reap its benefit." }
WordHunterWoW_QuestEN[39034] = { title = "Emissary of War", description = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture deep into caverns and strongholds to prove your worth.", objectives = "Complete 4 dungeons on Mythic difficulty.", progress = "Be bold, <name>, and you may win many friends on this day.", completion = "Your new allies left this here, as a tribute for your efforts on their behalf." }
WordHunterWoW_QuestEN[39035] = { title = "Tracking: Horde Siegebreaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[39036] = { title = "Tracking: Alliance Siegebreaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[39037] = { title = "Tracking: Iron Horde Siegebreaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[39038] = { title = "Tracking: Resource Rich", description = "", objectives = "" }
WordHunterWoW_QuestEN[39040] = { title = "A Call to Battle", description = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", objectives = "Win 4 Battleground matches.", completion = "I trust your battles went well?" }
WordHunterWoW_QuestEN[39041] = { title = "The Arena Calls", description = "This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....", objectives = "Win 10 Arena Skirmish battles.", completion = "The wind whispers your name, <name>, and tales of your conquest." }
WordHunterWoW_QuestEN[39042] = { title = "The Very Best", description = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", completion = "Well done, <name>. With courage, you have faced every challenge along the way, and battled to claim your rightful place." }
WordHunterWoW_QuestEN[39043] = { title = "Bitestone Enclave", description = "This is an old drogbar enclave that we used to trade with. Now it is a base of operations for their raids.\n\nI need more time to gather what is left of our warbraves. Go, enter the enclave, and slay any you find in there.\n\nBuy us the time we need to gather our strength.", objectives = "Slay drogbar in the Bitestone Enclave.", progress = "Highmountain stands!", completion = "Thank you for clearing us a path. We should have a straight shot at Dargrul now." }
WordHunterWoW_QuestEN[39044] = { title = "Unused", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39045] = { title = "Vignette: Zoug", description = "", objectives = "" }
WordHunterWoW_QuestEN[39046] = { title = "Vignette: Harbormaster Korak", description = "", objectives = "" }
WordHunterWoW_QuestEN[39047] = { title = "Call of the Illidari", description = "{name}, Altruis requests that you meet him at Krasus' Landing at once.\n\n<Kor'vas leans in close, her voice an urgent whisper.>\n\nYou must hurry. The Legion has eyes everywhere.", objectives = "Speak to Altruis the Sufferer at Krasus' Landing.", completion = "We need to move quickly. With every moment we sit here, the Legion's hold strengthens." }
WordHunterWoW_QuestEN[39048] = { title = "Vignette: Demolitionist", description = "", objectives = "" }
WordHunterWoW_QuestEN[39049] = { title = "Eye On the Prize", description = "This demon has proved less than useful. I have been using the Scythe of Souls on it, but so far, it has resisted my inquiries. We will see how long that lasts.\n\nI have a different idea...\n\nThere is a fresh inquisitor demon ahead. They are horrific fel casters who see through their floating eyes and specialize in dark pacts. If you steal its power, Jace Darkweaver could use some of it in his ritual to spy on the Legion.\n\nBetter yet, you will gain its power by ripping it from its smoking corpse.", objectives = "Kill Inquisitor Baleful and take his power.", progress = "<name>. I would salute, but I am in the middle of a ritual.", completion = "An inquisitor's essence... perfect. Allari was right.\n\nNow to complete my ritual and spy on the Legion's leadership." }
WordHunterWoW_QuestEN[39050] = { title = "Meeting With the Queen", description = "We can use some of that essence to complete my ritual. You'll be able to spy upon the Legion leaders and see what they're planning.\n\nUse the nether crucible and complete the ritual.", objectives = "Complete the ritual to spy upon the Legion leaders.", progress = "If we don't know what they're planning, we're at a disadvantage fighting them.", completion = "That's new. She looks like some kind of spider demon. As if the Legion needed spiders..." }
WordHunterWoW_QuestEN[39051] = { title = "By Any Means", description = "We need to figure out what rock Varedis is hiding under - the only way we're going to do that is by getting inside this prison.\n\nDo what you must.", objectives = "Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis.", progress = "A truly impressive display.", completion = "Suramar is not far from here." }
WordHunterWoW_QuestEN[39052] = { title = "Blueprints Are Important", description = "The first thing we need to start building ships is a blueprint.  Lucky for you, I snatched some of the best ones from the Iron Docks before we broke out of there.  There is a one problem though...\n\nThese blueprints can get me in big trouble if the Iron Horde finds out.  I need you to memorize them and then destroy the evidence.  Let me know when you are done.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the blueprints to Crowler at your Garrison. He should be able to decode them." }
WordHunterWoW_QuestEN[39054] = { title = "Shipbuilding", description = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.\n\nLet's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, {class}, and then destroy the evidence. Let me know when you are done.", objectives = "Learn the blueprints and destroy the evidence.", progress = "You memorize those blueprints yet?", completion = "Hah, we'll make you a sea-dog yet. Let's get started on our first ship!" }
WordHunterWoW_QuestEN[39055] = { title = "Ship Shape", description = "Now that we have the blueprints, let's get started on our first ship, a transport!  Speak to me when you are ready to begin construction.", objectives = "Speak with Yanas to begin construction on a transport ship. Once complete, add it to your collection of ships.", progress = "Get that ship started yet?", completion = "We have our first ship!  Great work <name>.  I will get to work preparing her for travel to Tanaan right away." }
WordHunterWoW_QuestEN[39056] = { title = "Naval Commander", description = "We have come a long way in a short time on this shipyard, {name}.  Now it's time to run our first naval mission and control the seas of Draenor!\n\nI will need to setup shop from a high vantage point to plan out these seafaring missions.  Meet me near the shipyard entrance and we can get started.", objectives = "Find Merreck Vonder in your Shipyard and complete a Naval Mission.", progress = "Finish a naval mission yet?", completion = "Great work Commander!  You are going to make a great captain one day." }
WordHunterWoW_QuestEN[39057] = { title = "Command of the Seas", description = "Gul'dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we're going to need more than just a couple of transport ships. We must build an arsenal.\n\nWe need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!", objectives = "Upgrade to a Level 2 shipyard.", completion = "Well done, <name>. These docks are buzzing with activity.\n\n\n\nLet's do some damage." }
WordHunterWoW_QuestEN[39058] = { title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", objectives = "Defeat Erris the Collector in a pet battle." }
WordHunterWoW_QuestEN[39059] = { title = "To Catch a Banshee", description = "The strange-talking vrykul said I might be able to meet you here. I have orders from Greymane.  It seems he may have a lead on Sylvanas' location.\n\nHe's set up a camp near the base of the mountain. We've run into some troubles, though. It looks like the Horde may have homed in on our position.\n\nWe could use your help. You can take my gryphon. Just speak to me when you're ready to leave.", objectives = "Meet with Genn Greymane in Greywatch.", completion = "It is good you arrived when you did, <name>." }
WordHunterWoW_QuestEN[39060] = { title = "Combustible Contagion", description = "It is true that we may have a lead on Sylvanas. Though I want nothing more than to get my hands on the Banshee Queen, the situation here at Greywatch requires immediate attention.\n\nYesterday, a regiment of guards returned with word of Forsaken forces in the woods. Several of them bore signs of a blight, similar to the one we endured in Gilneas. It would appear these Forsaken seek to unleash this blight upon Greywatch.\n\nSeek out their caches and destroy them, before the blight overtakes us!", objectives = "Burn the Forsaken Blight Caches near Greywatch.", progress = "Have the caches been taken care of?", completion = "The deed is done. \n\nYou have done a great service to the worgen of Greywatch, <name>." }
WordHunterWoW_QuestEN[39061] = { title = "Whispers from the Dark", description = "We still have little knowledge of the Horde's activities in the region, but I'm hoping you can help change that.\n\nLately the woods have been crawling with Sylvanas' agents. The few we have taken out carried orders from her Dark Rangers, who are no doubt in command of her forces here.\n\nWhile you're on the hunt, keep an eye out for any scouting orders. They may help us pinpoint Sylvanas' objective in the area.", objectives = "Collect the Forsaken Scouting Orders from Dread-Rider Stalkers and Dread-Rider Plaguebringers near Greywatch.", progress = "What have you found?", completion = "Excellent. The puzzle is finally coming together. \n\nWe may not know why Sylvanas' forces are here, but I think we know where they are." }
WordHunterWoW_QuestEN[39062] = { title = "To Skold-Ashil", description = "We have her now! According to these reports, Sylvanas' forces are after something in Skold-Ashil - a vrykul town not far from here. We must make our way there and track her down.\n\nI had previously dispatched Commander Lorna Crowley and a detachment of Gilneas Brigade to scout the position. Meet up with her there and find out what Sylvanas is after.\n\nMeanwhile, I will muster the fleet to assault their outpost. We will have justice if I have to reduce their camp to rubble!", objectives = "Meet with Commander Lorna Crowley in Crowley's Overlook.", completion = "So the cavalry has arrived? \n\nGood, we must make haste if we wish to uncover Sylvanas' plot before it comes to bear." }
WordHunterWoW_QuestEN[39063] = { title = "Shielded Secrets", description = "It's obvious at this point that the Horde wants something in Skold-Ashil. Unfortunately we still don't know what they're after.\n\nWe think the secret lies with the shieldmaidens here, so we need to find out more about them. Some early scouting revealed that they have a method of carving their shields to tell their stories. \n\nGo into the city and find as many of these shields as you can. With luck, we will find what Sylvanas seeks.", objectives = "Examine 6 Engraved Vrykul Shields in Skold-Ashil.", completion = "Val'kyr, you say? This is worse that I had imagined. If Sylvanas is able to create more Val'kyr, there will be no limit to her armies!\n\nIt seems the vault is her goal. We must stop her!" }
WordHunterWoW_QuestEN[39067] = { title = "Upgrading The Fleet", description = "You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", objectives = "Collect 1000 garrison resources, 1000 gold and complete 15 naval missions.", progress = "Finding success on these new naval missions?", completion = "Great work!  We will get to work right away on the upgrade." }
WordHunterWoW_QuestEN[39068] = { title = "Naval Domination", description = "Our naval domination continues!\n\nHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", objectives = "Collect 2500 garrison resources, 2500 gold and complete 25 naval treasure missions.", progress = "Gather those resources yet?  I am ready to get this upgrade started!", completion = "Controlling the seas of Draenor is in our grasp!" }
