WordHunterWoW_QuestEN[39082] = { title = "Let's Get To Work", description = "Now that the shipyard is complete, we need to get busy making ships!  Solog ran off to the dry docks, why don't you meet him down there?  He said he had a plan.", objectives = "Meet Solog at the dry docks.", completion = "I love the smell of fresh-cut wood and tar! Are you ready to start construction?" }
