WordHunterWoW_QuestEN[39090] = { title = "Slay Them All!", description = "Find them, hunt them, kill them. Teach our enemies a lesson they'll never forget.", objectives = "Slay 200 enemy players.", completion = "NICE WORK. TOO BAD THE ALLIANCE IS STILL BEATING DOWN OUR GATES! GET BACK OUT THERE!" }
WordHunterWoW_QuestEN[39092] = { title = "Becoming the Ascendant", description = "Our course is now clear. We must enter the vault and prevent Sylvanas from obtaining the power to create more Val'kyr. \n\nThe entrance is barred, which is likely what has kept her out so far, but you may have already uncovered the key to this barrier.\n\nYou must become the next ascendant.\n\nComplete the rites as depicted on the shields and take down the barrier to the vault. I will send word to Greymane of our findings - he will wish to confront Sylvanas himself.", objectives = "Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.", completion = "It is good to see you, <name>. \n\nThe assault on Dreadwake's Landing fared poorly, and I had thought our cause lost until Crowley informed me of your success.\n\nNow, let's finish this!" }
