WordHunterWoW_QuestEN[39107] = { title = "An Even Bigga Score", description = "So these mooks in Tanaan, they be carryin' all manner of valuable treasures. It still be complicated, but I can give ya a lot more now!", objectives = "Obtain Dingy Iron Coins for Griftah.", progress = "So you've got every last one?", completion = "Eh, ya got dem all! Dat's wonderful for the both of us. I can give ya dis much..." }
