WordHunterWoW_QuestEN[39117] = { title = "Shriek No More", description = "Papa loved this village. He'd never hear of leaving, even in these dread times.\n\nBefore he died, he told me what attacked him: a monstrous falcon we call Rotbeak.\n\nYou're fighting these undead, aren't you? Will you avenge my father? If so, you can find the beast northwest of here, patrolling our western route to the sea.", objectives = "Find Rotbeak along the Bradensbrook, and collect the beast's head.", progress = "Papa always said the only way he'd leave here would be feet-first.\n\nI wish he'd been wrong.", completion = "Thank you. Grisly, eh? I think I'll mount it over the door.\n\nI want you to have this, too. Fresh-caught mossgill was Papa's favorite." }
WordHunterWoW_QuestEN[39118] = { title = "Lower Citadel Speed Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[39119] = { title = "Assault on Skold-Ashil", description = "<insert>You will receive:", objectives = "<insert>" }
WordHunterWoW_QuestEN[39120] = { title = "Vignette: Shield Forger", description = "", objectives = "" }
WordHunterWoW_QuestEN[39121] = { title = "Vignette: Haunted Manor", description = "", objectives = "" }
WordHunterWoW_QuestEN[39122] = { title = "Ending the New Beginning", description = "The Banshee Queen is here! I'd recognize those tainted arrows anywhere.\n\nThis is the moment we have been fighting for. Sylvanas will answer for her crimes against Varian Wrynn and the Alliance!\n\nTo arms!", objectives = "Confront Sylvanas in the Vault of Eyir.", completion = "You're awake! We nearly lost you there... \n\nIt's a good thing we managed to get you and Greymane out of there in time, otherwise we wouldn't have been able to reverse Sylvanas's poison. It's a shame she got away, but her plans in Skold-Ashil failed and we have you to thank for it. \n\nI'm sure Greymane will order a commendation for you once he is fully recovered. You did a great thing here, <name>. \n\nGilneas is in your debt." }
WordHunterWoW_QuestEN[39123] = { title = "Lion Stalkin'", description = "The hills are crawlin' with lions that stalk their prey from afar. These big cats will pounce at anything that catches their eye, including a {race}. \n\nWhile most would fall to such a formidable predator, anyone in my huntin' party would be able to best those beasts.\n\nProve you've got what it takes by taking down a few of those stalkers.", objectives = "Hunt Pinerock Stalkers and Prowlers in Pinerock Basin.", completion = "Not a scratch on ya that I can see. I bet those lions never saw ya comin'!" }
WordHunterWoW_QuestEN[39124] = { title = "Moose Shootin'", description = "Highmountain is home to wildlife that can't be hunted anywhere else in the world. Tell me, {name}, have you ever laid eyes on a moose before? \n\nThe roaming Elderhorn may look like gentle giants, but only a fool would underestimate their strength. \n\nThey should prove to be a good challenge, even for someone as experienced as you.", objectives = "Hunt Pinerock Elderhorn in Pinerock Basin.", progress = "Ya can't be huntin' Elderhorn if you're lingerin' around camp.", completion = "You've hunted the Highmountain Elderhorn and lived to tell about it. That's not a feat that most can say they've accomplished. Color me impressed." }
WordHunterWoW_QuestEN[39125] = { title = "Demon Destroyer", description = "The demons spreading this corruption must be dealt with. Kill their generals and their plans will unravel.\n\nI have a gift for you. This horn was given to me by Odyn himself, use it to strike down all that stand in your way.\n\nThe gods will surely smile upon you if you thwart the advances of Legion.", objectives = "Slay Doomcaller, Sneermaw, and Grinchain" }
WordHunterWoW_QuestEN[39126] = { title = "Cleansing the Fountain", description = "The blood from an impaled dreadlord is flowing into a fountain at the base of Valhallas. Following orders given by their \"God-King\" the vrykul are drinking from the fountain. \n\nThe demon blood is driving the vrykul mad and it's giving them greater power than they deserve.\n\nTake this acorn. Throw it into the fountain. My ravens will take care of the rest.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Cleanse the demon blood from the fountain." }
WordHunterWoW_QuestEN[39127] = { title = "Beyond the Wall", description = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes. It sounds like they are going after the root of the yaungol invasion.\n\nThe pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", objectives = "Speak with Taran Zhu at the Longying Outpost in Townlong Steppes.", completion = "Welcome to Townlong Steppes. If you insist on wandering in to the darkest places of Pandaria then far be it from me to not put you to good use." }
WordHunterWoW_QuestEN[39128] = { title = "Tanaan Vignette", description = "", objectives = "" }
WordHunterWoW_QuestEN[39129] = { title = "Ill Tempered", description = "<Prying the lid off the scroll case reveals a plan by the Iron Horde to use large fish in the oceans around Draenor to interfere with Alliance and Horde naval power. Incredibly, the plan seems to have already worked on smaller sharks, but only up to a point.>", objectives = "Take the Shark Brainwashing Plans to your garrison shipwright.\n\nProvided item:" }
WordHunterWoW_QuestEN[39130] = { title = "7.0 Val'sharah - River: Vignette: Purging the River - TRACKING - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39131] = { title = "Possessions of Power", description = "Echoes of a thousand worlds swirl in the palm of your hand. Its true value lies in the eye of the beholder.", objectives = "Seek those who may offer insight into the origins of the shard." }
WordHunterWoW_QuestEN[39132] = { title = "The New Chieftain", description = "So you are the one of whom Ebonhorn foretold. I thought you would be taller.\n\nOur High Chieftain Ulan has been slain by the drogbar when they seized the hammer.\n\nHis daughter, Mayla Highmountain, has now taken on the burden of High Chieftain.\n\nYou can find her on the northern bluff with what few forces we have left to defend this place.\n\nShe will have need of you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Mayla Highmountain.So you are the one of whom Ebonhorn foretold. I thought you would be taller.\n\nOur High Chieftain Ulan has been slain by the drogbar when they seized the hammer.\n\nHis daughter, Mayla Highmountain, has now taken on the burden of High Chieftain.\n\nYou can find her on the northern bluff with what few forces we have left to defend this place.\n\nShe will have need of you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39133] = { title = "No Time to Talk", description = "Dargrul has sent his pets to do battle with us.\n\nWe need to crush these elementals before their rage swarms into Thunder Totem.", objectives = "Destroy 8 Enraged Ambershard.", progress = "We will all be honorary masons if this keeps up much longer.", completion = "It has been a long time since the earth itself has moved against us like this." }
WordHunterWoW_QuestEN[39134] = { title = "Wrathshard", description = "The Underking has used the Hammer of Khaz'goroth to render the mountainside into a weapon against us. The hammer is a tool for creation, not a weapon for his amusement!\n\nEven now, his crystal servant, Wrathshard, is driving these elementals out of the mountain down upon my people.\n\nWe must hold the bridge against this onslaught.\n\nEnter the cave, find Wrathshard, and send him back to his master in pieces.", objectives = "Slay Wrathshard.", progress = "Dargrul always was a vile creature. I never realized to what extent until he got his hands on that hammer.", completion = "I suspect this is not the last of Dargrul's assaults. He is still learning the powers of the Hammer like a child with a new toy." }
WordHunterWoW_QuestEN[39135] = { title = "A Sundered Tribe", description = "Dargrul didn't just take the Hammer of Khaz'goroth. He slew the High Chieftain -- my father -- to get it.\n\nThere are some who claim our tribe died with my father, and they have gone their separate ways.\n\nBut you... you look like someone they might listen to. You might convince them to return or at least send reinforcements.\n\nCan you speak with the representatives of the three tribes?You will receive:", objectives = "Speak with the Rivermane, Bloodtotem, and Skyhorn chieftains." }
WordHunterWoW_QuestEN[39136] = { title = "Unused", description = "You've charged up the gun. Now it's time to use it. Go and confront the ghostly wizard Kiranys Duskwhisper, and drive him out of Bradensbrook.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Kiranys Duskwhisper at the haunted manor in Bradensbrook." }
WordHunterWoW_QuestEN[39138] = { title = "March Forth and Conquer", description = "You should make sure that we do not lose momentum, Highlord. There is still much to be done in Azsuna.\n\nWe have a map of the island set up near the front of the sanctum. Meet me there and you can delegate your forces to handle important tasks in the area.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Command Map to send your followers on three missions to Azsuna." }
WordHunterWoW_QuestEN[39142] = { title = "Testing a Theory", description = "Now that the Bloodstone has fed, I hope to use its power to bend the will of demons that would otherwise not be so easily controlled.\n\nOf course, this is all theory. I have never witnessed the direct effect of the Bloodstone's power on a demon. This is where you come in.\n\nI have procured a few imps that should make suitable test subjects. Use the Bloodstone on them and report back to me with your findings.", objectives = "Use the Bloodstone on an Imprisoned Imp.", progress = "Have you tested the Bloodstone yet? I have imprisoned a few imps in the cave behind me that should make suitable test subjects.", completion = "The subject died during the testing process? Well that was unexpected.\n\nNonetheless, you've held up your end of the bargain. I suppose it's time for me to fulfill mine." }
WordHunterWoW_QuestEN[39147] = { title = "6.2 Tanaan - PTR - Unlock Tanaan Debug", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39149] = { title = "A Village in Peril", description = "Another outsider? Some bloke named Jarod just went off to our village down the road claiming he might be able to help us with our problem.\n\nIf you're here to help as well, then you best speak to the Mayor.\n\nJust know this is a bad time, and he's got an itchy trigger finger.", objectives = "Speak to Mayor Heathrow at Bradensbrook.", completion = "We don't need any help, and we don't like strangers wanderin' around on our land." }
WordHunterWoW_QuestEN[39151] = { title = "Forging the Artifact", description = "We've certainly got our work cut out for us, but not to worry. There's nae weapon in existence that ye can't improve, legendary ones included!\n\nThis anvil's only powerful enough to imbue your artifact once before we'll need something better, but that'll have to do fer now.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Valgar's anvil to imbue your artifact with a new power." }
WordHunterWoW_QuestEN[39152] = { title = "Felwrought Annihilator Looted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39153] = { title = "Dreadwake's Dilemma", description = "The situation has taken a dire turn, {name}. We were unprepared for Greymane's sudden assault, with only a token force left behind at Dreadwake's Landing, and we are paying the toll.\n\nThe beach is now swarming with worgen infiltrators, and if the cannons breach our defenses, they will likely swarm in on us. We're spread too thin here to take the fight to them, but you could change that.\n\nWipe them out.", objectives = "Kill 10 Greywatch Saboteurs or Infiltrators in Greymane's Offensive.", completion = "It looks like the ravens will feast on worgen flesh today, <class>.\n\nWell done." }
WordHunterWoW_QuestEN[39154] = { title = "To Skold-Ashil", description = "Thanks to your initiative, {class}, the situation at Dreadwake's Landing is under control. We have no time to rest on our laurels, however - Sylvanas's mission must still be carried out.\n\nThe dark rangers are heading up operations in Skold-Ashil from the tower overlooking the river junction. Seek them out there, and see if you can aid in completing this task.", objectives = "Meet with the dark rangers in Ranger's Foothold, outside of Skold-Ashil.", completion = "You seem surprised to find me here? I was surprised as well, to find that my forces were unable to even breach the city of these cursed vrykul! \n\nThe time has come to employ some different tactics, and your arrival couldn't have been more fortuitous." }
WordHunterWoW_QuestEN[39155] = { title = "Becoming the Ascendant", description = "It would seem that the engravings depict a rite of ascension, which allows the shieldmaidens to enter the vault. I believe we can use this to our advantage.\n\nYou must become the next ascendant.\n\nGo to the temple and perform the rites. Should you need to wade through the corpses of the shieldmaidens to do so, then so be it. \n\nFind me when you have completed this task, and we will take the vault for the Horde!", objectives = "Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.", completion = "The hero returns, and with the barrier disabled. I will see that you are commended for this. \n\nBut first, we must claim this vault!" }
