WordHunterWoW_QuestEN[39174] = { title = "Guiding Light Tutorialized", description = "", objectives = "" }
WordHunterWoW_QuestEN[39175] = { title = "Gems of the Apexis", description = "Listen, boss. I know you're a jewelcrafter. It's OK, I totally understand - I like money, too!\n\nI heard some of them bird fellas talking about some new gem-cuttin' device they got up in Tanaan. I'd be interested in checkin' it out myself, but I've got this whole shipyard mess to deal with right now.", objectives = "Find Sun-Sage Chakkis in Tanaan Jungle.", completion = "Yes?" }
WordHunterWoW_QuestEN[39176] = { title = "Mastery Of Taladite", description = "You - you are a gemcutter, no? You have the look of it in the twitch of your knuckles, in the focus of your eyes.\n\nI've been looking for something specific out here in Tanaan. We did not find it in our excavations in Arak... but the Apexis did not only dwell in Arak.\n\nWhat I am looking for is a storied Apexis construct that specialized in cutting gems. Be on the lookout, jewelcrafter. Such a marvel could benefit the both of us.", objectives = "Find the Apexis Gemcutting Construct.", completion = "<The construct lies amidst rubble, in disrepair.>\n\n<Judging by the tools on its manipulator arms, this construct does appear to be designed for gemwork.>" }
WordHunterWoW_QuestEN[39177] = { title = "Ruined Construct", description = "<It is in disrepair, but it is not broken. More than anything, the construct appears to be in need of re-energizing.>\n\n<A slot on the backside of the machine lies open, waiting to accept... whatever the Apexis used as a source of energy.>", objectives = "Repair the Apexis Gemcutter Construct by inserting 1000 Apexis Crystals.", completion = "Are you responsible for the return of this construct, <name>? It came barrelling through our camp like it was on a mission. It took three of the warders to tackle and subdue it, but for the time being, it appears content to stay here." }
WordHunterWoW_QuestEN[39178] = { title = "Moose on the Loose", description = "There's been chatter around the hunters' lodge about a crazed moose that is terrorizing the basin. \n\nI've never laid eyes on the beast myself, but they say its antlers are illuminated with magic. \n\nWhere other lesser hunters have tried and failed, you will prevail, and collect me a one-of-a-kind trophy!", objectives = "Collect the antlers of the cursed ancient spirit, Morashu.", progress = "I'm looking forward to hanging the antlers of an ancient spirit within the walls of the hunters' lodge!", completion = "These antlers are going to look quite impressive hanging from the walls of the hunters' lodge." }
WordHunterWoW_QuestEN[39179] = { title = "Bloodstone Bandit", description = "Something of personal value has been taken from me, and my work here cannot continue until I get it back.\n\nTo most it would appear to be an ordinary stone, but it is so much more than a simple rock - it lives and breathes!\n\nThe nearby naga have been snatching anything with any sort of magical significance, my stone included. Fortunately, they do not know how to access its power.\n\nReturn my stone to me, and I will consider your request for help.", objectives = "Recover Kira's Bloodstone from Narashi Spitescale.", progress = "Have you recovered my Bloodstone yet?", completion = "You're quite resourceful. I can see why Ritssyn likes to send you on errands." }
WordHunterWoW_QuestEN[39180] = { title = "Warchief's Command: Zangarmarsh!", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", objectives = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", completion = "Welcome to Cenarion Refuge, <name>.  I hope you've come to aid us in our mission.  We've much work ahead of us." }
WordHunterWoW_QuestEN[39181] = { title = "Hero's Call: Zangarmarsh!", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", objectives = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", completion = "Welcome to Cenarion Refuge, <name>.  I hope you've come to aid us in our mission.  We've much work ahead of us." }
WordHunterWoW_QuestEN[39182] = { title = "Warchief's Command: Terokkar Forest!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", completion = "I'm glad that Stonebreaker Hold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?" }
WordHunterWoW_QuestEN[39183] = { title = "FLAG - Immaculate Critical Strike Taladite", description = "", objectives = "" }
WordHunterWoW_QuestEN[39184] = { title = "FLAG - Immaculate Haste Taladite", description = "", objectives = "" }
WordHunterWoW_QuestEN[39185] = { title = "FLAG - Immaculate Mastery Taladite", description = "", objectives = "" }
WordHunterWoW_QuestEN[39186] = { title = "FLAG - Immaculate Multistrike Taladite", description = "", objectives = "" }
WordHunterWoW_QuestEN[39187] = { title = "FLAG - Immaculate Stamina Taladite", description = "", objectives = "" }
WordHunterWoW_QuestEN[39188] = { title = "Hero's Call: Terokkar Forest!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe King has commanded any able bodies of the Alliance to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", completion = "I'm glad that Stonebreaker Hold sent you.  The druids of the thicket have been slain!  Only myself and one other have survived, and he's insane.\n\nI don't know what happened, but I intend to get to the bottom of it.  Whatever it was, it happened quickly and feels unnatural.\n\nWill you help me?" }
WordHunterWoW_QuestEN[39189] = { title = "Warchief's Command: Nagrand!", description = "We have lost contact with the druids of the Cenarion Thicket\n\nThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", objectives = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.We have lost contact with the druids of the Cenarion Thicket\n\nThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.\n\nThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39190] = { title = "DEPRECATED", description = "The Knights of the Ebon Blade are ready. Place your hand upon the Orb of Command and Acherus will move to its new resting place.\n\nWe await your orders, Highlord.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Christen the Order of the Silver Hand using the Libram of the Order in Light's Hope Sanctum." }
WordHunterWoW_QuestEN[39191] = { title = "Legacy of the Icebreaker", description = "The greatest warrior should wield the greatest weapons. Long ago a great king, Magnar Icebreaker, wielded weapons crafted from a scale of the mightiest dragon in the land. He should be here, but he is not. Instead he languishes in his tomb.\n\nHis son, Hruthnir, is here. He will lead you to the tomb. If Magnar can be saved, do so. Either way, return with his weapons.", objectives = "Deal with Magnar Icebreaker.", progress = "You have done well. You will bring many victories to these Halls.", completion = "A great deed was done today. I have gained a mighty <class>, and you a powerful artifact." }
WordHunterWoW_QuestEN[39192] = { title = "The Forge of Odyn", description = "This Forge has been working for longer than your race has existed; we might know a few things. Your weapon is powerful, it will take my personal forge in order to work it.\n\nWe can work the artifact to provide various improvements, provided you have enough experience with it. Let's give it a try shall we?", objectives = "Use the Forge of Odyn.", completion = "Your weapon has untold potential! You will need to get more acquainted with it first and we can work on it some more." }
WordHunterWoW_QuestEN[39193] = { title = "Hellfire Assault", description = "If you are to breach the walls of the citadel, you must first face siege equipment and forces led by Siegemaster Mar'tak.\n\nI wish you luck in gaining entry to Hellfire Citadel with your limbs intact.You will receive:", objectives = "Defeat the Hellfire Assault in Hellfire Citadel." }
WordHunterWoW_QuestEN[39195] = { title = "Gems of the Apexis", description = "Commander! I've noticed you have been keeping up with your jewelcrafting, despite all of this war going on. I find that to be most admirable.\n\nI overheard some of the arakkoa discussing a gemcutting device that they believe is located within Tanaan Jungle. They got their information from one named \"Chakkis.\"\n\nJust thought you might be interested.", objectives = "Find Sun-Sage Chakkis in Tanaan Jungle.", completion = "Yes?" }
WordHunterWoW_QuestEN[39196] = { title = "Warchief's Command: Nagrand!", description = "The Warchief has asked for any able bodied champions of the Horde to ride to the aid of Garadar.\n\nThe home of the Mag'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.\n\nReport to Captain Kroghan there and offer him what assistance you can. Garadar must not fall!", objectives = "Speak with Captain Kroghan at Garadar in Nagrand.", completion = "<Even though he endeavors to hide it, a look of relief spreads over Kroghan's face.>\n\nIt's about time you got here! Granted, you're not an army, but any able-bodied <race> than can wield a weapon or chant a spell is welcome here. The people of Garadar are kin to all the Horde and we are proud to shed our blood in their defense." }
WordHunterWoW_QuestEN[39197] = { title = "Hero's Call: Nagrand!", description = "The King has requested you represent him with the Kurenai settlement of Telaar in Nagrand.\n\nSeek out Warden Moi'bff Jill upon arrival.", objectives = "Speak with Warden Moi'bff Jill at Telaar in Nagrand on Outland.", completion = "You are welcome here in Telaar." }
WordHunterWoW_QuestEN[39198] = { title = "Warchief's Command: Blade's Edge Mountains!", description = "The Warchief is calling for champions to put an end to the ogre threat in Blade's Edge Mountains. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Gor'drek know of our plight. Any help he can spare would be most welcome.", objectives = "Travel to Thunderlord Stronghold in the Blade's Edge Mountains and speak with Gor'drek.", completion = "Thank you for coming, <class>. We have many enemies here and we can use all the help we can get." }
WordHunterWoW_QuestEN[39199] = { title = "Hero's Call: Blade's Edge Mountains!", description = "The Alliance forces of Sylvanaar in the Blade's Edge Mountains require reinforcements.\n\nThe King has asked for any able bodied members of the Alliance to journey to the mountains along the northern border of Zangarmarsh.", objectives = "Speak with Rina Moonspring at Sylvanaar in the Blade's Edge Mountains.", completion = "Thank you for coming. We could use more able bodies." }
WordHunterWoW_QuestEN[39200] = { title = "Lynore's Fury", description = "It appears Eira has a present for you, your first valarjar! You lead 'em, I'll make sure their weapons and armor are ready for war!You will learn:", objectives = "Speak with Lynore.It appears Eira has a present for you, your first valarjar! You lead 'em, I'll make sure their weapons and armor are ready for war!You will learn:" }
WordHunterWoW_QuestEN[39201] = { title = "Warchief's Command: Netherstorm!", description = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.\n\nThe Warchief feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas.\n\nArea 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", objectives = "Report to Rocket-Chief Fuselage at Area 52.", completion = "Hey there. Looking for work? Perfect!" }
WordHunterWoW_QuestEN[39202] = { title = "Hero's Call: Netherstorm!", description = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.\n\nThe King feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas.\n\nArea 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", objectives = "Report to Rocket-Chief Fuselage at Area 52.", completion = "Hey there. Looking for work? Perfect!" }
WordHunterWoW_QuestEN[39203] = { title = "Warchief's Command: Dragonblight!", description = "The Warchief wishes to reinforce the Horde's presence at Agmar's Hammer in the Dragonblight.\n\nThe fortress is a vital staging point for our assault on Icecrown and pivotal to containing the chaotic magic energies being released throughout the land.\n\nReport to Archmage Aethas Sunreaver.", objectives = "Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", completion = "What took you so long? Time waits only for Aspects, <race>.\n\nWe have much work to do, you and I." }
WordHunterWoW_QuestEN[39204] = { title = "Hero's Call: Dragonblight!", description = "Volunteers are needed to aid the Silver Covenant forces in the Dragonblight as they attempt to counter the chaotic arcane energies that threaten to rip the land apart.\n\nThose skilled in fighting dragons and undead are greatly welcome.\n\nThose willing to answer the call should report to Archmage Modera at Stars' Rest in Dragonblight.", objectives = "Speak with the Image of Archmage Modera at Stars' Rest.", completion = "I've been expecting you, <class>. We have much work to do, you and I." }
WordHunterWoW_QuestEN[39205] = { title = "The Twisted Garden", description = "", objectives = "" }
WordHunterWoW_QuestEN[39206] = { title = "Warchief's Command: Grizzly Hills!", description = "We've received a request for help from our base in the Grizzly Hills. Go to see Conqueror Krenna.\n\nShe's attempting to secure all of the natural resources. Just watch your back around her. The word is that she's aggressive even for an orc.\n\nYou can reach her by traveling east from Dragonblight.", objectives = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills.", completion = "Who are you?\n\nTell me why I shouldn't split you in two where you stand!" }
WordHunterWoW_QuestEN[39207] = { title = "Hero's Call: Grizzly Hills!", description = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.\n\nLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", objectives = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills.", completion = "Savage monsters - those Horde.\n\nPayback will come for what they've done. You can count on at least that much, <class>.\n\nNow, it's time to put you to work." }
WordHunterWoW_QuestEN[39208] = { title = "Zul'Drak", description = "Our death knight allies in Zul'Drak are in need of heroes to aid them in securing the troll lands from the Scourge.\n\nThose willing to aid should travel to the southwestern camp of Ebon Watch and speak with Stefan Vadu there.", objectives = "Report to Stefan Vadu at Ebon Watch in Zul'Drak.", progress = "What have you got there, <race>?", completion = "<Stefan reads the missive, then crumples it up and tosses it into the fire.>\n\nOld news. The Argent Crusade is - once again - late to the party. We've been tracking Drakuru since Grizzly Hills. He is slated for eradication." }
WordHunterWoW_QuestEN[39209] = { title = "Sholazar Basin", description = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.\n\nMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either.\n\nVolunteers are needed to mount an expedition to find the missing expedition. Monte's flying machine was last seen in the Wildgrowth Mangal south of the Suntouched Pillar in Sholazar Basin.", objectives = "Speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.", completion = "Aye, Hemet's here. He's at the camp, just go northwest toward the river and you'll soon see it. And for the love of the Light, lad, have him send someone to cut me down!" }
WordHunterWoW_QuestEN[39210] = { title = "The Magical Kingdom of Dalaran", description = "The Kirin Tor have moved their city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nThey believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest.\n\nWhen you arrive, seek out Archmage Celindra.", objectives = "Report to Archmage Celindra at The Violet Gate in Dalaran.", completion = "Welcome to Dalaran." }
WordHunterWoW_QuestEN[39212] = { title = "Sholazar Basin", description = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.\n\nMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either.\n\nArchmage Pentarus in Dalaran is standing by with a flying machine to take you to the last known location of Monte Muzzleshot.", objectives = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.", completion = "Aye, Hemet's here. He's at the camp, just go northwest toward the river and you'll soon see it. And for the love of the Light, lad, have him send someone to cut me down!" }
WordHunterWoW_QuestEN[39214] = { title = "The Eye of Odyn", description = "It is time to begin the war in Azeroth. We have prepared a tool for you to direct your warriors and your own operations from here. It is called the Eye of Odyn. \n\nIf you will follow me, I will take you to it, and someone that will help you use it.", objectives = "Go to the Eye of Odyn.", completion = "It has been a while since I've talked to the living. I hope you don't mind if I assist you. Being slain in combat has given me a calmer outlook in this emergency than other warriors." }
WordHunterWoW_QuestEN[39216] = { title = "Ready to forge Tracking Bit", description = "", objectives = "" }
WordHunterWoW_QuestEN[39217] = { title = "Don't Hate, Excavate!", description = "Well <name>, the good news is that our excavation team breached a chamber below right outside some sort of vault. The bad news is that the Horde were there too. Go down there and take a look.", objectives = "Harrison Jones in Ashran wants you to investigate the deepest part of the Ashran Excavation, The Breach.", completion = "Good work <name>! It's not a pretty situation down there." }
WordHunterWoW_QuestEN[39219] = { title = "The Iron Bulwark", description = "The Siegemaster within Hellfire Citadel has been working on a special machine she calls the Iron Reaver.\n\nWith any luck, she has not yet completed its construction, but you know what happens when we rely on luck...You will receive:", objectives = "Defeat the Iron Reaver in Hellfire Citadel." }
WordHunterWoW_QuestEN[39221] = { title = "Pits of Mannoroth", description = "In the Hellfire Citadel, they work to corrupt a magnaron with fel energy within the Pits of Mannoroth.\n\nIf you delve into the fel pools of that place, be on your guard.", objectives = "Defeat Kormrok in Hellfire Citadel.", completion = "I wonder if dat magnaron fel into da pool. Get it, mon?" }
WordHunterWoW_QuestEN[39222] = { title = "Court of Blood", description = "A council of orc clans has assembled and must be adjourned... permanently.\n\nGurtogg Bloodboil of the Bleeding Hollow, Jubei'thos of the Burning Blade, and Dia Darkwhisper of the Shadowmoon clan can all be found within the accursed walls of Hellfire Citadel.You will receive:", objectives = "Defeat the Hellfire High Council in Hellfire Citadel." }
WordHunterWoW_QuestEN[39223] = { title = "Deadeye's Vision", description = "Kilrogg Deadeye has led his clan down a dark path that he cannot return from.\n\nDemon blood coursing through his veins, he awaits the moment of his death--or yours--in Hellfire Citadel.You will receive:", objectives = "Defeat Kilrogg Deadeye in Hellfire Citadel." }
WordHunterWoW_QuestEN[39225] = { title = "Maw of Souls", description = "Falling into the heart of the mausoleum in Auchindoun, Teron'gor gorged upon hundreds of draenei souls, becoming a bloated abomination in the process. \n\nNo longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", objectives = "Defeat Gorefiend in Hellfire Citadel.", completion = "I wouldn't know dat monster started off as an orc if Saurfang hadn't told me." }
WordHunterWoW_QuestEN[39226] = { title = "Iskar's Clutch", description = "I'm afraid I have bad news about someone we once trusted. The arakkoa known as Iskar has gone too far in his desire to regain flight, and has joined with Gul'dan to regain his highborn body.\n\nWith it came the price of fel corruption and being doomed to fall at your hands.You will receive:", objectives = "Defeat Shadow-Lord Iskar in Hellfire Citadel." }
WordHunterWoW_QuestEN[39227] = { title = "Amphitheater of the Eternal", description = "The Exarch betrayer, Socrethar, was defeated with the assistance of Lady Liadrin and Exarch Maladaar.\n\nBut, he has returned. His vile spirit  is now within the Soulbound Construct in Hellfire Citadel, and must be destroyed once again.You will receive:", objectives = "Defeat the Soulbound Construct  in Hellfire Citadel." }
WordHunterWoW_QuestEN[39228] = { title = "Temple of Tyranny", description = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.\n\nPurge this Eredar of darkness.", objectives = "Defeat Tyrant Velhari in Hellfire Citadel.", completion = "Anotha follower of da darkness falls before ya." }
WordHunterWoW_QuestEN[39229] = { title = "Grommash's Torment", description = "We believe Grommash has not yet accepted Gul'dan's offer, and may even have avoided drinking the blood offered to him.\n\nBut Gul'dan has set Fel Lord Zakuun on Grommash. This demon is Gul'dan's best-known torturer.\n\nI fear for Grommash. If he is turned, I fear for us all.You will receive:", objectives = "Defeat Fel Lord Zakuun in Hellfire Citadel." }
WordHunterWoW_QuestEN[39230] = { title = "The Felborne Breach", description = "Summoned by Gul'dan from the depths of the Twisting Nether, Xhul'horac is one of most powerful of the Void Revenants--a race of parasitic void-beings that tear holes through the planes of reality, consuming and absorbing the energies and beings within.\n\nGul'dan has twisted Xhul'horac, feeding him overwhelming fel energy, and using his powers to tear open the portals through which he plans to rally the forces of the Burning Legion.You will receive:", objectives = "Defeat Xhul'horac in Hellfire Citadel." }
WordHunterWoW_QuestEN[39231] = { title = "Destructor's Rise", description = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we had predicted.\n\nMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", objectives = "Defeat Mannoroth in Hellfire Citadel.", completion = "Dat bag of bones be gone again." }
WordHunterWoW_QuestEN[39232] = { title = "The Black Gate", description = "We have heard rumors that one of the strongest of the eredar could soon enter this world through the Black Gate.\n\nIf these rumors are to be believed, it could even be Archimonde the Defiler. Should he arrive uncontested, Draenor itself is likely to fall.", objectives = "Defeat Archimonde in Hellfire Citadel.", completion = "Ya saved Draenor from one of da strongest demons in all creation, Commander. Dey will sing songs of your victory." }
WordHunterWoW_QuestEN[39233] = { title = "Don't Hate, Excavate!", description = "At last <name>, you've arrived and not a moment too soon. Quick, go down into the mine and take a look at what we've discovered. You may run into some Alliance down there. It is a minor inconvenience that is easily remedied.", objectives = "Belloc Brightblade in Ashran wants you to investigate the deepest part of the Ashran Excavation, The Breach.", completion = "Good work <name>! You see the mess the Alliance has made I'm sure." }
WordHunterWoW_QuestEN[39234] = { title = "Peak Urgency", description = "BYou've been summoned by Master Mathias Shaw of SI:7. He's waiting for you in the depths beneath Dalaran. Be wary - there have been reports of disappearances in those sewers.", objectives = "Speak to Mathias Shaw in the sewers beneath Dalaran.\n\nBYou've been summoned by Master Mathias Shaw of SI:7. He's waiting for you in the depths beneath Dalaran. Be wary - there have been reports of disappearances in those sewers." }
WordHunterWoW_QuestEN[39235] = { title = "Buba", description = "", objectives = "" }
WordHunterWoW_QuestEN[39236] = { title = "Let's Get To Work", description = "Now that the shipyard is complete, we need to get busy making ships!  Solog ran off to the dry docks, why don't you meet him down there?  He said he had a plan.", objectives = "Meet Solog at the dry docks.", completion = "I love the smell of fresh-cut wood and tar! Are you ready to start construction?" }
WordHunterWoW_QuestEN[39241] = { title = "Shipbuilding", description = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.\n\nLet's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, {class}, and then destroy the evidence. Let me know when you are done.", objectives = "Learn the blueprints and destroy the evidence.", progress = "You memorize those blueprints yet?", completion = "Hah, we'll make you a sea-dog yet. Let's get started on our first ship!" }
WordHunterWoW_QuestEN[39242] = { title = "Ship Shape", description = "You want to take the fight to Gul'dan? You need a transport! Speak to me when you are ready to begin construction.", objectives = "Speak with Solog to begin construction on a transport ship. Once complete, add it to your collection of ships.", progress = "Get that ship started yet?", completion = "It is done. Quite the beauty! You provide the army, she'll get 'em where they need to go.\n\nI will prepare her for the trip to Tanaan." }
WordHunterWoW_QuestEN[39243] = { title = "Naval Commander", description = "You're a natural at this, {name}. You've got the salt in your veins. Now it's time to run our first naval mission and control the seas of Draenor!\n\nYou will want a high vantage point to plan out these seafaring missions.  I know a good spot just up the path behind us. Meet me near the shipyard entrance and we can get started on our first mission.", objectives = "Find Rolash Wavechaser at your shipyard and complete a Naval Mission.", progress = "Finish a naval mission yet?", completion = "Great work Commander!  You are going to make a great captain one day." }
WordHunterWoW_QuestEN[39245] = { title = "Upgrading The Fleet", description = "You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", objectives = "Collect 1000 garrison resources, 1000 gold and combat 15 naval missions.", progress = "Finding success on these new naval missions?", completion = "Great work!  We will get to work right away on the upgrade." }
WordHunterWoW_QuestEN[39246] = { title = "Naval Domination", description = "Our naval domination continues!\n\nHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", objectives = "Collect 2500 garrison resources, 2500 gold and complete 25 naval treasure missions.", progress = "Gather those resources yet?  I am ready to get this upgrade started!", completion = "Controlling the seas of Draenor is in our grasp!" }
WordHunterWoW_QuestEN[39247] = { title = "The Hunt", description = "This hunt is yours to lead, {name} - a select few Illidari will join you to make sure Varedis meets his end.\n\nThe rest of us must stay behind; a small team will have the best chance of making it to his hold undetected.\n\nWe will meet you at Krasus' Landing to see you off when you are ready.", objectives = "Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.", completion = "What of the others? Did they...?\n\nI see. They gave their lives for a worthy cause - the Twinblades will change the tide of this war, mark my words." }
WordHunterWoW_QuestEN[39248] = { title = "Hellfire Assault", description = "If ye want to breach the walls o' the citadel, ye must first face siege equipment and forces led by Siegemaster Mar'tak.\n\nGood luck gainin' entry to Hellfire Citadel with yer limbs intact.You will receive:", objectives = "Defeat the Hellfire Assault in Hellfire Citadel." }
WordHunterWoW_QuestEN[39249] = { title = "The Iron Bulwark", description = "The Siegemaster in Hellfire Citadel has been working on a special machine she calls the Iron Reaver.\n\nWith any luck, she hasn't yet completed its construction, but ye know what happens when we rely on luck...You will receive:", objectives = "Defeat the Iron Reaver in Hellfire Citadel." }
WordHunterWoW_QuestEN[39250] = { title = "Pits of Mannoroth", description = "In the Hellfire Citadel, they're corruptin' a magnaron with fel energy in the Pits o' Mannoroth.\n\nIf ye delve into the fel pools of that place, be on yer guard.", objectives = "Defeat Kormrok in Hellfire Citadel.", completion = "We can't handle too many more of those fel-corrupted beasts." }
WordHunterWoW_QuestEN[39251] = { title = "Court of Blood", description = "A council o' orc clans has assembled and must be taken care of, if ye know what I mean.\n\nGurtogg Bloodboil o' the Bleeding Hollow, Jubei'thos o' the Burning Blade, and Dia Darkwhisper o' the Shadowmoon clan can all be found within the accursed walls of Hellfire Citadel.You will receive:", objectives = "Defeat the Hellfire High Council in Hellfire Citadel." }
WordHunterWoW_QuestEN[39252] = { title = "Deadeye's Vision", description = "Kilrogg Deadeye has led his clan down a dark path that he cannot return from.\n\nDemon blood coursing through his veins, he awaits the moment of his death at yer hands in Hellfire Citadel.You will receive:", objectives = "Defeat Kilrogg Deadeye in Hellfire Citadel." }
WordHunterWoW_QuestEN[39253] = { title = "Maw of Souls", description = "Falling into the heart o' the mausoleum in Auchindoun, Teron'gor gorged upon hundreds o' draenei souls, becoming a bloated abomination in the process. \n\nNo longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", objectives = "Defeat Gorefiend in Hellfire Citadel.", progress = "I hope you make Gorefiend pay for his atrocities.", completion = "That was some kind of monster, wasn't it?" }
WordHunterWoW_QuestEN[39254] = { title = "Iskar's Clutch", description = "I'm afraid I have bad news about someone ye once trusted. The arakkoa Iskar has gone too far in his desire to regain flight, and has joined with Gul'dan to regain his highborn body.\n\nWith it came the price of fel corruption and being doomed to fall at yer hands.You will receive:", objectives = "Defeat Shadow-Lord Iskar in Hellfire Citadel." }
WordHunterWoW_QuestEN[39255] = { title = "Amphitheater of the Eternal", description = "The Exarch betrayer, Socrethar, was defeated with the assistance of Lady Liadrin and Exarch Maladaar.\n\nBut, he has returned. His vile spirit  is now within the Soulbound Construct in Hellfire Citadel, and must be destroyed once again.You will receive:", objectives = "Defeat the Soulbound Construct in Hellfire Citadel." }
WordHunterWoW_QuestEN[39256] = { title = "Temple of Tyranny", description = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.\n\nPurge this Eredar of darkness.", objectives = "Defeat Tyrant Velhari in Hellfire Citadel.", completion = "How does a vindicator fall so far from the light?" }
WordHunterWoW_QuestEN[39257] = { title = "Grommash's Torment", description = "We believe Grommash has not yet accepted Gul'dan's offer, and may even have avoided drinking the blood offered him.\n\nBut Gul'dan has set Fel Lord Zakuun on Grommash. This demon is Gul'dans best-known torturer.\n\nI fear for Grommash. If he is turned, I fear for us all.You will receive:", objectives = "Defeat Fel Lord Zakuun in Hellfire Citadel." }
WordHunterWoW_QuestEN[39258] = { title = "The Felborne Breach", description = "Summoned by Gul'dan from the depths o' the Twisting Nether, Xhul'horac is one o' the most powerful o' the Void Revenants--a race of parasitic void-beings that tear holes through the planes o' reality, consuming and absorbing the energies and beings within.\n\nGul'dan has twisted Xhul'horac, feeding him overwhelming fel energy, and using his powers to tear open the portals through which he plans to rally the forces o' the Burning Legion.You will receive:", objectives = "Defeat Xhul'horac in Hellfire Citadel." }
WordHunterWoW_QuestEN[39259] = { title = "Destructor's Rise", description = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we thought.\n\nMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", objectives = "Defeat Mannoroth in Hellfire Citadel.", completion = "Let's hope Mannoroth stays down longer this time." }
WordHunterWoW_QuestEN[39260] = { title = "The Black Gate", description = "We've heard rumors that one o' the strongest eredar might enter this world through the Black Gate soon.\n\nIf these rumors are to be believed, it could even be Archimonde the Defiler. If he arrives unchallenged, Draenor itself is likely to fall.", objectives = "Defeat Archimonde in Hellfire Citadel.", completion = "You have saved Draenor from one of the strongest demons in all creation, Commander. They will sing songs of your victory." }
WordHunterWoW_QuestEN[39261] = { title = "Call of the Illidari", description = "{name}, Kayn requests that you meet him at Krasus' Landing at once.\n\n<Kor'vas leans in close, her voice an urgent whisper.>\n\nYou must hurry. The Legion has eyes everywhere.", objectives = "Speak to Kayn Sunfury at Krasus' Landing.", completion = "We have much to do, and precious little time to do it." }
WordHunterWoW_QuestEN[39262] = { title = "Give Me Sight Beyond Sight", description = "Jace Darkweaver swears that for a split second he sensed a demonic presence up and behind us. He took some of our forces up to the cave just to the southeast to investigate.\n\nThey found nothing in the cave, but he is certain that something is amiss.\n\nWould you lend him your guidance, and more importantly, your spectral sight?", objectives = "Speak with Jace Darkweaver and then use your Spectral Sight ability to scan the cave for hidden demons.", progress = "<name>, we need you to scan the cave with your spectral sight.\n\nWe must know if there are Legion forces magically hidden within.", completion = "I KNEW that I'd sensed something foul!" }
WordHunterWoW_QuestEN[39263] = { title = "Ashran Excavation", description = "", objectives = "" }
WordHunterWoW_QuestEN[39264] = { title = "Bonus Objective: Ashran Excavation", description = "", objectives = "" }
WordHunterWoW_QuestEN[39265] = { title = "A Tiny Viking Helmet", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39266] = { title = "A Tiny Plated Helm", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39267] = { title = "A Tiny Ninja Shroud", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39268] = { title = "A Tiny Pirate Hat", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39269] = { title = "Never Alone", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[39271] = { title = "First Mission Sent", description = "", objectives = "" }
WordHunterWoW_QuestEN[39272] = { title = "Poisoned Crops", description = "After driving us from the farmland and infesting our crops with insects, the drogbar placed wicked totems that further poison our harvest.\n\nI can only hope that if you destroy them, we'll be able to heal the land using Jale's water magic.\n\nThank you for coming to help us, {name}. We are but simple farmers and fishermen, and have little prowess in combat.", objectives = "Destroy the drogbar Poison Idols.", progress = "The crops must be rid of this poison!", completion = "Thank you, <race>. Some of the crops still live. I believe with hard work and some of Jale's magical waters, we will not lose the entire harvest." }
WordHunterWoW_QuestEN[39273] = { title = "First Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39274] = { title = "Defend the Riverlands", description = "", objectives = "" }
WordHunterWoW_QuestEN[39276] = { title = "Strange Tools", description = "We are well on our way to building our first ship, but unfortunately, I am not the orc for the job.  I have no idea how to work with these human tools.  Your shipwright, Yanas Seastrike, is going to take over from here on out.\n\nI will be here at the dry docks if you need anything from me.", objectives = "Speak with Yanas Seastrike at the dry docks.", completion = "Interested in shipbuilding, I see?  I will do everything I can to help out, commander." }
WordHunterWoW_QuestEN[39277] = { title = "Spray and Prey", description = "The Bug Sprayer you recovered from Ormgul the Pestilent seems like it could give us an advantage against the drogbar and their insects.\n\nSpray the Drogbar with their own alchemy and watch their insects turn against them.", objectives = "Use the Bug Sprayer on drogbar in Whitewater Wash.", progress = "For this group of drogbar to turn against us after so many years of peace...", completion = "That worked quite well. I will hold on to this Bug Sprayer; it might be useful in the battles to come." }
WordHunterWoW_QuestEN[39278] = { title = "The Missing Manifest", description = "The water-proofed manifest contains some form of code for the most part, hiding the contents of the actual manifest. In the corner is a hastily scrawled note for a Mr. Knuckles. \"Shipment attacked, got away but boat is sinking. Get here before they do.\"\n\nThere are coordinates after that which lead to the sunken boat. Mr. Knuckles is definitely the kind of person you want owing you a favor, not the other way around.", objectives = "Find Mr. Knuckles' missing shipment.", progress = "Whatchoo got there?", completion = "Dis... is important! Where you find dis? We been lookin for dis stuff a while.\n\nYou got a dock now? Dat is VERY interesting. Maybe it time we became good friends? Da big fort you have is hard to sneak a spy-- er, forget I said dat.\n\nI gots an idea." }
WordHunterWoW_QuestEN[39279] = { title = "Assault on Mardum", description = "", objectives = "" }
WordHunterWoW_QuestEN[39282] = { title = "Second Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39283] = { title = "Felmouth Frenzy Lunker", description = "", objectives = "You got lunkers, <name>?", progress = "You got lunkers, <name>?", completion = "Wow, look at this thing.\n\nI think maybe I'll... actually, I'm not sure what to do with this. Is it really a fish?" }
WordHunterWoW_QuestEN[39285] = { title = "Second Mission Sent", description = "", objectives = "" }
WordHunterWoW_QuestEN[39286] = { title = "A Gruesome Task", description = "So here's the scoop, <name>. One of our agents has found an entrance to the portal world where Sargeras is keeping his personal felhound. We can't strike at him directly, but he's imbued a lot of power into this creature.\n That's the good news.\n\n The bad news, however, is outright gruesome. He's been feeding this monster on the brains of our allies, and that's all it will eat. As horrifying as it is, there's a fresh supply of corpses at the Broken Shore. Head down and get them.", objectives = "Retrieve 5 Severed Heads from the Broken Shore." }
WordHunterWoW_QuestEN[39287] = { title = "Deathtalon", description = "", objectives = "" }
WordHunterWoW_QuestEN[39288] = { title = "Terrorfist", description = "", objectives = "" }
WordHunterWoW_QuestEN[39289] = { title = "Doomroller", description = "", objectives = "" }
WordHunterWoW_QuestEN[39290] = { title = "Vengeance", description = "", objectives = "" }
WordHunterWoW_QuestEN[39292] = { title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.You will receive:", objectives = "Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade." }
WordHunterWoW_QuestEN[39294] = { title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.You will receive:", objectives = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath." }
WordHunterWoW_QuestEN[39296] = { title = "Crystal Fissure Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39299] = { title = "Black Marketeering", description = "Ya did us a real solid today, {name}. Boss Goya says you're big stuff in dese parts and we should keep an eye on --- uh, I mean we should be good buds. She's sent a repre... repre... del-e-g... um, a Black Market person to your garrison.\n\nGo say hi and stuff, and make sure to speak loudly when you plan what you're gonna do next.", objectives = "Speak with Zhang Yeoh in your garrison.", completion = "I am pleased to make your acquaintance, commander. If you ever wish to see the latest wonders that Madame Goya offers, please do not hesitate to speak with me. She sends this as a token of appreciation for your work in retrieving the manifest.\n\nRemember, Madame Goya only accepts bids in person. You must travel to meet her, if you wish to acquire any of her wares." }
WordHunterWoW_QuestEN[39303] = { title = "Third Mission Sent", description = "", objectives = "" }
WordHunterWoW_QuestEN[39304] = { title = "Third Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39305] = { title = "Empty Nest", description = "I've taken an inventory of the eggs you recovered. Some among the bunch may still have a chance to hatch.\n\nThey will need to be returned to an empty nest, and with any luck, an eagle will claim the eggs as her own and watch over them once again.\n\nThere is a nest just outside the entrance, on a rocky ledge above the cave.\n\nBe careful, {name}. The eggs are very delicate.", objectives = "Place the eagle eggs in the empty nest above the eastern entrance to Rockcrawler Chasm.", progress = "If there's any hope for those eggs hatching, they'll need to be returned to their nest.", completion = "Thanks to you, the great eagles of Highmountain will live on.\n\nOne of the eggs I thought was too damaged to salvage appears to be hatching..." }
WordHunterWoW_QuestEN[39306] = { title = "Call to Arms", description = "", objectives = "" }
WordHunterWoW_QuestEN[39307] = { title = "Mechasuit", description = "", objectives = "" }
WordHunterWoW_QuestEN[39308] = { title = "Bodyguard", description = "", objectives = "" }
WordHunterWoW_QuestEN[39309] = { title = "Arcane Orb", description = "", objectives = "" }
WordHunterWoW_QuestEN[39310] = { title = "Artillery Strike", description = "", objectives = "" }
WordHunterWoW_QuestEN[39311] = { title = "Bitestone Enclave Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39312] = { title = "Thunder Totem Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39313] = { title = "Bring the Reinforcements", description = "Greetings, Commander! With all of the fighting concentrated here in Tanaan, we've got the breathing room to divert some of our resources from nearby outposts to help make headway.\n\nJust let me know which reinforcements to call, and I'll get them here on the double!", objectives = "Talk to Angar Steelbellow and choose which reinforcements to bring to Tanaan.", progress = "Which allies should I call for?", completion = "Great! I'm always here if ye' ever want to change your mind!" }
WordHunterWoW_QuestEN[39315] = { title = "Bring the Reinforcements", description = "Hey there, Commander. You know, with all of the fighting concentrated here in Tanaan, we've got plenty of extra supplies just sitting around in our nearby outposts.\n\nYou just give me the order and I'll make sure some of them get sent our way!", objectives = "Talk to Fraggs and choose which reinforcements to bring to Tanaan.", completion = "A whole slew of artillery options at your hands! Living the dream.\n\nRemember, you can return to me at any time if you change your mind!" }
WordHunterWoW_QuestEN[39316] = { title = "Trapped Tauren", description = "The drogbar just rounded up those of us that they could and led them to a cave near here.\n\nIf you act quickly, I think they can still be saved. I know not what purpose they have for capturing our people.\n\nI shudder to think of it... in the deep places, the darkness rules.", objectives = "Free the captured Rivermane tauren.", progress = "They slew many of my brothers and sisters, but at least some managed to escape. Others, however, we captured.", completion = "They have returned relatively unharmed. Thank you, <name>." }
WordHunterWoW_QuestEN[39317] = { title = "Siege of Crawliac", description = "[ph] Defend the bluffs!You will receive:", objectives = "" }
WordHunterWoW_QuestEN[39318] = { title = "Nursing the Wounds", description = "I know why Mayla sent you. But as you have seen, the drogbar are not the only threat to Highmountain.\n\nI will not send forces to support until we deal with the minions of High Crawliac.\n\nIf you want to help, find my shaman. He was supposed to be dispersing these fires that are ravaging my village.\n\nHe was last seen heading for his spirit lodge to the south just before these Cinderwitches descended on us.", objectives = "Find Windmaster Julan and help extinguish the fires on Skyhorn.", progress = "These harpies are all over the place!", completion = "Julan is dead? He was a good shaman and full of life. Not as morbid as some of these spiritwalkers.\n\nI will miss his laughter tonight." }
WordHunterWoW_QuestEN[39321] = { title = "The Three", description = "When High Crawliac seized control of the harpies she placed 3 powerful and deadly witches in charge of the covens under her command.\n\nThese witches must die. Feel up for the challenge?\n\nHead into the Haglands behind me and find these three evil creatures.\n\nWe will cover you from the air and give your prey no sky to retreat.\n\nLook for us higher up the mountain, should you survive.", objectives = "Slay Ragi the Hexxer, Agara Deathsong, and Ugla the Hag.", progress = "Many Skyhorn have fallen to the witchcraft of these hags.", completion = "Well done. Now to cut the head off the snake, as it were." }
WordHunterWoW_QuestEN[39322] = { title = "The Witchqueen", description = "The time has come to assault High Crawliac, the Witchqueen.\n\nYou should know that one does not become queen of the harpies through kindness.\n\nThis creature has killed, betrayed, and tormented countless tauren, harpies, kobolds, and anything else she had to in order to secure her position as queen.\n\nCome, friend, let us finish this.", objectives = "Slay High Crawliac, the Witchqueen.", progress = "Without a queen, it will take the harpies many years before they can organize in such numbers again.", completion = "You have our respect and honor, <name>. I name you Skyfriend, and grant you free passage through our lands at your discretion." }
WordHunterWoW_QuestEN[39323] = { title = "Moozy's Sojourn", description = "My son! They took him! My wife and I split up to look for him. She went upriver and I went downriver.\n\nLeave me, please, and find Moozy... I might be okay... If you find Moozy, please bring him to my wife upriver.", objectives = "Find Moozy downriver in Whitewater Wash.", completion = "<Moozy squeals in delight at your presence.>" }
WordHunterWoW_QuestEN[39324] = { title = "Through the Portal", description = "Here's the good news: you're halfway there. Sorry you had to do that, but necessity is the mother of invention. See that portal down there? That's where the Hound lives. Get through it and find out what's going on in there.", objectives = "Use the Demonic Gateway to enter the Hound's Portal World." }
WordHunterWoW_QuestEN[39325] = { title = "Get Your Mix On", description = "Let's see... potion stains on your tabard, crushed herbs on your boots... I know a fellow alchemist when I see one!\n\nWe will do good work together, the two of us. I trust you're not averse to learning new tricks.\n\nBe sure to use my state-of-the-art alchemy table. I built her myself!", objectives = "Deucus Valdera in Dalaran wants you to craft some new potions. Merchant Patricia Egan in the alchemy shop can help you learn how.", progress = "I hope you're making good use of my alchemy table. It's my pride and joy!", completion = "I trust you were successful in making the potions? This will be the first step in building trust between us." }
WordHunterWoW_QuestEN[39326] = { title = "Missing Shipments", description = "Now that we've gotten to know each other, perhaps you can lend me a hand.\n\nMy weekly supply shipment was lost when my longtime courier--you know, old whatsername--was shot out of the sky over the shores of Azsuna. Surely a hardy sort like you could retrieve my lost goods.", objectives = "Alchemist Deucus Valdera in Dalaran wants you to locate supplies lost near the water in Azsuna.", progress = "I say, I do hope you were able to locate my lost supplies. How are we to build trust between us if you won't do everything I ask?", completion = "You found them! I had the utmost faith, of course. What's a few demons or naga to one so dedicated to advancing our craft?" }
WordHunterWoW_QuestEN[39327] = { title = "There's a Scribe for That", description = "Fine! I admit, even my considerable intellect can't translate the strange tome you discovered. No doubt the water smears made it illegible.\n\nSay, one of those dimwitted scribes down the block owes me a favor. This sort of busywork is just his cup of tea.", objectives = "Bring the Runewritten Tome to Professor Pallin in Dalaran.", progress = "I don't have time to translate tomes! That's what lesser professions are for.", completion = "It seems that twerp of a scribe has his uses after all! Let's see what he came up with..." }
WordHunterWoW_QuestEN[39328] = { title = "Ancient Knowledge", description = "The tome contains a wealth of ancient vrykul recipes! Why, I could be the first alchemist in untold ages to craft one! How fortunate for you, friend {name}, that you are here to bear witness to my greatness!\n\nAwful kind of that Svena person to die and leave her book for us, eh? Silly vrykul...", objectives = "Observe Deucus Valdera as he attempts one of the vrykul recipes.", completion = "My poor table!\n\nAll the implements we needed to mix the new potions were on that table. Without them, the new recipes are useless!\n\nFinding replacements will be no small task, but I'm confident you're up to it. If you need guidance, I can suggest places to look for the items we need.\n\nNow, off with you!" }
WordHunterWoW_QuestEN[39329] = { title = "A Dormant Burner", description = "I've heard that someone over in the engineering shop is selling a burner that might be usable. You could likely negotiate a fairer price than I could!\n\nThe shop is just across the street. I'll make a note on your map for you.", objectives = "Purchase a Depleted Leyflame Burner from Hobart Grapplehammer and bring it to Deucus Valdera in Dalaran.", progress = "It's a good thing the other crafters around here make such items. I couldn't imagine wasting my time on such endeavors.", completion = "Ah, this burner is exactly what we need for the alchemy table!\n\nWait just a moment... No, no, this will never do!" }
WordHunterWoW_QuestEN[39330] = { title = "Ley Hunting", description = "The leyflame burner you brought me is useless! This is why I never trust an engineer...\n\nThe burner needs to be charged in areas that resonate with ley energy before it can be used to craft our newfound alchemy recipes.\n\nLucky for us, Azsuna is rich with such power.", objectives = "Travel to key locations in Azsuna and use the Depleted Leyflame Burner to collect ley energy.", completion = "You imbued the burner with ley energy, eh? Let's have a look.\n\n<Deucus examines the leyflame burner.>\n\nYes, this will do nicely! A crucial step in rebuilding the alchemy table." }
WordHunterWoW_QuestEN[39331] = { title = "Eye of Azshara: Put a Cork in It", description = "A thought occurred to me recently, {name}. The naga have been known to hoard all manner of potions, so they might have the sort of corks we need.\n\nIn my educated opinion, I believe the best place to start searching is around the Eye of Azshara!\n\nTry not to waste your time in there dealing with the naga's goings on, just look for some replacement corks.", objectives = "Go to the Eye of Azshara and retrieve the Advanced Corks for Deucus Valdera in Dalaran.", progress = "The sooner we get my supplies back, the quicker we can get back to real work.", completion = "What's this? The spoils from another of your adventures, eh? Let's have a look." }
WordHunterWoW_QuestEN[39332] = { title = "Furbolg Firewater", description = "Oh! I recognize these corks you brought me, {name}. I recently acquired several from a furbolg tribe in Val'sharah. They need sturdy corks to keep a tight seal on that potent firewater they brew.\n\nWe need more firewater potions--the corks would make an ideal addition to our alchemy table!", objectives = "Acquire skins of Smolderhide Firewater from the furbolg camp in Val'sharah. Bring them back to Deucus Valdera in Dalaran so he can make use of the corks.", progress = "Did you find more firewater potions? I bet it's tempting to take a swig!", completion = "These potions have the corks we need for the alchemy table. Another successful endeavor!" }
WordHunterWoW_QuestEN[39333] = { title = "An Imprecise Burette", description = "Here are your burettes. Should you ever be in the need of anything else, don't hesitate to ask.\n\n<Ms. Xiulan holds up the hair and continues to chuckle to herself.>", objectives = "Bring the Uncalibrated Malloric Burettes to Deucus in Dalaran.\n\nProvided item:", completion = "Oh yes, these are fine. Fine indeed. Unfortunately they need to be calibrated in order to for us to get any accurate readings off of them." }
WordHunterWoW_QuestEN[39334] = { title = "Thanks for Flasking", description = "Here is your flask, good as new. A fair trade for those potions.\n\nBe a little more careful with your breakables next time!", objectives = "Take the repaired Dual-Chambered Mixing Flask to Deucus Valdera in Dalaran.\n\nProvided item:", completion = "Barm did his work, then? I hoped that tauren would come through!\n\nThis is a very useful addition to my alchemy table." }
WordHunterWoW_QuestEN[39335] = { title = "Neltharion's Lair: Potent Powder", description = "I've heard rumors that the ancient drogbar collected powder from the residue of dragon's breath. If it's true that Neltharion's Lair lies somewhere below us, it seems a likely source.\n\nGo there and try to find a replacement for my powder.", objectives = "Acquire Precipitating Powder in Neltharion's Lair and bring it to Deucus Valdera in Dalaran.", progress = "What have we here?", completion = "You... you found some? I'm impressed, and that doesn't happen easily I'll have you know.\n\nNow let's see what exactly it was that you found..." }
WordHunterWoW_QuestEN[39336] = { title = "We Need More Powder!", description = "The substance you brought me appears to be precipitating powder, a highly volatile reagent used by the vrykul in their recipes.\n\nThere are rumors that a vrykul elder named Katterin has built up quite a store of this powder. A substance this dangerous needs to be in our hands, not hers!", objectives = "Obtain Katterin's Alchemy Kit from Katterin the Blistered in Stormheim.", progress = "Let's hope you find the powder we need...", completion = "The ghost of Svena appeared again? Seems she doesn't take kindly to our attempts to learn these vrykul recipes...\n\nThankfully, the satchel you recovered has all the precipitating powder we require for the alchemy table. Another victory for us!" }
WordHunterWoW_QuestEN[39337] = { title = "Forlorn Filter", description = "Next on the list of things to replace are my filters. Now I'm sure you've concluded that an alchemist of my caliber uses only the finest of tools when mixing my potions.\n\nThe elves at the Temple of Elune in Val'sharah use Shaldorei silk to craft their robes. Perhaps they'd be willing to part with some for my filters.", objectives = "Speak with a Temple Priestess at the Temple of Elune to see if you can acquire some Shaldorei Silk.", progress = "A pile of tattered shaldorei silk lay on the chest.", completion = "This Shaldorei Silk appears to be torn into strips. The elves have apparently been using it as bandages for their fallen warriors." }
WordHunterWoW_QuestEN[39338] = { title = "Return the Filter", description = "What was torn has now been mended. I hope you put this Shaldorei silk to good use.\n\nNow, run along.", objectives = "Return the Mended Shaldorei Silk to Deucus Valdera in Dalaran.\n\nProvided item:", completion = "This Shaldorei Silk will make an excellent filter for the alchemy table. Nice work getting that nightborne to help us, <name>!" }
WordHunterWoW_QuestEN[39339] = { title = "A Fragile Crucible", description = "I have customers asking for alchemist stones, but I'm unable to make any until I replace my crucible.\n\nIn order to create a new one, we'll need a few things, but first we'll need a proper container. Something that can be augmented to withstand a demon's breath.\n\nThere's a place in Suramar which the Legion has occupied. There surely must be a device there we can take that will be suitable for our needs.", objectives = "Bring the Fragile Demonsbreath Crucible to Deucus Valdera in Dalaran.", progress = "I trust you're strong enough to handle a few demons?", completion = "You've found something quite intriguing here! Others have brought me fragments of such implements, but never so complete a sample.\n\nThis is going to require a lot of work..." }
WordHunterWoW_QuestEN[39340] = { title = "Lining the Crucible", description = "The first step in making this crucible useful is to restore the lining of its interior. That's going to require supplies you'll either gather yourself or obtain through trade with fellow adventurers.\n\nFelwort and yseralline seeds are familiar to herbalists.\n\nFelhide is obtained through skinning.\n\nBlood of Sargeras can be found all over the Broken Isles.", objectives = "Gather 1 Blood of Sargeras, 1 Felhide, 2 Felwort, and 100 Yseralline Seeds.", progress = "Restoring the lining of the crucible is no simple task, <name>.", completion = "It looks like you acquired everything we need. Give me a few moments to apply them to the interior.\n\n<Deucus works on the crucible, restoring its lining.>\n\nPerfect! The crucible is almost ready for use.\n\nJust one more tiny detail..." }
WordHunterWoW_QuestEN[39341] = { title = "Vault of the Wardens: Demon's Bile", description = "The key to a crucible like this is that it must be bathed in the foulest of fel energy. I hate to say it, but the most efficient method of accomplishing such a feat is to subject it to the bile of a demon.\n\nYes, I said the bile of a demon. Ready to get to work?\n\nIn the Vault of the Wardens, such a demon exists. An imp mother by the name of Grimoira. The door to her room is sealed by an invisible lock.\n\nI'd suggest bringing some Skaggldrynk with you. Use it when you get to her door.", objectives = "Craft a Skaggldrynk, then go to the Vault of the Wardens and bathe the crucible in the bile of Grimoira.", completion = "You did it! I must say, I was a bit concerned for your well-being, but once again you've proven resourceful.\n\nNow that the crucible's lining is restored and it has been bathed in demon's bile, it's ready for use on the alchemy table.\n\nWell done!" }
WordHunterWoW_QuestEN[39342] = { title = "The Price of the Black Market", description = "I may have what you're looking for, burettes you say? Not a very common item.\n\nFor that, I require a moderate favor. Nothing too big, just a few things really.\n\nA silver hair from a high-ranking archmage... the blood of a titan, and, oh... some wine and cheese.\n\nWhat?! I have appetites that need satiating.", objectives = "Collect a Silver Hair of Khadgar, a Blood of Sargeras, 5 Kaldorei Ginger Wine and 5 Moist Azsunian Feta.", progress = "Don't take too long now. Who knows who else may be in the market for your precious burettes.", completion = "You got the hair?!\n\n<Ms. Xiulan laughs audibly.>\n\nOh, I wish I could have been there to see the look on his face. Nevertheless, a deal's a deal." }
WordHunterWoW_QuestEN[39343] = { title = "Vault of the Wardens: Bendy Glass Tubes", description = "You find tubing formed from a bendable sort of glass. It appears as though Grimoira was using it to suck out the insides of her victims.\n\nIts magical properties, however, would seem ideal for use on an advanced alchemy table.", objectives = "Bring the Bendy Glass Tubes to Deucus Valdera in Dalaran.\n\nProvided item:", completion = "What's this you have for me, <name>? Say, these are some wondrous tubes! I bet I know a way to make them even better.\n\nI'll need you to temper these glass tubes in the fire of a dragon's breath under the light of a full moon on the equinox, then travel into the Emerald Dream and--\n\nOh, hold on. These tubes are perfect just as they are. Nevermind!\n\nSometimes I get a bit caught up in this whole adventuring business..." }
WordHunterWoW_QuestEN[39344] = { title = "Going Underground", description = "We're so close to replacing all my equipment, {name}. In order to make flasks again, we need to be able to precisely measure each ingredient.\n\nFor that, we need to replace my burette assembly. Unfortunately, burettes aren't easy to come by. We may be able to procure some though through other means by...\n\n<Deucus looks around and beckons you closer.>\n\nGoing underground, so to say. As in, the Black Market.\n\nGo see Ms. Xiulan. Mum's the word.", objectives = "See Ms. Xiulan about acquiring some new burettes for Deucus.", completion = "Well, now that we understand one another let's see what sort of arrangement we can come to." }
WordHunterWoW_QuestEN[39345] = { title = "Calibration Experts", description = "It will take the cooperation of several highly skilled sorts to calibrate these burettes for a variety of substances.\n\nChemist Emmara is an old friend from the Undercity who has helped me with similar endeavors.\n\nThunder Bluff smells like a barn to me, but Jana Winterhoof is an alchemist with exacting standards.\n\nAnd while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair.", objectives = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", completion = "Yes, I'd say these burettes look well-calibrated.\n\nI knew those three would be meticulous. Never underestimate the value of someone who obsesses over tiny details, <name>!" }
WordHunterWoW_QuestEN[39346] = { title = "Testing the Calibration", description = "Now that you have the burettes calibrated, it's time to test them out! The only way to be sure is by crafting a sufficient quantity of a variety of potions.\n\nGlamorous work? No, but the most important reagent in alchemy is a bit of elbow grease!", objectives = "Test the Malloric Burettes' calibration by crafting a variety of potions.", progress = "The only way to be sure the burettes are working is to use them!", completion = "That's quite an armload of potions you made! I think it's safe to say that these burettes are working as intended.\n\nI'll add them to the alchemy table." }
WordHunterWoW_QuestEN[39347] = { title = "Channeling Our Efforts", description = "While it's no secret my time is more valuable than... well, anyone's, I fear I must step in and help to replace my decoction conduit.\n\nYou will also play a crucial part in this, {name}, as my liaison with the blacksmiths. The thought of getting soot on my robes curls my toes.\n\nHere's a list of what we'll need done. Meanwhile I'll be out gathering the rest of what's needed.", objectives = "Talk to Alard Schmied about the list of things you need done.\n\nProvided item:", completion = "What's this then?\n\n<Alard takes the list and looks it over. His eyes widen as he reaches the bottom>\n\nI take it you don't fully grasp what it is that you need, do you? If this is truly what's required then we better get started." }
WordHunterWoW_QuestEN[39348] = { title = "Halls of Valor: The Prime Ingredient", description = "This first ingredient can only be obtained by visiting the next realm. Fortunately for us, there's a gate in Stormheim that can take you there.\n\nIn the Halls of Valor, there is a sand that's used for polishing their architecture. Eternity Sand, it's called. I'll need an ample amount of it as the base for the new glass.\n\nThis ingredient won't be easy to work with either. I'll need something to keep me going, you know, keep my stamina up.", objectives = "Retrieve the Eternity Sand from Heroic: Halls of Valor, craft a Flask of Ten Thousand Scars and return both items to Alard in Dalaran.", progress = "What a sight the Halls of Valor must be. You'll have to tell me about them sometime after your return.", completion = "Well done, <name>. Once we have everything together, I'll get started right away." }
WordHunterWoW_QuestEN[39349] = { title = "Black Rook Hold: Heavy, But Helpful", description = "The next ingredient on the list will supposedly add strength to the mix, according to Deucus. I've heard of it before, but haven't really used it.\n\nIt's called Sabelite Sulfate, and it's said the elves of Black Rook Hold use it in their blacksmithing.\n\nSomething like that won't just be lying around. You may have to delve deep into the hold to find it.\n\nAnd due to its weight, I may need a concoction of yours to compensate, something to give me a bit more strength.", objectives = "Retrieve some Sabelite Sulfate from Heroic: Black Rook Hold, craft a Flask of the Countless Armies and return both items to Alard in Dalaran.", progress = "I hope Deucus was right about these ingredients. This'll be the first time I'm making something like this.", completion = "<Alard takes the bag from you and peers inside.>\n\nSo this is the stuff? It's definitely true what I've heard. It is quite heavy." }
WordHunterWoW_QuestEN[39350] = { title = "Maw of Souls: A Hope in Helheim", description = "For this last ingredient, well...\n\n<Alard begins pondering for a moment, then nods his head.>\n\nYes, that's the only way. For this last one, you'll need to go to the land of the damned, Helheim.\n\nWell, not there exactly, but aboard the boat that ferries the dead across the Maw of Souls. Upon that boat may be the final ingredient we need.\n\nIt's called Dragur Dust. Keep an eye out for it.\n\nAlso, one needs to be quick when adding this ingredient. I'll need something to heighten my reflexes.", objectives = "Retrieve a crate of Dragur Dust from Heroic: Maw of Souls, craft a Flask of the Seventh Demon and return both items to Alard in Dalaran.", progress = "Were you able to board the ship? Did you find the dust?", completion = "It was there? You found some?\n\n<Alard takes the crate and opens it. He reels back from the smell.>\n\nYep, that's the stuff alright. By the light, does that reek." }
WordHunterWoW_QuestEN[39351] = { title = "The Emerald Nightmare: Rage Fire", description = "Now that we have all the ingredients assembled, we need one last thing.\n\nThe fire of my forges burn hot, but not hot enough to work these ingredients into glass. For that, we need more heat. The heat of a dragon, to be exact.\n\nI'm aware of one that has emerged from the Emerald Dream in a corrupted state. Corrupted or not, a dragon's heart burns with enough heat to melt the strongest of materials.\n\nBring me its heart and you'll have your conduit.", objectives = "Travel to the Emerald Nightmare and acquire Nythendra's Heart. Bring it to Alard in Dalaran.", progress = "I'm getting the mixture ready now. As soon as you return with the heart, I'll begin the construction.", completion = "<You hand the heart over to Alard. He places it within his forge and it begins to burn white hot.>\n\nPerhaps I should refer to you as Dragonslayer <name> from now on.\n\nJoking aside, I'll begin my forging." }
WordHunterWoW_QuestEN[39352] = { title = "Extinguishing the Sentinels", description = "You've made it. See that camp there? They've got some Legion Sentinels hiding in there, set to notify Sargeras any time his pet pooch gets hungry or craves attention. Shut them down.", objectives = "Extinguish the three Sentinels." }
WordHunterWoW_QuestEN[39353] = { title = "Test - New", description = "Test", objectives = "" }
WordHunterWoW_QuestEN[39354] = { title = "Wisp in the Willows", description = "Wisps are the spirits of our night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life.\n\nYou should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.", objectives = "Guide the Wisp through the Hidden Pools to grow 8 trees.", progress = "Any luck?", completion = "Oh thank you traveler! You have truly helped the forest today." }
WordHunterWoW_QuestEN[39355] = { title = "Equipment Blueprint: Trained Shark Tank", description = "This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.", objectives = "Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.", progress = "Those look like some equipment blueprints!", completion = "This is a blueprint for some high tech naval equipment.  I should be able to reverse engineer the plans and have this equipment available for you shortly!" }
