WordHunterWoW_QuestEN[39371] = { title = "Witches of the Sky", description = "", objectives = "" }
WordHunterWoW_QuestEN[39372] = { title = "Witch of the Wood", description = "You saved me at Riverbend not long ago. It is the reason I vouched for you as emissary to this tribe, and the only reason you're alive here now. I consider my debt to you paid.\n\nYou must prove yourself to the Bloodtotem chieftain before he will speak with you.\n\nWithin the forest is the Witch of the Wood, a harpy mother who recently descended into this territory. If you are able to defeat her and show her carcass to the Bloodtotem, they might allow you an audience with Torok.", objectives = "Defeat the Witch of the Wood.", completion = "The Bloodtotem don't often allow outsiders into their midst. Even asking them to give you an audience is a danger." }
WordHunterWoW_QuestEN[39373] = { title = "Hags of a Feather", description = "The drogbar you freed me from were unusually aggressive. The tribe in the nearby caves seems to be apart from the rest of them, but that didn't stop the Bloodtotem from going on the offensive just in case, capturing some of their number.\n\nThat move left the woods exposed to the harpies, however. Your help dealing with these witches would not go unnoticed by Torok. Bring back their feathers as proof of death.", objectives = "Collect 50 Hag Feathers from Witchwood Hags in the Witchwood.", progress = "Your size belies your strength, <name>.", completion = "I could hear them screeching from here. With this victory and the defeat of the Witch of the Wood, Torok will surely be willing to see you." }
WordHunterWoW_QuestEN[39374] = { title = "An Audience with Torok", description = "I should warn you that Torok is easily displeased and is hateful of outsiders. Be on your guard.\n\nWe will seek an audience with him at his tent at the Cliff's Edge. As the Rivermane Emissary here, I am afforded some protection against aggression, but they have made no such promises about you.", objectives = "Speak with Torok Bloodtotem.", progress = "I just hope the Bloodtotem don't cut us down for demanding their chieftain's time.", completion = "Strange that he would be in the cavern at this time... perhaps this is a good sign?" }
WordHunterWoW_QuestEN[39375] = { title = "Short-Supply Reward", description = "", objectives = "" }
