WordHunterWoW_QuestEN[39380] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[39381] = { title = "Rock Troll in a Hard Place", description = "We should leave this place while we have a chance. The Bloodtotem are amassing at their village to the north, and I believe they intend to kill my people.\n\nLet me know when you are ready to go, and I can take us to a safe place quickly.", objectives = "Speak with Navarrogg to meet him at a safe location.", completion = "You have little reason to trust me, but we have a common enemy in the Bloodtotem and I could use your help." }
WordHunterWoW_QuestEN[39382] = { title = "Perrexx the Corruptor", description = "Look around you, <class>. Corruption has befouled my valley. If Malfurion requires my presence to summon Ysera the Awakened, then I will surely aid him, but not until I have purged these demons from my lands.\n\nPerrexx the Corruptor is just ahead. Help me slay this fiend.\n\nStand by my side, and together we can rout these satyrs and their brethren.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Perrexx the Corruptor in the Moonclaw Vale." }
WordHunterWoW_QuestEN[39383] = { title = "Dishonored", description = "Xandris the Dishonored was among the first to betray his brethren and accept the curse of Xavius.\n\nDuring the great war, it was he who led the slaughter of many of my dearest friends.\n\nThe last time I met him on the battlefield he fled. Help me to finally dispense justice on this foul being.", objectives = "Slay Xandris the Dishonored.", completion = "Xandris has finally paid for his crimes, but his blood will not bring back the innocents he has slain." }
WordHunterWoW_QuestEN[39384] = { title = "The Corruptor", description = "Xandris has been slain, but there are others that must be dealt with if my grove is to be saved.\n\nDuring the great war, Kagraxxis took great pleasure in corrupting the lands he once called home.\n\nWere it not for the foolish mercy of my fellow druids, I would have slain him myself.\n\nFind the demon and bring justice upon him.\n\nI must entrust this task to you alone, for I sense an even darker presence here... one that requires my personal attention.", objectives = "Slay Kagraxxis the Corruptor.", progress = "Kagraxxis must be slain.", completion = "You have my thanks, <class>.\n\nIf not for your arrival I would have surely perished here." }
WordHunterWoW_QuestEN[39385] = { title = "A Gift for Greymane", description = "It looks like the Gilnean infiltrators brought some heavy ordnance to the fight. It's likely they intend to use them on the walls of Dreadwake's Landing.\n\nIf these could be rigged to Greymane's ship, it could make for a decisive end to his assault on the outpost.", objectives = "Plant 3 Gilnean Heavy Explosives onto the hull of Greymane's ship and detonate them at a safe distance.", progress = "<insert>", completion = "By the Dark Lady's favor, you did it! I witnessed the explosion from here - there's no way that Greymane could have survived such destruction! \n\nYou have done a great deed today for the Forsaken. Rest assured, it will be remembered." }
WordHunterWoW_QuestEN[39386] = { title = "Procuring a Prototype", description = "If Addie's going to be a more permanent member of the huntin' party, then she'll need some specialty gear for someone her size.\n\nMy munitions expert should have some ideas about what kind of weapon would best suit a gnome.\n\nStop by his camp and let him know that I'll be needin' a prototype soon.", objectives = "Find Razik Gazbolt at Icepine Point.", completion = "A gnome hunter, huh? Is that a joke?\n\nFine, fine. What the boss wants, the boss gets. I'll start working on a prototype as soon as I finish up my latest project." }
WordHunterWoW_QuestEN[39387] = { title = "The Skies of Highmountain", description = "When you are ready, join me at the base of Thunder Totem.\n\nI would be honored to have you at my side as my tribe once again swears its allegiance to the young Mayla.\n\nTogether, we are Highmountain!", objectives = "Speak with Lasan Skyhorn at the base of Thunder Totem.", progress = "Have you had any luck with Lasan?", completion = "The Skyhorn are with us? This day just got much better." }
WordHunterWoW_QuestEN[39388] = { title = "Moonclaw's Wisdom", description = "Our quick action today has stopped this aggression and saved my valley. As you requested, I will join Malfurion in the Grove of Cenarius.\n\nStill, there is much about these satyrs that I wish to tell you. This information would be most valuable to you.\n\nPlease meet me in my den before departing.", objectives = "Meet Thaon Moonclaw in his den." }
WordHunterWoW_QuestEN[39389] = { title = "It Hungers for Blood", description = "Bloodstones contain a great deal of power that can only be awakened once they are fed. \n\nYet this stone does not feast on fish and cakes. It hungers for blood; the more powerful, the better.\n\nThere's an infestation of demons just east of here. I need you to nourish my stone with their blood, so that I may unlock its power.", objectives = "Let the Bloodstone feed on the blood of demons.", progress = "Has the Bloodstone been sated yet?", completion = "The Bloodstone looks sated. Well done! Now it's time for a test..." }
WordHunterWoW_QuestEN[39390] = { title = "A Mysterious Text", description = "You found a water-logged tome near the bones of a massive creature. Written in an unfamiliar language, the book is adorned with runes and alchemical symbols. Perhaps another alchemist would be able to tell you more.", objectives = "Bring the Runewritten Tome to Deucus Valdera in Dalaran.", progress = "You found something down in Azsuna, <name>? Do share. It's so rare for something interesting to walk through the door of my quiet little shop.", completion = "Well now, this is intriguing! This book is... well, you see, it's obviously... uh..." }
WordHunterWoW_QuestEN[39391] = { title = "Pet Rocks", description = "I raise creatures born of the earth to help defend myself and my people. When I was captured, I ordered them to stay behind at our home, but they are often disobedient and likely tried to follow me.\n\nIf they did, I fear the Bloodtotem may have captured them, or worse. In my current state, I can't muster the strength to find them. If you find them, it would be much appreciated.", objectives = "Find Navarrogg's pets.", progress = "These beasts are not terribly bright, but they are loyal in their way.", completion = "Frag has fallen? The youngest of my pets was perhaps my most dear... curse the Bloodtotem and their cruelty!" }
WordHunterWoW_QuestEN[39392] = { title = "Bear Huntin'", description = "They say a single hair from the back of a bristlefur bear is sharp enough to cut a dwarf's beard. But if the fur doesn't kill ya, the maul will.\n\nSome lesser hunters have been a meal for those bears. \n\nShow me you're more than a snack and bring me back a few of those bristlefur pelts.", objectives = "Collect 4 Bristlefur Pelts within the Fields of An'she.", progress = "Procuring a few Bristlefur Pelts should help sell me on your huntin' skills.", completion = "These pelts are even sharper than I imagined. Well done, <name>." }
WordHunterWoW_QuestEN[39393] = { title = "Moonclaw Vale", description = "", objectives = "" }
WordHunterWoW_QuestEN[39394] = { title = "The Cipher of Damnation", description = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", objectives = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.", completion = "You have saved us all. The Cipher has become fragmented with Cyrukh's death. This means its guardians can hide the shards all over Draenor so the chances of piecing it together will be impossible.\n\nThis great victory will give us more time to stop Gul'dan but I shudder to think of what his next plan may be..." }
WordHunterWoW_QuestEN[39395] = { title = "Oronok's Offer", description = "", objectives = "I am glad you trusted me, <name>. I feel like a great weight has been lifted from me.\n\nI still owe Draenor a great debt for the part I played in Gul'dan's plot. My sons will aid the shamans in rebuilding and hiding the shards. Also, if you will allow it, I want to help you remove Gul'dan from this world.\n\nI will serve you... Commander." }
WordHunterWoW_QuestEN[39396] = { title = "NOT USED", description = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.You will receive:\n\nUpon completion of this quest you will gain:" }
