WordHunterWoW_QuestEN[39401] = { title = "Destroying the Competition", description = "One battle does not win the war, Commander.\n\nThat Transport isn't gonna hold up long against this Iron Horde navy.  We are going to need another ship.  Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers.  We should construct one of these ships immediately!", objectives = "Construct a Destroyer in your Shipyard and send it on a naval mission.", progress = "What is the status of the Destroyer?", completion = "They lured us right into their trap, Commander.  I want revenge!" }
WordHunterWoW_QuestEN[39404] = { title = "Destroying the Competition", description = "One battle does not win the war, Commander.\n\nThat Transport isn't gonna hold up long against this Iron Horde navy.  We are going to need another ship.  Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers.  We should construct one of these ships immediately!", objectives = "Construct a Destroyer in your Shipyard and send it on a naval mission.", progress = "What is the status of the Destroyer?", completion = "They lured us into a trap, commander.  I want revenge!" }
WordHunterWoW_QuestEN[39405] = { title = "Stories of Battle", description = "The writings carried by the priestess appear to be the first part of an epic poem describing the history of Ashildir, the ancient queen of the Valkyra. \n\nIf Ashildir has a connection to the shieldmaidens here, you may be able to use that to your advantage. \n\nThe answer to her involvement likely lies within the remaining text.", objectives = "Collect 8 verses of Ashilvara from Priestesses of Eyir in Skold-Ashil.", progress = "This appears to be the last verse.", completion = "The verses of the poem unfold the tale of Ashildir founding the shieldmaidens and bringing them to Skold-Ashil.\n\nIf these shieldmaidens revere the Valkyra queen as this would suggest, your dealings with her in Helheim may prove advantageous." }
