WordHunterWoW_QuestEN[39417] = { title = "Rating Razik", description = "Hemet is expecting an update on how my munitions research and development is going.\n\nI'm sure you'll be happy to tell my boss that my latest creation worked flawlessly!\n\nYou can find him at his camp near the hunters' lodge.", objectives = "Find Hemet Nesingwary at his Highmountain retreat.", completion = "It's good to hear that Razik is makin' some progress on his gadgets.\n\nMaybe if he could design a gun that aims itself, these amateurs infesting the basin would hit their targets for once." }
WordHunterWoW_QuestEN[39418] = { title = "Neltharion's Lair Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39419] = { title = "Hex-a-Gone", description = "The harpies are relentless in their pursuit to control the basin. They are able to craft bags of foul magic as quickly as we can destroy them.\n\nThe Skyhorn cannot gain the upper hand as long as their hexweaver lives. She must be stopped.", objectives = "Slay Hexweaver Akara.", progress = "Hexweaver Akara must be slain if the Skyhorn wish to gain the upper hand.", completion = "You have done the Skyhorn a great service, <name>." }
WordHunterWoW_QuestEN[39420] = { title = "Xavius Event TRACKING", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", objectives = "Defeat Botanist Darkgrove(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet." }
WordHunterWoW_QuestEN[39422] = { title = "Shipyard Report", description = "Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Lunarfall and check in with Merreck?  Every ship we build gives us another advantage over Gul'dan's new Horde.", objectives = "Return to your shipyard in Lunarfall.", completion = "We have been waiting for you, Commander." }
WordHunterWoW_QuestEN[39423] = { title = "Shipyard Report", description = "Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Frostwall and check in with Rolosh?  Every ship we build gives us another advantage over Gul'dan's new Horde.", objectives = "Return to your shipyard in Frostwall.", completion = "We have been waiting for you, Commander." }
WordHunterWoW_QuestEN[39424] = { title = "Everything!", description = "", objectives = "" }
WordHunterWoW_QuestEN[39425] = { title = "Stonedark Crystal", description = "Without my crystalline focus, my powers are weak. Those who captured me took it, and I know not where it is now.\n\nI'm sure one of the Feltotem has it. If you find it, please return it to me.", objectives = "Find Navarrogg's Stonedark Focus.", progress = "I have power over the earth without my crystal, but my power is much greater with it than without.", completion = "This will help me repair my broken body." }
WordHunterWoW_QuestEN[39426] = { title = "Blood Debt", description = "You have proven a much greater ally than the Bloodtotem ever were. With my focus crystal, my wounds are healed. I fear Frag was too far gone to revive.\n\nTorok and his Bloodtotem will suffer for what they have done to us. Let's pay them a visit before they can mount an attack against the cave of my people.", objectives = "Defeat Torok Bloodtotem at Torok's Bluff.", progress = "Drogbar are not violent by nature, despite our size. But the Bloodtotem crossed us, and they pay the debt in blood.", completion = "You have earned my trust. The Stonedark are not yet safe from our brothers led by Dargrul the Underking. We would willingly join Mayla Highmountain and her tauren against them." }
WordHunterWoW_QuestEN[39427] = { title = "The Eagle Spirit's Blessing", description = "The spear is linked to a spirit called Ohn'ahra. It has been tradition for us to speak with her and receive her blessing before going after the spear. She may also impart some knowledge.\n\nIf you would accompany me to Spiritwatch Point, I will summon the Eagle Spirit and ask for its blessing in the coming fight.", objectives = "Receive the Eagle Spirit's blessing at Spiritwatch Point in Highmountain.", progress = "We've done it!", completion = "We saved the Eagle Spirit and received her blessing. I feel even more confident we will get Talonclaw now!" }
WordHunterWoW_QuestEN[39428] = { title = "Satyr Line TRACKING", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", objectives = "Defeat Botanist Darkgrove(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet." }
WordHunterWoW_QuestEN[39429] = { title = "Assaulting the Haglands", description = "Proceed on foot into the Haglands and slay any harpies you find.\n\nQuell their numbers!\n\nWe will provide air support and force your prey to the ground where you can deal with them.\n\nShow these witches the fury of your... well... your \"you.\"", objectives = "Slay 8 Crawliac Harpies and 6 Skywhisker Loyalists in the Haglands.", progress = "It has been many years since we have had to enter the Haglands in force.", completion = "Haha! You are covered in the feathers of your enemies." }
WordHunterWoW_QuestEN[39430] = { title = "Flasking for a Favor", description = "You know, this mixing flask didn't suffer terrible damage. I'm positive it can just be repaired.\n\nI'm no expert in glass repair, but I've heard of someone who is--a tauren by the name of Barm Stonebreaker. He's a smith by trade, but those who know him say he was born to work glass.\n\nThose tauren don't work for free, so you may be in for some work yourself.", objectives = "Seek out Barm Stonebreaker at the Ironhorn Enclave in Highmountain.", progress = "You're looking for help? I hope you have something to offer my people in return, <race>.", completion = "Your gift is a noble gesture, <race>. Smithing can be a surprisingly perilous profession.\n\nNow let's see that flask.\n\n\n\nEh, that's not so bad. Give me a moment to fix it." }
WordHunterWoW_QuestEN[39431] = { title = "Mending the Filter", description = "Bringing back the cloth in such a manner would not be beneficial to Deucus.\n\nPerhaps there's a tailor here in Val'sharah who'd be willing to mend it for you.\n\nThe priestess who helped you earlier may know of such a person.", objectives = "Try to find the whereabouts of a tailor in Val'sharah who can help you mend the silk.", completion = "You dare request such a menial task from me? Surely you must be joking." }
WordHunterWoW_QuestEN[39432] = { title = "Unknowable Power", description = "The one they call Gul'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra'nak have already pledged themselves to Gul'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.", objectives = "Collect a Fel-Corrupted Apexis Fragment from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle.", progress = "This is simply the beginning of what you must do to save what remains of the Arakkoa.", completion = "As your archmage told me, the power that has warped these crystals comes from far beyond this world. I will need more help in discovering how to turn back the darkness inside my people." }
WordHunterWoW_QuestEN[39433] = { title = "Unseen Influence", description = "The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.", objectives = "Collect 10 Fel-Corrupted Apexis Fragments from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle.", progress = "I fear even your help may not be enough to avert the doom of the Arakkoa.", completion = "I will continue to need your help until this world is free of whatever terrible presence Gul'dan has invited to destroy us." }
