WordHunterWoW_QuestEN[39435] = { title = "Oubdob da Smasher", description = "", objectives = "" }
WordHunterWoW_QuestEN[39436] = { title = "Haglands Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39437] = { title = "Deep in the Cavern", description = "We're getting tired of those murlocs. They skitter around the cavern like they own it. They stole some of our most precious relics and got their fishy fins all over them. \n\nKill a few of them so they know they don't run things around here.", objectives = "Slay 8 murlocs in Stonedark Cavern.", progress = "Slippery little critters, aren't they?", completion = "I could hear their murlurulurls echoing in the cavern. Maybe they'll think twice before taking our stuff next time." }
WordHunterWoW_QuestEN[39438] = { title = "Guhruhlruhlruh", description = "The murlocs are usually pretty scared of us, but some bigger one led them into our cavern and they're getting too brave.\n\nKill their leader. I think its name is something like \"Guhruhlruhlruh.\"", objectives = "Defeat Guhruhlruhlruh.", progress = "Can you pronounce murloc names? I never can.", completion = "That ought to send some of the murlocs packing." }
WordHunterWoW_QuestEN[39439] = { title = "Stonedark Relics", description = "The murlocs managed to steal some of our sacred relics and carry them down into the lower cavern.\n\nWhile we warm up, do you think you could go find them?", objectives = "Recover the Chain of Resistance, Wheel of Fortitude, and Rod of Bearing.", progress = "We have possessed these relics for generations until the murlocs put their fishy flippers on them.", completion = "You found them! Not sure how you carried them all at one time..." }
WordHunterWoW_QuestEN[39440] = { title = "You Lift, Brul?", description = "Do you even lift? If you can carry these weights to the statue of Liftbrul and back, maybe we can talk.", objectives = "Carry the weights to the statue of Liftbrul and return to Damrul the Stronk.", progress = "Those arms fallin' off?", completion = "Stronger than you look, little one." }
