WordHunterWoW_QuestEN[39445] = { title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.You will receive:", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle." }
WordHunterWoW_QuestEN[39446] = { title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.You will receive:", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle." }
