WordHunterWoW_QuestEN[39472] = { title = "Cut Out the Heart", description = "This map points out the strategic locations of the Forsaken forces around Greywatch. A marker to the east indicates an apothecary camp where Dread-Riders are being supplied from.\n\nIf you were to take out the apothecary in charge of creating this plague, it could stem the invasion and prevent the Dread-Riders from spreading the plague any further.", objectives = "Kill Apothecary Curseheart in the Dread-Rider Incursion.", completion = "To think that the Forsaken were brash enough to brew their blight in our own backyard. With the loss of their apothecary, their invasion force is left without teeth. \n\nYou have done well, <name>." }
