WordHunterWoW_QuestEN[39509] = { title = "Bloodied Blades of Zeth'Gol", description = "Them Bleeding Hollow orcs do blood magic - like voodoo but it hurt more. They cut their own flesh. Most of 'em carry curved ritual blades for carvin' themselves up.\n\nBring me them blades, commander. We can turn their power against 'em.", objectives = "Collect 25 Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth'Gol.", progress = "Watch your back in Bleeding Hollow lands. They fight dirty.\n\n'Course, we fight dirtier.", completion = "<Denjai runs one of the blades along his thumb. A sinister smile spreads across his elongated face.>\n\nThese will do, commander. These'll do nice." }
WordHunterWoW_QuestEN[39510] = { title = "A Little Wetwork", description = "What be left of the Iron Horde is comin' to Tanaan through Ironhold Harbor. If we knew who was comin' and when, we could use our shipyard to cause some chaos.\n\nGo to Ironhold Harbor and fish up some intelligence!", objectives = "Collect 15 Iron Horde Naval Manifests from forces in Ironhold Harbor.", progress = "Whatcha learn for us, commander?", completion = "Yes, yes, this be the good stuff commander.\n\nI'll send a messenger with these to your shipyard. Don't you worry none, me hunters slip through this jungle like they was invisible." }
WordHunterWoW_QuestEN[39511] = { title = "Blood of Fallen Brothers", description = "Orcs that drink Gul'dan's poison turn into fel beasts. Soulless savages.\n\nLady Liadrin an' the Blood Knights think maybe there be a way back. They be wantin' samples of blood from freshly turned orcs. Get their blood, {name}!\n\nYou be findin' fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden is where you find the most.", objectives = "Collect 20 Vials of Fel Blood from fel orcs throughout Tanaan Jungle.", progress = "You bleed 'em dry, commander?", completion = "I get these to Lady Liadrin then.\n\nYou really think there be a way back for these monsters, commander? You got a brighter outlook then me, mon." }
WordHunterWoW_QuestEN[39512] = { title = "Secrets of the Shadow Council", description = "Gul'dan be growin' his Shadow Council like a spider spin a web. But some of this new blood, they not so smart. They write down the secrets but don't burn 'em.\n\nCatch his minions out in the open and bring their secrets back to me! You find them workin' with the arakkoa in da Ruins of Kra'nak or atop the Throne of Kil'jaeden.", objectives = "Collect 20 Shadow Council Missives from shadow council representatives in the Ruins of Kra'nak or the Throne of Kil'jaeden.", progress = "You find anything, commander?", completion = "This be just what we need! I get my people at work on these right away, commander." }
WordHunterWoW_QuestEN[39513] = { title = "Disarming Sha'naar", description = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals used to channel their magics. Now demons be lootin' the place. We gotta keep those crystals out of demonic hands, commander!\n\nAttack the mines behind the temple and grab them crystals.", objectives = "Collect 8 Unrefined Draenic Crystals from the mines located within the Temple of Sha'naar in Tanaan Jungle.", progress = "What you find up there, commander?", completion = "They don't look like much, do they?\n\nI put these in safekeeping, commander. The blood elves might know what to do with 'em." }
WordHunterWoW_QuestEN[39514] = { title = "Harnessing Their Power", description = "Ol' Grommash Hellscream found a way to weaponize the gronn. Vol'jin wants to know how.\n\nTravel to the Iron Front and kill one of them big beasties, then bring back its war harness. You might be needin' help.", objectives = "Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle.", progress = "Did you break one?", completion = "You lugged that thing all the way back here? You must got a bit of gronn-blood yourself, commander!\n\nWe send this to the goblins at Orgrimmar to take a look at." }
WordHunterWoW_QuestEN[39515] = { title = "Vengeance Will Be Mine!", description = "This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.\n\nQuickly, {name}, teach us what you have learned.", objectives = "Teach the Vengeance specialization to your assembled demon hunters.", progress = "We await your instruction, <name>.", completion = "I blame myself, <name>. Mannethrel was already struggling. It is a never-ending battle we all must endure... to control the fel energies that we have taken in.\n\nMaybe it would be best if you held off teaching the others for now. We can not afford to lose anyone else." }
WordHunterWoW_QuestEN[39516] = { title = "Cry Havoc and Let Slip the Illidari!", description = "This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.", objectives = "Teach the Havoc specialization to your assembled demon hunters.", progress = "We await your instruction, <name>.", completion = "I blame myself, <name>. Mannethrel was already struggling. It is a never-ending battle we all must endure... to control the fel energies that we have taken in.\n\nMaybe it would be best if you held off teaching the others for now. We can not afford to lose anyone else." }
WordHunterWoW_QuestEN[39517] = { title = "Fel Secrets - Havoc Spec Tracking Event", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39518] = { title = "Fel Secrets - Vengeance Spec Tracking Event", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39519] = { title = "Demonslayer of Tanaan", description = "Look to the north, {class}. The sky is turning a sickly green. Gul'dan's summoning portals are not yet at full strength, but already the stench of demon is on the wind.\n\nSlay them, {name}. Destroy as many beasts as you can before they find a way to Azeroth. The Temple of Sha'naar is infested, as is the Throne of Kil'jaeden, although you may find others wandering about the jungle.", objectives = "Slay 20 demons in Tanaan Jungle.", progress = "How many demons were slain by your capable hands?", completion = "How does it feel, <name>? To look the Burning Legion directly in the eye and to tell them... \"Not today.\"" }
WordHunterWoW_QuestEN[39520] = { title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.Upon completion of this quest you will gain:", objectives = "Defeat the Alliance at the event locations in Ashran and kill Grand Marshal Tremblade." }
WordHunterWoW_QuestEN[39521] = { title = "Continue the Domination", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.You will receive:", objectives = "Defeat the Alliance at the event locations in Ashran and kill Grand Marshal Tremblade." }
WordHunterWoW_QuestEN[39522] = { title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.Upon completion of this quest you will gain:", objectives = "Defeat the Horde at the event locations in Ashran and kill High Warlord Volrath." }
WordHunterWoW_QuestEN[39523] = { title = "Continue the Domination", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.You will receive:", objectives = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath." }
WordHunterWoW_QuestEN[39524] = { title = "Slay Them All!", description = "Find them, hunt them, kill them. Teach our enemies a lesson they'll never forget.Upon completion of this quest you will gain:", objectives = "Slay 200 enemy players." }
WordHunterWoW_QuestEN[39525] = { title = "Slay Them All!", description = "The Horde encroachment cannot be tolerated. Dwindle their numbers to the ground!Upon completion of this quest you will gain:", objectives = "Slay 200 enemy players." }
WordHunterWoW_QuestEN[39526] = { title = "Pressing the Attack", description = "We got Gul'dan's minions on the run, commander! If you be feelin' it, we should put some pressure on some of his other strongholds as well.", objectives = "Complete 2 bonus objective areas within Tanaan Jungle.", progress = "How goes the fight?", completion = "You done it, commander! Day by day, we be conquerin' this whole Jungle." }
WordHunterWoW_QuestEN[39527] = { title = "Wrath of Azshara Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39528] = { title = "Wrath of Azshara Heroic Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39529] = { title = "Tooth and Claw", description = "Beyond the meager shelter of these fortress walls, the jungle closes in. Can you feel it? That is the untamed wilderness, {class}, calling forth our primal instincts. There is no better way to feel alive than to court death.\n\nJoin me in the hunt, {name}! Collect teeth from the wild beasts. The ravagers in Thornmire, the raptors in Zorammarsh - even the sea creatures along the strand and the little podling plants themselves all have teeth. Bring them to me!", objectives = "Collect 100 Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle.", progress = "I trust the hunt goes well?", completion = "Oh, this is quite the collection. How many of these sunk into your flesh? Exhilarating, isn't it?" }
WordHunterWoW_QuestEN[39530] = { title = "The Forgening", description = "Your new weapon is very powerful, but my smiths have mastered crafting over thousands of years. Speak to Master Smith Helgar and see what improvements can be made.", objectives = "Speak with Master Smith Helgar in the Forge in Valhallas.", completion = "That artifact is amazing, I can already see the potential we can unlock." }
WordHunterWoW_QuestEN[39531] = { title = "7.0 Highmountain - Treasure 00x - Steamy Romance Novel", description = "", objectives = "" }
WordHunterWoW_QuestEN[39532] = { title = "Bringing Down the Iron Horde", description = "Ever since the fall of Blackrock Foundry, Gul'dan has been turning the Iron Horde into... something worse. The orcs who once flocked to Grommash's banner, through either fear or thirst for revenge, are now embracing the fel.\n\nWade into the battlefields of Tanaan and lay waste to Gul'dan's forces. Orc or fel orc makes no difference. Gut what remains of the Iron Horde!", objectives = "Slay 25 Iron Horde orcs in Tanaan Jungle.", progress = "Feel no remorse for the fallen, <name>. They made their choice.", completion = "You gave them the glorious death they craved, <name>. Soon Gul'dan will have no one left to do his dirty work." }
